window.READER_DATA={"title": "Sharh Adwa", "slug": "sharh-adwa", "pages": [{"n": 1, "paras": ["دراسات في فقه الدعوة - ١", "أضواء على الأصول العشرين للإمام حسن البنا", "بقلم عصام أحمد البشير", "مكتبة المنار الإسلامية"], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0001.png"}, {"n": 2, "paras": ["بسم الله الوهاب الودود"], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0002.png"}, {"n": 3, "paras": ["أَضْوَاء عَلَى الْأُصُولِ الْعِشْرِينَ لِلْإِمَامِ حَسَن الْبَنَّا"], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0003.png"}, {"n": 4, "paras": ["حقوق الطبع محفوظة ولا يحق لأية جهة أن تطبع أو تعطي حق الطبع لأحد سواء كان مؤسسة رسمية أو أفراد إلا بإذن خطي من المكتبة.", "قال الإمام أحمد بن حنبل: إذا اشترى الرجل من رجل شيئاً وهو يعلم أنه سرقه فقد شاركه. مسائل الإمام أحمد لأبي القاسم البغوي ص ٦٨", "الطبعة الأولى", "١٤١٠ه - ١٩٩٠م"], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0004.png"}, {"n": 5, "paras": ["مقدمة", "إن الحمد لله نحمده ونستعينه ونستغفره ونستهديه ونعوذ بالله من شرور أنفسنا ومن سيئات أعمالنا، من يهده الله فهو المهتد، ومن يضلل فلن تجد له ولياً مرشداً، وأشهد أن لا إله إلا الله وحده لا شريك له وأشهد أن محمداً عبده ورسوله.", "وبعد: فهذه أضواء كاشفة، ومعالم مبينة عن بعض ما تضمنته رسالة الأصول العشرين للإمام حسن البنا - رحمه الله - من غرر الفوائد، وفرائد القلائد، حيث اشتملت - على وجازتها - على منطلقات أساسية في البناء والتكوين، محررة على أصول السلف الصالح أهل القرون الفاضلة المشهود لها بالخير والإيمان والفضل والإحسان، مبنية على شمول الفهم، ودقة النظر، واعتدال الفكر، وأصالة المنهج، وشرعية التأصيل، وسنية الاتباع، وهي بذلك تمثل قاسماً مشتركاً في الفهم الذي ينبغي أن يلتقي عليه العاملون على اختلاف منازعهم، وتنوع اجتهاداتهم في تقدير أولويات المرحلة بالنسبة لدعوة الإسلام.", "وقد عمدت في هذا المبحث إلى ضم فقرات الأصول التي تندرج تحت قسم واحد، فجمعت مثلاً المواضع التي تناول فيها ما يتصل بالعقيدة وجعلتها في بند معالم المنهج في العقيدة عند الإمام البنا، وهكذا في بقية النقاط الأخرى.", "وقد اشتملت هذه الأقسام على ما يلي:", "١ - شرعية العمل الجماعي."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0005.png"}, {"n": 6, "paras": ["٢ - شرعية البيعة في العمل الجماعي.", "٣ - معالم المنهج في العقيدة.", "٤ - وسطية المنهج في مسألة المذهبية الفقهية.", "٥ - القواعد الكلية والآداب المرعية عند الخلاف.", "٦ - نظرة موضوعية حول التصوف.", "٧ - فقه الأمر بالمعروف وقواعد الإنكار.", "٨ - السياسة الشرعية وضوابط العمل السياسي.", "وهذا جهد المقل أسوقه بعلم مسترضع بثدي من العجز، وثدي من التقصير، وما عسى أن يبلغ الخاطر المكدود مع بضاعته المزجاة التي حقيق بحاملها أن يقال فيه تسمع بالمعيدي خير من أن تراه.", "والله من وراء القصد وهو يهدي السبيل.", "عصام أحمد البشير"], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0006.png"}, {"n": 7, "paras": ["شرعية العمل الجماعي", "العمل الجماعي جهاد شرعه الإسلام وأملته الضرورة العملية. وقد دلّ على مشروعيته نصوص الوحي، وقواعد الفقه، وآثار السلف، ومنطق الواقع، وضرورة التحدي، وسنّة الاجتماع الكونية. أما دلائل الوحي فقد تكاثرت واستفاضت بالترغيب في العمل الجماعي ترغيباً بيناً، واقترن ضمير الجمع في القرآن والسنة بالعزائم على فعل الخير ودعم الحق، وتنوّعت صور الاستدلال في الحض عليه والدعوة إليه، أسوق طرفاً منها:", "١ - الطلب الدال على وجوب الفعل: قال تعالى: ﴿ولتكن منكم أمة يدعون إلى الخير ويأمرون بالمعروف وينهون عن المنكر وأولئك هم المفلحون﴾(١) أي جماعة راشدة تقوم بمهمة الأمر بالمعروف والنهي عن المنكر، فليست الأمة أوزاعاً متفرقة، ولا أفراداً متناثرة، كما هي ليست جماعة مطلقة من كل قيد. قال ابن جرير الطبري: (أصل الأمة الجماعة تجتمع على دين واحد ثم يكتفى بالخبر عن الأمة عن الدين لدلالتها عليه كما قال جلّ ثناؤه: ﴿ولو شاء الله لجعلكم أمة واحدة﴾(٢) يراد به أهل دين واحد)(٣) فهي جماعة مؤتلفة ذات شخصية متميزة يحدوها هدف، وتضبطها أصول وتحكمها قواعد. قال في تفسير المنار: (إن الأمة", "(١) سورة آل عمران: الآية ١٠٤.", "(٢) سورة النحل: الآية ٩٣.", "(٣) تفسير الطبري ١٩٥/٢."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0007.png"}, {"n": 8, "paras": ["أخص من الجماعة فهي الجماعة المؤلفة من أفراد لهم رابطة تضمهم ووحدة يكونون بها كالأعضاء في بنية الشخص الواحد). والأظهر أن (من) في (منكم) لبيان الجنس فالأمر بالمعروف منوط بكل أفراد الأمة كل بحسبه.*", "٢ - الجماعة موضع للرحمة: قال تعالى: ﴿ولو شاء ربك لجعل الناس أمة واحدة ولا يزالون مختلفين إلا من رحم ربك ولذلك خلقهم...﴾(١) الآية. قال قتادة: (أهل رحمة الله أهل الجماعة وإن تفرقت ديارهم وأبدانهم)(٢). (وجاء عن طاوس وابن عباس في قوله تعالى: ﴿ولذلك خلقهم﴾ أي للرحمة خلقهم والجماعة وبه قال مجاهد والضحاك وقتادة)(٣) واستشهدوا بقوله تعالى: ﴿وما خلقت الجن والإنس إلا ليعبدون﴾(٤). وقال شارح الطحاوية الإمام علي بن أبي العز الحنفي: (فجعل أهل الرحمة مستثنين من الخلاف)(٥).", "٣ - الاعتصام بها عصمة من الاجتماع على ضلالة: قال تعالى: ﴿واعتصموا بحبل الله جميعاً ولا تفرقوا، واذكروا نعمة الله عليكم إذ كنتم أعداء فألف بين قلوبكم فأصبحتم بنعمته إخواناً وكنتم على شفا حفرة من النار فأنقذكم منها كذلك يبين الله لكم آياته لعلكم تهتدون﴾(٦). قال ابن كثير في قوله: (ولا تفرقوا) أمرهم بالجماعة ونهاهم عن التفرقة... ثم قال: وقد ضمنت لهم - أي الآية - العصمة عند اتفاقهم من الخطأ كما وردت بذلك الأحاديث المتعددة(٧) وقد ذكر الحافظ ابن أبي عاصم طرفاً في كتاب السنّة منها حديث: «إن الله أجار أمتي من أن", "* ومنهم من يرى أنه فرض كفاية.", "(١) سورة هود: الآية: ١١٨ - ١١٩.", "(٢) تفسير ابن كثير ٤٦٦/٢.", "(٣) تفسير ابن كثير ٤٦٦/٢.", "(٤) سورة الذاريات: الآية ٥٦.", "(٥) شرح العقيدة الطحاوية ص ٥١٤.", "(٦) سورة آل عمران: الآية ١٠٣.", "(٧) تفسير ابن كثير ٣٩٠/١."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0008.png"}, {"n": 9, "paras": ["تجتمع على ضلالة»(١) وجاء عن ابن مسعود: (عليكم بالجماعة فإن الله لا يجمع أمة محمد ﷺ على ضلالة)(٢) - وهذه صفة خصيصة لهذه الأمة تشريفاً لها وتعظيماً لقدرها وقد انتزع الشافعي الدلالة من قوله تعالى: ﴿ومن يشاقق الرسول من بعد ما تبين له الهدى ويتبع غير سبيل المؤمنين نوله ما تولى ونصله جهنم وساءت مصيرا﴾(٣) على كون الإجماع حجة تحرم مخالفته، ويتعين المصير إليه. وبين الإجماع والاجتماع والجماعة من وشائج القربى ما لا يخفى.", "٤ - أنها ميراث الرسل والأنبياء ومنهاجهم في البلاغ: قال تعالى: ﴿وكأين من نبي قاتل معه ربيون كثير فما وهنوا لما أصابهم...﴾ الآية. قال ابن القيم: الربيون هنا الجماعات بإجماع المفسرين قيل من الربة بكسر الراء وهي الجماعة. قال الجوهري: (الربي واحد الربيين وهم الألوف من الناس)(٤).", "وقال تعالى: ﴿قل هذه سبيلي أدعو إلى الله على بصيرة أنا ومن اتبعني...﴾ الآية. قال ابن القيم: قال الفرّاء: (أنا ومن اتبعني يدعو إلى الله كما أدعو وهو قول الكلبي).", "وقد كان منهاجه عليه الصلاة والسلام في تشييد صرح دولة الإسلام أنه حرص لأول وهلة على الظفر والانحياز إلى جماعة تؤيده وتؤازره وتعينه على أمره وكان يقول للناس في المواسم - وهو يعرض نفسه عليهم -: «هل من رجل يحملني إلى قومه لأبلغ رسالة ربي، فإن قريشاً منعوني أن أبلغ رسالة ربي..» وما زال كذلك حتى قيض الله له رجالاً من الأوس والخزرج حملوه إلى المدينة وبذلوا المهج والأرواح - والغالي والمرتخص والنفس والنفيس فداء لدعوته -", "(١) قال الشيخ الألباني: حديث حسن وإسناده ضعيف لكنه يتقوى بما بعده ٤١/١ - ٤٢.", "(٢) قال الشيخ الألباني: إسناده جيد موقوف، رجاله رجال الشيخين ٤١/١ - ٤٢.", "(٣) سورة النساء: الآية ١١٥.", "(٤) مفتاح دار السعادة ١٢٦/١."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0009.png"}, {"n": 10, "paras": ["والاقتداء به في منهج الدعوة واجب كالاقتداء به في سائر التكاليف الشرعية الأخرى: ﴿واتبعوه لعلكم تهتدون﴾(١). وفي منهج الأنبياء ما أجمل اعتذار نبي الله هارون لأخيه موسى: ﴿إني خشيت أن تقول فرقت بين بني إسرائيل ولم ترقب قولي﴾(٢).", "٥ - الحض على الاتحاد والتعاون على الخير: قال تعالى: ﴿وتعاونوا على البر والتقوى﴾(٣) والجماعة من أخص الدلائل وأقوى الشواهد على خصال الخير، ووجوه البر، وسمات التقوى، وأبلغها أثراً، وأشملها استيعاباً، وأعمقها دلالة، وأصدقها تعبيراً عن خيرية الأمة. وهل من بر يجب التعاون عليه أعظم من إنفاذ أوامر الله وشرائعه والتمكين لدينه لتكون كلمة الله هي العليا.", "٦ - استجلاب عون الله ونصره وتأييده: قال تعالى: ﴿ولا تنازعوا فتفشلوا وتذهب ريحكم﴾(٤). وقال جل ثناؤه: ﴿إن تنصروا الله ينصركم ويثبت أقدامكم﴾(٥) ونصر الله يكون بطاعته فيما أمر وتصديقه بما أخبر، والانتهاء عما نهى عنه وزجر، ومن أوامره سبحانه ما يوجب اجتماع الكلمة ولزوم الجماعة والحرص عليها - إذ هي رحمة والفرقة عذاب -. جاء عن ابن عباس مرفوعاً: (يد الله مع الجماعة)(٦).", "٧ - في الجماعة حسن العاقبة وجميل المآل وكريم العقبى: قال تعالى: ﴿فأنجينا الذين كانوا ينهون عن السوء وأخذنا الذين ظلموا بعذاب بئيس بما كانوا يفسقون﴾(٧).", "(١) سورة الاعراف: الآية ١٥٨.", "(٢) سورة طه: الآية ٩٤.", "(٣) سورة المائدة: الآية ٢.", "(٤) سورة الأنفال: الآية", "(٥) سورة محمد الآية ٧.", "(٦) أخرجه الترمذي ٤٦٦/٤.", "(٧) سورة الاعراف: الآية ١٦٥."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0010.png"}, {"n": 11, "paras": ["وقد جاء في الأثر: (من أراد بحبوحة الجنة فليلزم الجماعة)(١).", "٨ - التحذير من مغبة التفرق وعاقبة التشتت بالتزام الجماعة: قال تعالى: ﴿مُنِيبِينَ إِلَيْهِ وَاتَّقُوهُ وَأَقِيمُوا الصَّلَاةَ وَلَا تَكُونُوا مِنَ الْمُشْرِكِينَ * مِنَ الَّذِينَ فَرَّقُوا دِينَهُمْ وَكَانُوا شِيَعًا كُلُّ حِزْبٍ بِمَا لَدَيْهِمْ فَرِحُونَ﴾(٢)، وقال تعالى: ﴿وَلَا تَكُونُوا كَالَّذِينَ تَفَرَّقُوا وَاخْتَلَفُوا مِن بَعْدِ مَا جَاءَهُمُ الْبَيِّنَاتُ﴾(٣). فهذا تحذير لهذه الأمة عما أصاب سالف الأمم من داء التفرق وبلاء التمزق بسبب الأهواء المردية والشبهات المضلة بعد مجيء العلم والهدى والحق.", "٩ - مقام الخيرية والشهادة على الناس منوطان بها: خيرية هذه الأمة منوطة بأسبابها. قال تعالى: ﴿كُنتُمْ خَيْرَ أُمَّةٍ أُخْرِجَتْ لِلنَّاسِ تَأْمُرُونَ بِالْمَعْرُوفِ وَتَنْهَوْنَ عَنِ الْمُنكَرِ وَتُؤْمِنُونَ بِاللَّهِ﴾(٤) والشهادة على الناس مقام رفيع وشرف عال لا يتأتى بالأماني... قال البخاري في صحيحه(٥) باب: (وكذلك جعلناكم أمة وسطاً) وما أمر النبي ﷺ: «بلزوم الجماعة وهم أهل العلم» وساق بسنده إلى أبي سعيد الخدري قال: قال رسول الله ﷺ: «يجاء بنوح يوم القيامة فيقال له: هل بلغت؟ فيقول نعم يا رب. فتسأل أمته هل بلغكم؟ فيقولون: ما جاءنا من نذير. فيقول من شهودك؟ فيقول محمد وأمته فيجاء بكم فتشهدون» ثم قرأ رسول الله ﷺ: «وكذلك جعلناكم أمة وسطاً - قال: عدلاً - لتكونوا شهداء على الناس ويكون الرسول عليكم شهيداً» قال الحافظ ابن حجر: (والآية التي ترجم بها احتج", "(١) رواه الترمذي عن عمر ٤٦٥/٤، ومسند أحمد ٢٣٠/١ - ٢٣١ وقال أحمد شاكر: إسناده صحيح.", "(٢) سورة الروم: الآية ٣٢.", "(٣) سورة آل عمران: الآية ١٠٥.", "(٤) سورة آل عمران: الآية ١١٠.", "(٥) كتاب الاعتصام بالكتاب والسنة ٣١٦/١٣."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0011.png"}, {"n": 12, "paras": ["بها أهل الأصول لكون الإجماع حجة لأنهم عدلوا بقوله تعالى (وسطاً) أي عدولاً ومقتضى ذلك أنهم عصموا من الخطأ فيما أجمعوا عليه قولاً وفعلاً(١).", "١٠ - وجوب الولاء لجماعة المؤمنين: قال تعالى: ﴿والذين كفروا بعضهم أولياء بعض إلا تفعلوه تكن فتنة في الأرض وفساد كبير﴾(٢) أي إن لم يوال بعضكم بعضاً كما فعل أهل الكفر حدثت الفتنة - أي الشرك - ووقع الفساد لتناصرهم وتخاذلكم، واجتماعهم وتفرقكم. ولهذا كان التوجيه الرباني: ﴿واصبر نفسك مع الذين يدعون ربهم بالغداة والعشي يريدون وجهه ولا تعد عيناك عنهم تريد زينة الحياة الدنيا...﴾(٣) الآية.", "١١ - لا قيام ببعض التكاليف إلا بها: كالعلم والتربية وجهاد العدو والسعي إلى إقامة الدين. قال تعالى: ﴿وقاتلوهم حتى لا تكون فتنة ويكون الدين كله لله﴾(٤). ﴿انفروا خفافاً وثقالاً وجاهدوا بأموالكم وأنفسكم في سبيل الله﴾(٥). وبها تحفظ هيبة الأمة، وتصان الشعائر المقدسة ويدفع العدو الصائل. هذه الإشارات القرآنية في الدلالة على لزوم الجماعة والاعتصام بها هي غيض من فيض، وقطرة من بحر، فالشواهد أكثر من أن تحصر، والبينات أوضح من الشمس في رابعة النهار وفيما ذكر كفاية ومقنع. من شواهد السنة في الحض على لزوم الجماعة والاستمساك بها:", "١ - حديث أبي هريرة مرفوعاً: (إن الله يرضى لكم ثلاثاً، أن تعبدوه ولا تشركوا به شيئاً، وأن تعتصموا بحبل الله جميعاً ولا تفرقوا، وأن تناصحوا من ولاه الله أمركم)(٦).", "(١) فتح الباري ٣١٧/١٣.", "(٢) سورة الانفال: الآية ٧٣.", "(٣) سورة الكهف: الآية ٢٨.", "(٤) سورة الانفال: الآية ٣٩.", "(٥) سورة التوبة الآية ٤١.", "(٦) أخرجه مسلم ١٣٤٠/٣، مالك في الموطأ ٩٩٠/٢، أحمد في المسند ٣٦٧/٢."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0012.png"}, {"n": 13, "paras": ["٢ - ومنها في حديث زيد بن ثابت مرفوعاً: (ثلاث لا يغل عليهن قلب مسلم: إخلاص العمل لله، ومناصحة ولاة الأمور، ولزوم جماعة المسلمين فإن دعوتهم تحيط من ورائهم)(١).", "٣ - وفي حديث حذيفة: (أن تلزم جماعة المسلمين وإمامهم)(٢).", "٤ - وفي حديث الحارث بن الحارث الأشعري مرفوعاً: (وأنا آمركم بخمس أمرني الله بهن: السمع والطاعة والجهاد والهجرة والجماعة فإن من فارق الجماعة قيد شبر فقد خلع ربقة الإسلام من عنقه)(٣).", "٥ - وفي حديث ابن عباس مرفوعاً: (يد الله مع الجماعة)(٤).", "٦ - وفي حديث افتراق الملّة: (وإن هذه الملّة ستفترق على ثلاث وسبعين فرقة، ثنتان وسبعون في النار وواحدة في الجنة هي الجماعة)(٥).", "٧ - وفي حديث معاذ بن جبل: (إن الشيطان ذئب الإنسان كذئب الغنم يأخذ الشاة القاصية والناحية وإياكم والشعاب، وعليكم بالجماعة والعامة)(٦).", "وفي نصوص السنة دلائل أخرى لا يتسع المقام للإفاضة فيها شرحاً وتبياناً، فليس المقصود هو الحصر والاستيعاب، وإنما هي إشارات قصد منها", "(١) رواه الترمذي ٣٤/٥، وقال حديث زيد بن ثابت حسن، وأحمد في المسند ١٨٣/٥، والدارمي ٧٤/١ - ٧٥.", "(٢) البخاري ٣٥/١٣ من فتح الباري.", "(٣) أحمد في المسند ٢٠٢/٤.", "(٤) الترمذي ٤٦٦/٤.", "(٥) حديث صحيح مشهور رواه أصحاب السنن والمسانيد بألفاظ عدة، انظر الجامع الصغير ١٩/١.", "(٦) أحمد في المسند وصححه الشيخ الألباني وقال: صحيح الإسناد. انظر شرح العقيدة الطحاوية ص ٥٧٨."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0013.png"}, {"n": 14, "paras": ["رد المسائل إلى أصولها الشرعية على أساس من منهج السلف الصالح. وما أحسن قول القائل: تكفي اللبيب إشارة مرموزة وسواه يدعى بالنداء العالي", "آثار السلف:", "١ - أخرج أحمد عن جابر بن سمرة أن عمر بن الخطاب قال في خطبته المشهورة التي خطبها بالجابية: (عليكم بالجماعة، وإياكم والفرقة، فإن الشيطان مع الواحد، وهو من الاثنين أبعد، ومن أراد بحبوحة الجنة فليلزم الجماعة)(١).", "٢ - وعن علي بن أبي طالب قال: (اقضوا كما كنتم تقضون فإني أكره الاختلاف حتى يكون للناس جماعة، أو أموت كما مات أصحابي)(٢).", "٣ - وروى محمد بن سيرين عن أبي مسعود الأنصاري أنه وصى من سأله لما قتل عثمان: (عليك بالجماعة فإن الله لم يكن ليجمع أمة محمد ﷺ على ضلالة)(٣). قال قتادة: (أهل رحمة الله أهل الجماعة وإن تفرقت ديارهم وأبدانهم)(٤).", "٤ - ومن الفقه العملي للسلف: ما ذكر ابن الجوزي عن أبي الوفاء ابن عقيل الحنبلي: قال: (رأيت في زماننا أبا بكر الأقفالي في أيام القائم إذا نهض لإنكار منكر استتبع معه مشايخ لا يأكلون إلا من صنعة أيديهم)(٥).", "(١) أحمد في المسند بتحقيق أحمد شاكر وقال: إسناده صحيح ١/ ٢٣٠ - ٢٣١، وانظر فتح الباري ٣١٦/١٣.", "(٢) أخرجه البخاري ٧٨/٩، ومسلم ٣/ ١٤٦٧ - ١٤٦٨.", "(٣) فتح الباري ٣٧/١٣.", "(٤) تفسير ابن كثير ٤٦٦/٢.", "(٥) تلبيس إبليس ص ١٤٥."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0014.png"}, {"n": 15, "paras": ["وكان هشام بن حكيم يأمر بالمعروف في رجال معه(١). وذكر عن عبدالرحمن بن محمد البغدادي أن: (له أتباع وأصحاب يقومون في الأمر بالمعروف والنهي عن المنكر)(٢).", "ومن أقوال أئمة العلم: ما قاله الشافعي: (ومن قال بما تقول به جماعة المسلمين فقد لزم جماعتهم، ومن خالف ما تقول به جماعة المسلمين فقد خالف جماعتهم التي أمر بلزومها، وإنما تكون الغفلة في الفرقة، فأما الجماعة فلا يمكن فيها كافة غفلة عن معنى كتاب ولا سنة ولا قياس إن شاء الله تعالى)(٣).", "وفي تأصيل شرعية العمل الجماعي المنظم يقول ابن تيمية: (وأما لفظ الزعيم فإنها مثل لفظ الكفيل والقبيل والضمين، قال تعالى: ﴿ولمن جاء به حمل بعير وأنا به زعيم﴾ فمن تكفل بأمر طائفة فإنه يقال هو زعيم. فإن كان تكفل بخير كان محموداً على ذلك، وإن كان شراً كان مذموماً على ذلك. وأما رأس الحزب فإنه رأس الطائفة التي تتحزب، أي تصير حزباً. فإن كانوا مجتمعين على ما أمر الله ورسوله من غير زيادة ولا نقصان فهم مؤمنون لهم ما لهم وعليهم ما عليهم … إلى فإن الله ورسوله أمرا بالاجتماع، ونهيا عن التفرقة والاختلاف)(٤).", "ومن القواعد الشرعية المرعية:", "١ - إن الوسائل إذا تعينت طريقاً لازماً لتحقيق المقاصد والغايات فإنها تأخذ حكمها من حيث الوجوب أي: (ما لا يتم الواجب إلا به فهو واجب)، ومعلوم أن النهوض بتكاليف الدين، وإنفاذ أحكامه وتطبيق حدوده، وحفظ محارمه متعينة على الأمة.", "(١) (٢) المنطلق ص ١٥٠ - ١٥١.", "(٣) الرسالة ص ٤٧٥ - ٤٧٦.", "(٤) الفتاوى ٩٢/١١، وانظر المنطلق ص ١٥٠ - ١٥١."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0015.png"}, {"n": 16, "paras": ["قال تعالى: ﴿والسارق والسارقة فاقطعوا أيديهما﴾ وقال سبحانه: ﴿الزانية والزاني فاجلدوا كل واحد منهما مائة جلدة﴾ وقال جلّ شأنه: ﴿كتب عليكم القصاص في القتلى﴾ ﴿ولكم في القصاص حياة﴾ ﴿وقاتلوهم حتى لا تكون فتنة ويكون الدين كله لله﴾ وغير ذلك من الآيات التي تحمل طابعاً من التكليف لا يتأتى بصورة فردية بل هو من التكاليف التي تتعين على الدولة المسلمة ومعلوم أنه لا سبيل إلى تحقيق ذلك إلا من خلال جهد جماعي، تتضافر فيه الجهود، وتعبأ فيه الطاقات وتلتحم فيه الصفوف.", "٢ - قياس الأولى: لئن كانت الجماعة متأكدة في بعض الشرائع التي يصح أداؤها بصورة فردية فإنها تكون قوية التأكيد، شديدة اللزوم فيما لا يصح إلا بوجه جماعي. كالجهاد والعلم والتربية وقيام الدولة.", "منطق الواقع: يرينا أن المرء ضعيف بنفسه، قوي بإخوانه، قليل بمفرده، كثير بأعوانه. ومن ثم قيل - كدر الجماعة لا صفو الفرد - والجهد الفردي مهما بني على الإخلاص وتلبث بحرارة العاطفة وصدق التوجه فإنه لا يستطيع النهوض بتبعات الدين وتكاليفه ليبلغ بها الأهداف المرجوة والآمال المبتغاة نظراً لضعف الإمكانات، وقصور الرؤية، وقلة التحمل ووهاء الطاقة عن الوفاء بهذه المهمة الجليلة والتبعة الجسيمة.", "أما الجهد الجماعي فمن شأنه حشد الطاقات وتعبئتها، وتوظيفها بما يتناسب وقدراتها التكوينية والموهبية وتنوعها.", "وفي العمل الجماعي سبر لغور النفس وإدراك لعللها وآفاتها، ومن ثم إصلاحها وتهذيبها، وتقويمها وتسديدها: رأيت الطين في الحمام يوماً بكفّ الحبّ أثّر ثم نَسْمُ فقلت أذاك مسكٌ أم عبير لقد صيّرتني بالحبّ مُغْرَمُ"], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0016.png"}, {"n": 17, "paras": ["أجاب الطينُ أني كنتُ تُراباً صحبتُ الوردَ صيرني مُكرَّمْ ألفْتُ أكابراً وازددتُ علماً كذا مَنْ عاشر العلماءَ يُكْرَمْ", "وكان بعض السلف يقول: (إن أحدنا ليلقى أخاه فيكون برؤيته عاقلاً أياماً).", "وقد كان جماعة من السلف يقصدون الرجل الصالح للنظر إلى سمته وهديه لا لاقتباس علمه، ذلك أن ثمرة علمه هديه وسمته. فبذلك يصفو القلب، وتسمو الروح، ويزكو الفؤاد، ويتجدد النشاط بما يقوي العزيمة ويعلي الهمة، كما قال نابغة بني جعدة: بلغنا السماء مجدنا وسناءنا وإنا لنرجو فوق ذلك مظهراً", "وفي العمل الجماعي تزوُّدٌ، بالخبرات النافعة والإضافة المفيدة، والتجارب النابضة الحية بما يعين على قطع المفاوز وتجاوز الصعاب.", "والعمل الجماعي كذلك منحة سانحة وهبة سابغة، لجزيل الأجر وتكاثر الحسنات حيث تنمو صور المعروف وذخائر البر، من إعانة المحتاج وتفقد الغائب، وعيادة المريض، وتفريج المكروب، وإغاثة الملهوف، وتلبية الدعوات، وإرشاد الحيران، وتذكير الغافل، وتعليم الجاهل، وهداية الضال، وتسلية المصاب وغيرها من صنائع المعروف: سأشكراً عمراً إن تراخت منيتي أيادي لم تُمنَنْ وإن هي جلَّتِ فتى غيرُ محجوبِ الغنى عن صديقه ولا مظهرِ الشكوى إذا النعلُ زلَّتِ رأى خُلتي من حيث يخفى مكانُها فكانت قذى عينيه حتى تجلَّتِ", "وقد قال أبو بكر الصديق رضي الله عنه مخاطباً الأنصار حين عرضوا على إخوانهم المهاجرين أنفس ما يملكون وأغلى ما يجدون، قام فيهم أبو بكر"], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0017.png"}, {"n": 18, "paras": ["خطيباً وقال جزاكم الله عنا معشر الأنصار خيراً فوالله ما مثلنا ومثلكم إلا كمثل طفيل الغنوي إذ يقول: جزى الله عنا جعفراً حيث أشرفت بنا رجلنا في الواطئين فزلتِ أبو أن يملّونا ولو أن أمّنا تلاقى الذي يلقون منّا لملّتِ فذو المال موفورٌ وكلُّ مُعَصَّبٌ إلى حُجراتٍ أدفأت وأظلتِ", "والجماعة من بعد ردء للفرد وظهير، تصون عرضه، وتحفظ دمه، وتذود عن حماه، وتذب عن كرامته من أن تطال بعدوان: إنا إذا عضَّ الثقاف برأس صعدينا لوينا نحمي حقيقتنا وبعض القوم يسقط بين بينا", "ضرورة التحدّي: ترينا، إن تكاتف أعداء الدين على اختلاف نزعاتهم، وتباين مشاربهم، وتعدد راياتهم يتربصون به الدوائر للنيل منه بما يستدعي ضرورة اجتماع أهل الحق ليقوى ساعدهم، ويشتد عضدهم ليقابل الجهد بجهد أقوى منه ﴿إن الله يحب الذين يقاتلون في سبيله صفاً كأنهم بنيان مرصوص﴾ وقد قال أبو بكر لخالد: (حاربهم بمثل ما يحاربونك به السيف بالسيف، والرمح بالرمح، والنبل بالنبل) فلا يعقل أن يقابل جهد جماعي بجهود فردية متناثرة: ﴿إن لا تفعلوه تكن فتنة في الأرض وفساد كثير﴾.", "سنة الاجتماع الكونية: الاجتماع سنّة من سنن الله تعالى في كونه الطبيعي والبشري - تآلفاً وترابطاً وانسجاماً - فكل مجموعة تتآزر وتتناصر لتحقيق ما خلقت له، وهكذا تتم مقاصد العيش: ﴿الذي أعطى كل شيء خلقه ثم هدى﴾."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0018.png"}, {"n": 19, "paras": ["وقد أحسن من قال: النمل تبني قراها في تماسكها والنحل تجني رحيق الشهد أعوانا", "الطيور لا تعيش أو تهاجر إلا في أسراب، والدواب والماشية لا تحيا إلا بقطعان، والأسماك لا تعيش إلا في الماء وقل ذلك في سائر المجموعات الكونية الأخرى - والإنسان ليس بدعاً من أمره - بل هو مدني بطبعه وحياته ومعاشه ومصالحه مرهونة بالتعامل مع غيره: الناس للناس من بدو وحاضرة بعضهم لبعض وإن لم يشعروا خدم", "(وكل بني آدم لا تتم مصلحتهم لا في الدنيا ولا في الآخرة إلا بالاجتماع والتعاون والتناصر على جلب منافعهم ودفع مضارهم، ولهذا يقال الإنسان مدني بطبعه، فإذا اجتمعوا فلا بد لهم من أمور يفعلونها يجتلبون بها المصلحة وأمور يجتنبونها لما فيها من المفسدة ويكونون مطيعين للآمر بتلك المقاصد والناهي عن تلك المفاسد)(١) فلئن كانت الجماعة من الضروريات اللازمة لمعاش بني آدم ومصالحهم العاجلة فهي أدعى وأطلب للقيام بما يترتب عليه فوز الآخرة والفلاح بها..", "والمؤمنون في حكم الإسلام ليسوا أفراداً منفصلين بل هم جماعة مؤتلفة فمن الطبيعي أن يتبع لقاء القلوب لقاء المشاركة في تحمل أعباء الدعوة إلى الله وهداية خلقه.", "لذا كان الطابع في الأمر التكليفي على المنحى الجماعي - كصلاة الجماعة - العيدين - الاستسقاء - الخوف - الكسوف - وفي الجمعة لا تصح إلا بها - والصيام مشاركة جماعية - والزكاة تكافل اجتماعي - والحج ملتقى عام - والجهاد والأمر بالمعروف والنهي عن المنكر ومدافعة أهل الباطل فمجمل الدعوة لا يتم بوجهه الأكمل إلا في جماعة.", "(١) الفتاوى بتصرف ٦٢/٢٨."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0019.png"}, {"n": 20, "paras": ["معنى الجماعة المسلمة أو جماعة المسلمين التي وردت بها النصوص", "رغم ظهور الدلائل النقلية والعقلية واستفاضة الشواهد وتواترها على شرعية العمل الجماعي - بله وجوبه - لاستئناف حياة إسلامية راشدة فإن غلواً في الفهم والتطبيق قد اكتنفا هذه القاعدة السليمة . . فمن هذا الغلو.", "١ - اعتبار جماعة ما من الجماعات الإسلامية اليوم أنها هي «الجماعة المسلمة» التي ورد ذكرها في الأحاديث أو هي الفرقة الناجية والطائفة الظاهرة إلى قيام الساعة.", "٢ - وأن من فارقها متوعد عليه بأن يموت ميتة جاهلية لأنه خارج عن جماعة المسلمين.", "٣ - قياس هذه الجماعة على جماعة الصحابة رضي الله عنهم.", "٤ - إعطاء قائد هذه الجماعة صلاحيات أمير المؤمنين في الدولة المسلمة. هذه بعض صور الغلو في فهم الجماعة التي جاءت بها النصوص، ونظراً لخطورة الآثار والمستلزمات المترتبة على هذا المسلك أحببت أن أشير إلى هذه المسألة بتوضيح معالمها من خلال كلام أهل العلم ثم بتأصيل الإمام البنا لها على نحو ما قرره الأئمة الأعلام. معنى الجماعة المسلمة: استفاضت لفظة الجماعة في كثير من النصوص فقد بين رسول الله ﷺ أن الفرقة الناجية عند تعدد الفرق واختلاف الأهواء هي الجماعة، وأن المفارق"], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0020.png"}, {"n": 21, "paras": ["لها متوعد بأن يموت ميتة جاهلية، وأنها هي المتعين لزومها كما في حديث حذيفة بن اليمان. فما المراد بالجماعة في كلام الشارع الحكيم؟. يجدر بنا أن نورد حديث الفرقة الناجية ونعرض له بشيء من الإبانة والتفصيل. عن معاوية بن أبي سفيان: قال: ألا إن رسول الله ﷺ قام فينا فقال: «ألا إن مَنْ قبلكم من أهل الكتاب افترقوا على ثنتين وسبعين ملة، وإن هذه الملة - وفي رواية: «وإن أمتي» - ستفترق على ثلاث وسبعين ملة، ثنتان وسبعون في النار وواحدة في الجنة وهي الجماعة»، وفي رواية: «من كان على مثل ما أنا عليه اليوم وأصحابي»(١). هذا الحديث من معجزاته عليه الصلاة والسلام لأنه أخبر عن غيب وقع. وقد تضمن هذا الخبر جملة أمور أشير إليها على سبيل الإجمال: الأول: قوله: «وستفترق أمتي» المراد بالأمة هنا أمة الإجابة وهم أهل القبلة، فإن اسم الأمة مضافاً إلى النبي ﷺ يتبادر منه أمة الإجابة(٢) كما تدل عليه رواية: «وإن هذه الملة» أي أمته ﷺ(٣). الثاني: إن المراد بتفرق الأمة هو ما وقع في الأصول الدينية والاعتقادية لا ما كان في الفروع الفقهية والأحكام العملية فالتفرق في الأصول والعقائد هو المخصوص بالذم(٤). قال العلامة عبدالقاهر بن طاهر التميمي في شرح هذا الحديث: (قد علم أصحاب المقولات أنه ﷺ لم يرد بالفرق المذمومة المختلفين", "(١) تقدم تخريجه.", "(٢) انظر حاشية ابن ماجة ١٣٢٢/٢.", "(٣) انظر عون المعبود ٣٤٢/١٢.", "(٤) انظر فيض القدير ١٧٩/١."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0021.png"}, {"n": 22, "paras": ["في فروع الفقه من أبواب الحلال والحرام، وإنما قصد بالذم من خالف أهل الحق من أصول التوحيد، وفي تقدير الخير والشر، وفي شروط النبوة والرسالة وفي موالاة الصحابة وما جرى مجرى هذه الأبواب لأن المختلفين قد كفر بعضهم بعضاً بخلاف النوع الأول فإنهم اختلفوا من غير تكفير ولا تفسيق للمخالف فيه فيرجع تأويل الحديث في افتراق الأمة إلى هذا النوع من الاختلاف وقد حدث في آخر أيام الصحابة خلاف القدرية من معبد الجهني وأتباعه(١).", "الثالث: قوله: «كلها في النار» لا يعني أنها كافرة - بل هذا اللفظ من ألفاظ الوعيد - والوعيد مشروط بشروط منها يلوغ النص، وإدراك مدلوله، وله موانع منها التوبة الصادقة والاستغفار، والحسنات الماحية للسيئات والمصائب المكفرة والشفاعة، وأعظم من ذلك رحمة أرحم الراحمين.", "الرابع: لم يجعل رسول الله ﷺ الألقاب التي اشتهرت بها الطوائف المنتسبة إلى الإسلام سمات تعرف بها الفرق الثنتين والسبعين، ولا عنواناً يتمايز به بعضها عن بعض، وإنما جعل أمارتها مفارقة الكتاب والسنة، وإجماع الخلفاء الراشدين وسائر الصحابة اتباعاً للظن وما تهوى الأنفس، وقولاً على الله بغير علم وعصبية لمتبوعهم سوى رسول الله ﷺ يعادون في ذلك ويوالون. كما جعل شعاراً للفرقة الناجية اتباع الكتاب والسنة على هدي الصحابة ولزوم جماعتهم وإيثار ذلك على مداركهم وظنونهم يوالون في ذلك ويعادون.", "الخامس: قوله: «إلا واحدة هي الجماعة»، الجماعة جاءت هنا معرفة تعريفاً بأل العهدية والعلمية فدل ذلك على أنها جماعة مخصوصة لها شروطها وأحكامها.", "(١) عون المعبود ١٢ / ٣٤٠ - ٣٤١."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0022.png"}, {"n": 23, "paras": ["وقد تتبع الإمام الشاطبي أقوال أهل العلم في معنى الجماعة فوجدها منحصرة في خمسة أقوال هي:", "١ - أنها السواد الأعظم من أهل الإسلام، فعلى هذا القول يدخل في الجماعة مجتهدو الأمة وعلماؤها وأهل الشريعة العاملون بها ومن سواهم داخلون في حكمهم لأنهم تابعون لهم ومقتدون بهم. فكل من خرج عن جماعتهم فهم الذين شنوا وهم نهبة الشيطان ويدخل في هؤلاء جميع أهل البدع لأنهم مخالفون لمن تقدم من الأمة لم يدخلوا في سوادهم بحال ومن قال بهذا مسعود الأنصاري وابن مسعود.", "٢ - الثاني: أنها جماعة العلماء المجتهدين، فهم حجة الله على خلقه، وهم المعنيون بقوله عليه الصلاة والسلام: «إن الله لن يجمع أمتي على ضلالة» وهذا قول ابن المبارك وابن راهويه وقد قيل لابن المبارك من الجماعة الذين ينبغي أن نقتدي بهم؟ قال: أبو بكر وعمر - فلم يزل يحسب حتى انتهى إلى محمد بن ثابت، والحسين بن واقد - فقيل: هؤلاء ماتوا، فمن الأحياء؟ قال: أبو حمزة السكري. ويخرج بهذا القول من ليس بعالم وكذا أهل البدع.", "٣ - الثالث: أن الجماعة هي جماعة أهل الإسلام إذا أجمعوا على أمر فواجب على غيرهم من أهل الملل اتباعهم.", "٤ - الرابع: أنها جماعة الصحابة على الخصوص. وممن قال بهذا عمر بن عبدالعزيز، وتدل عليه رواية: (ما عليه أنا وأصحابي).", "٥ - الخامس: ما اختاره الطبري من أن الجماعة هي جماعة المسلمين إذا اجتمعوا على أمير فقد أمر رسول الله ﷺ بلزومه(١).", "ونقل الحافظ في الفتح عن الطبري ما نصه: (قال الطبري اختلف في هذا الأمر(٢) وفي الجماعة. فقال قوم: هو للوجوب والجماعة السواد", "(١) انظر الاعتصام ٢٥٨/٢ - ٢٦٧.", "(٢) أن تلزم جماعة المسلمين وإمامهم."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0023.png"}, {"n": 24, "paras": ["الأعظم ... إلى أن قال(١) والصواب أن المراد من الخبر بلزوم الجماعة الذين في طاعة من اجتمعوا على تأميره، فمن نكث بيعته خرج عن الجماعة(٢). قال الشاطبي: (الجميع اتفقوا على اعتبار أهل الاجتهاد سواء انضم إليهم العوام أم لا؟)(٣).", "وكما وقع الخلاف في تفسير الجماعة، فقد تعددت الآراء أيضاً في تفسير الطائفة المنصورة الظاهرة إلى قيام الساعة. قال النووي: (وأما هذه الطائفة فقد قال البخاري هم أهل العلم، وقال أحمد بن حنبل رضي الله عنه: إن لم يكونوا أهل الحديث فلا أدري من هم. قال القاضي عياض: إنما أراد أحمد أهل السنة والجماعة ومن يعتقد مذهب أهل الحديث. قلت: ويحتمل أن هذه الطائفة مفرّقة بين أنواع المؤمنين فمنهم شجعان مقاتلون، ومنهم فقهاء، ومنهم محدثون، ومنهم زهاد وآمرون بالمعروف، وناهون عن المنكر، ومنهم أهل أنواع أخرى من الخير ولا يلزم أن يكونوا مجتمعين، بل قد يكونون متفرقين في أقطار الأرض)(٤).", "من خلال ما تقدم من أقوال أهل العلم يتحرر لي مدلولان لمعنى الجماعة:", "١ - أحدهما: يمثل الأساس المنهجي، والإطار الأصولي لجماعة المسلمين من حيث منهجها في الاعتقاد، وفهمها لنصوص الكتاب والسنة، وسبيلها في الأقوال والأعمال والأحوال. وهذا المعنى تدل عليه رواية: (مَنْ كان على مثل ما أنا عليه اليوم وأصحابي)، قال شارح الطحاوية: (جماعة المسلمين الصحابة والتابعون لهم", "(١) الطبري.", "(٢) فتح الباري ٣٧/١٣.", "(٣) انظر الاعتصام ٢٥٨/٢ - ٢٦٧.", "(٤) شرح النووي على مسلم ٢٥/٨ - ١٢٦ بحاشية إرشاد الساري."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0024.png"}, {"n": 25, "paras": ["بإحسان) فهذا يعني أن الجماعة المسلمة أو جماعة المسلمين هي التي تسير في عقيدتها وأقوالها وأفعالها وأخلاقها على ما كان عليه النبي ﷺ وما كان عليه الصحابة رضي الله عنهم فتلزم طريقهم، وتسلك سبيلهم، وتنهج نهجهم في كل ما تأتي وما تذر دون ابتداع أو تحريف. فكل من لزم آثار السلف الصالح من الصحابة والتابعين وتابعيهم (١) من أهل القرون الثلاثة الفاضلة المشهود لها بالخير والإيمان والفضل والإحسان وتمسك بهديهم، وارتضى منهاجهم، والتزم إجماعهم، فهو من جماعة المسلمين ومن أهل الفرقة الناجية والطائفة الظاهرة لا يستوحسن من قلة السالكين، ولا يغتر بكثرة المخالفين، إذ هي ما وافق الحق ولو كنت وحدك قال تعالى: إن إبراهيم كان أمة. قال ابن القيم: (وما أحسن ما قال أبو محمد عبدالرحمن بن إسماعيل المعروف بأبي شامة في كتاب الحوادث والبدع : حيث جاء الأمر بلزوم الجماعة فالمراد به لزوم الحق واتباعه، وإن كان المتمسك به قليلاً والمخالف له كثيراً لأن الحق هو الذي كانت عليه الجماعة الأولى من عهد النبي ﷺ وأصحابه ولا نظر إلى كثرة أهل البدع بعدهم . ثم ذكر قصة عمرو بن ميمون الأودي وفيها أنه صحب معاذاً باليمن ثم بالشام حتى واراه في التراب، ثم صحب أبن مسعود وسمعه يقول : عليكم بالجماعة فإن يد الله على الجماعة. ثم سمعه يقول مرة: سيلي عليكم ولاة يؤخرون الصلاة عن مواقيتها فصلوا الصلاة لمقاتها فهي الفريضة وصلوا معهم فإنها لكم نافلة. فأشكل ذلك على الأودي: كيف يحدثهم عن لزوم الجماعة ثم يأمرهم بالصلاة وحدهم. فقال ابن مسعود: تدري ما الجماعة؟ قال: قلت: لا . قال: إن جمهور الناس فارقوا الجماعة: الجماعة ما وافق الحق وإن كنت وحدك.", "وقد سئل بعض أهل العلم في زمان محمد بن أسلم الطوسي عن قوله : (إذا اختلف الناس فعليكم بالسواد الأعظم) فقال محمد بن أسلم الطوسي : هو السواد الأعظم .", "(1) دون من رمي ببدعة أو تخليط."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0025.png"}, {"n": 26, "paras": ["قال ابن القيم: وصدق والله فإن العصر إذا كان فيه عارف بالسنة داع إليها فهو الحجة، وهو الإجماع، وهو السواد الأعظم وهو سبيل المؤمنين(١). فالجماعة بهذا المعنى تعني المنهج الذي يلزمنا اتباعه والذي استقر على صيغة أهل السنة والجماعة.", "قال المناوي في شرح حديث الفرقة الناجية (إلا واحدة) (وهي أهل السنة والجماعة)(٢) وذكر الأستاذ محمد فؤاد عبدالباقي تعليقاً على معنى «الجماعة» فقال: (أي الموافقون لجماعة الصحابة، الآخذون بعقائدهم، المتمسكون برأيهم)(٣). وبهذا المدلول المنهجي لمعنى الجماعة يتنزل قول قتادة: (أهل رحمة الله: أهل الجماعة وإن تفرقت ديارهم وأبدانهم)(١).", "ويتنزل قول الشافعي: (ومن قال بما تقول جماعة المسلمين فقد لزم جماعتهم، ومن خالف ما تقول به جماعة المسلمين فقد خالف جماعتهم التي أمر بلزومها)(٢).", "ولكن هذا الإطار المنهجي لمفهوم الجماعة المسلمة والفرقة الناجية تتفاوت فيه درجات الأمة ومقاماتها، فمنهم من هو أحرص على اتباع الشريعة والإستسلام لها وأبعد الناس عن الابتداع والتحريف، وأصدقهم على تمثيل هذا المنهج، وأشملهم التزاماً. فهؤلاء أسعد القوم بمقام الفرقة الناجية والجماعة المسلمة كعلماء الأئمة المعتبرين في الفقه والتفسير والحديث والأصول والرقائق، والدعاة الأعلام المشهود لهم بالاستقامة والخيرية والصلاح وأمثالهم. ومنهم من هو أهل للاجتهاد إلا أنه قد يتأول بعض نصوصها تأويلاً يخطىء فيه فيعذر في خطئه لكونه في موارد الاجتهاد. ومنهم من ينكر بعض نصوص الشريعة إما لكونه حديث عهد بالإسلام، وإما لأنه نشأ في أطراف البقاع فلم يبلغه ما أنكره. ومنهم من يرتكب بعض البدع العملية فهو مؤمن.", "(١) إغاثة اللهفان ٨٤ - ٨٥.", "(٢) فيض القدير ١٧٩/١.", "(٣) انظر حاشية ابن ماجه ١٣٢٢/٢."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0026.png"}, {"n": 27, "paras": ["مطيع لله بما فيه من طاعة، مسيء بما ارتكب من معصية أو قارف من بدعة عملية فهو في مشيئة الله تعالى. قال تعالى: ﴿إن الله لا يغفر أن يشرك به، ويغفر ما دون ذلك لمن يشاء﴾. وقال تعالى: ﴿وآخرون اعترفوا بذنوبهم خلطوا عملاً صالحاً، وآخر سيئاً عسى الله أن يتوب عليهم﴾.", "فهؤلاء وهؤلاء ليسوا بكفار بتأويلهم الخاطيء أو بجحدهم ما جحدوا بجهلهم، بل يعذرون ويدخلون في عداد الفرقة الناجية وإن كان دون الأولى(١).", "فأهل الجماعة المسلمة ومنهم السابق المقرب، ومنهم المقتصد، ومنهم الظالم لنفسه.", "ومما يقتضي التنبيه أن لأهل السنة والجماعة أصولاً ثابتة بالأدلة يبنون عليها الفروع ويرجعون إليها في الاستدلال على المسائل الجزئية وفي تطبيق الأحكام على أنفسهم وعلى غيرهم.", "توضيح: يتفرع على ما قدمت أنه لا يصح حمل معنى الطائفة الظاهرة على أهل الحديث خاصة إلا على ما ذكره القاضي عياض: (وهو أهل السنة والجماعة). لأن انتفاع الأمة بأهل الحديث وإن كان نفعاً عاماً فإنها تنتفع بغيرهم كالفقهاء الذين يبينون موارد الشرع وأحكام الحلال والحرام، وكذلك أهل التفسير والقراء والوعاظ والدعاة والقضاة وغيرهم من طبقات الأمة: (فإن كل قوم ينفعون بفن لا ينفع به الآخر)(٢).", "٢ - المعنى الثاني للجماعة: ويمثل المنهج في مرحلة التمكين، وهو جماعة العلماء - أهل الحل والعقد - إذا اجتمعوا على أمير والأمة من ورائهم تبع لهم.", "(١) انظر فتوى هيئة كبار العلماء رقم ٨٣٠، بتاريخ ١٣٩٤/٨/١٣ ه.", "(٢) جامع الأصول لابن الأثير ١ / ٣٢٠ - ٣٢١."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0027.png"}, {"n": 28, "paras": ["كما حدث في بيعة أبي بكر الصديق حيث بايعه كبار الصحابة في السقيفة، ثم تبعهم السواد في بيعة عامة مشهودة(١). وعلى هذا يتنزل قول الطبري: (والصواب أن المراد من الخبر لزوم الجماعة الذين في طاعة من اجتمعوا على تأميره)(٢). فإذا لم توجد هذه الإمامة الشرعية في حياة الأمة وجب عليها السعي إلى تحقيقها ولا ينفك عنها الإثم حتى تقام.", "الخلاصة: يتضح مما تقدم في معنى الجماعة التي وردت بها النصوص جملة أمور:", "١ - إن قيام جماعة من الجماعات مهما بلغت من وضوح الفكرة واستقامة الطريق لا يعني بأية حال أن جماعة المسلمين قد قامت. وعلى هذا، فالجماعات العاملة اليوم في الحقل الإسلامي والمعروفة بأسمائها وقادتها وشعاراتها ليست وحدها هي الجماعة المسلمة أو جماعة المسلمين بل هي تندرج في جماعة المسلمين. فالإخوان المسلمون والسلفيون وأمثالها جماعات من المسلمين، ولا يصح وصف واحدة بأنها هي الجماعة الواردة في الأحاديث وإن كانت تسعى لتحقيق جماعة المسلمين بالتمكين لها بدولة الإسلام والخلافة الراشدة.", "٢ - أن هذه الجماعات وإن كانت مندرجة في المفهوم المنهجي للجماعة المسلمة إلا أنها تتفاوت في عطائها وقدراتها فمنها من أوقف اجتهاده على إصلاح عقائدي، وآخر اعتنى بالتربية الروحية، وثالث عني بالوعظ والتذكير، ورابع غلب عليه الاهتمام السياسي، ومنها من استوعب كل مناحي الإصلاح في شمول وتكامل وتوازن ورعاية أولويات.", "٣ - لا يصح قياس هذه الجماعات على جماعة الرسول ﷺ لأنه قائد تلك الجماعة، وطاعته واجبة - وهو مؤيد بالوحي - والانقياد له أمر لا يتم إسلام المرء إلا به، سواء في حياته أو بعد مماته.", "(١) انظر البداية والنهاية لابن كثير ٥/ ٢٤٥ - ٢٤٧.", "(٢) فتح الباري ١٣/ ٣٧، والاعتصام ٢/ ٢٥٨ - ٢٦٧."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0028.png"}, {"n": 29, "paras": ["ثم إن الواقع الفعلي كان مطابقاً للأمر التشريعي، فلم يكن هناك إنسان يدعي إنه مسلم ويشهد الشهادتين ويقيم الصلاة إلا ويعد نفسه عضواً في تلك الجماعة. وواقعنا اليوم غير ذلك، فكثير من الناس اليوم ينتسبون إلى الإسلام، ويقيمون شرائعه الظاهرة، ولا يرتبطون بجماعة من الجماعات فالحكم عليهم بالكفر قياساً على الجماعة الأولى تحكم وتعسف. وكذلك الحكم على من فارق إحدى هذه الجماعات بالكفر تعسف لا مسوغ له.", "٤ - كما لا يصح قياس شروط أمير إحدى هذه الجماعات على شروط أمير المؤمنين وواجباته.", "٥ - مفهوم المفارقة التنظيمية للجماعات لا ينطبق عليه وصف الخارج على الجماعة، فالخروج على الجماعة في غالب اصطلاح الفقهاء محمول على معنى المقاومة المسلحة لا مجرد المفارقة والابتعاد، وهذا المعنى ظاهر في معنى البغي والبغاة وما أطلق على الخوارج.", "وحتى الخروج بهذا المعنى في حد ذاته لا يعتبر كفراً لاحتمال أن يكون صاحبه متأولاً، قال تعالى: ﴿وإن طائفتان من المؤمنين اقتتلوا...﴾ الآية، فسماهم مؤمنين رغم اقتتالهم.", "ومما يدل على ذلك أن الخوارج لم يكفرهم علي ولا سائر الصحابة رغم خروجهم ومع ورود الأحاديث المستفيضة بشأن ضلالهم، بل قال رضي الله عنه: (إخواننا بغوا علينا، هم من الكفر قد فروا) وعاملهم في الحرب معاملة البغاة، فلم يغنم أموالهم، ولم يسب ذراريهم، ولم يقتل أسيرهم، ولم يجهز على جريحهم أو يتبع من أدبر منهم.", "٦ - مفهوم (مات ميتة جاهلية) لا تعني أنه مات على الكفر بل المراد أنه مات على حالة تشبه حال أهل الجاهلية لأنهم لم يكونوا يبايعون إماماً أو يخضعون لسلطان. قال الإمام الشوكاني: (ميتة الجاهلية تشبيه بأهل الجاهلية فلا إمام لهم فليس المراد أنه يموت كافراً، بل يموت عاصياً)(١).", "(١) نيل الأوطار ١٩٤/٧."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0029.png"}, {"n": 30, "paras": ["٧ - التخلف عن العمل الجماعي لإنفاذ أوامر الله وشرائعه والتمكين لدينه يأثم المرء عليه ولا يخرج من الملة بسبب ذلك إلا أن يجحد الهدف(١) وهو تحكيم شرع الله فيكون كافراً مرتداً(٢). كان للإمام البنا منهج واضح المعالم بين القسمات، أوضح فيه معنى جماعة الإخوان المسلمين، وموقعها من جماعة المسلمين في اعتدال صادق، وتوازن محكم تأكيداً لما قرره الأئمة الأعلام من سلف الأمة الصالح ويتضح هذا البيان في عدة محاور: الأول: موقف الإخوان من الهيئات الإسلامية: يقول الإمام البنا: (والإخوان المسلمون يرون هذه الهيئات على اختلاف ميادينها تعمل لنصرة الإسلام وهم يتمنون لها جميعاً النجاح ولم يفتهم أن يجعلوا من منهاجهم التقرب منها والعمل على جمعها وتوحيدها حول الفكرة العامة)(٤). الثاني: الفرق بين الإخوان والجماعات الإسلامية: يقول الإمام البنا: (كثيراً ما يرد على أذهان الناس هذا السؤال ما الفرق بين جماعة الإخوان وجماعة الشبان؟ ولماذا لا يكونان هيئة واحدة ويعملان على منهج واحد؟ وأحب قبل الجواب على هذا السؤال أن أؤكد للذين يسرهم وحدة الشهود وتعاون العاملين أن الإخوان والشبان وخاصة هنا في القاهرة لا يشعرون بأنهم في ميدان منافسة ولكن في ميدان تعاون قوي وثيق، وأن كثيراً من القضايا الإسلامية العامة يظن فيها الإخوان والشبان شيئاً واحداً، وجماعة واحدة إذ إن الغاية العامة مشتركة وهي العمل لما فيه إعزاز الإسلام وإسعاد المسلمين، وإنما تقع فروق يسيرة في أسلوب الدعوة وفي خطة القائمين عليها وتوجيه جهودهم في كلتا الجماعتين)(٥).", "(١) وهو عالم بذلك.", "(٢) انظر دعاة لا قضاة ص ١٨٣.", "(٣) مجموعة الرسائل ص ٣١٣.", "(٤) المصدر السابق ص ٣١٤.", "(٥) المصدر السابق ص ٣١٤."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0030.png"}, {"n": 31, "paras": ["٣ - أسلوب معاملة المخالف: (ونلتمس كل العذر لمن يخالفوننا في بعض الفرعيات، ونرى أن هذا الخلاف لا يكون أبداً حائلاً دون ارتباط القلوب، وتبادل الحب والتعاون على الخير، وأن يشملنا وإياهم معنى الإسلام السابغ بأفضل حدوده وأوسع مشتملاته)(١).", "٤ - موقفنا من الدعوات الأخرى: (موقفنا من الدعوات في هذا البلد دينية واجتماعية واقتصادية وسياسية - بناء على طبيعة دعوتنا - موقف واحد على ما أعتقد: نتمنى لها الخير وندعو لها بالتوفيق، وإن خير طريق نسلكها ألا يشغلنا الالتفات إلى غيرنا عن الالتفات إلى أنفسنا. إننا في حاجة إلى عدة وإلى تعبئة، وإن أمتنا والميادين الخالية فيها محتاجة إلى جنود وإلى جهاد، والوقت لا يتسع لتطلع إلى غيرنا ونشتغل به . كل في ميدانه والله مع المحسنين حتى يفتح الله بيننا وبين قومنا بالحق)(٢).", "٥ - تقرير الإمام الهضيبي عن مسلك الإمام البنا العملي: يقول الإمام الهضيبي: (ومن المسلم به أن جماعة الإخوان المسلمين مع إيمانها الكامل أنها قامت على الحق ويقينها الذي لا شك فيه أن دعوتها دعوة حق خالصة أمر الله بها أمر وجوب وإلزام فمن المؤكد أن الاختيار الفقهي لمؤسسها لم يكن النظر إليها باعتبارها جماعة المسلمين المقصودة في الأحاديث وإنما هي داعية بعون الله لتحقيق جماعة المسلمين. يؤكد ذلك أن مؤسس الجماعة رضي الله عنه اعترف طوال فترة قيادته للجماعة وصحبه الذين آزروه واجتمعوا معه على دعوته قد اعترفوا لغيرها من الجماعات بأنها جماعات إسلامية كما اعترفوا بصفة المسلم لمن لم يكن منضماً لجماعة الإخوان أو فصل منها.", "(١) المصدر السابق ص ٢٤", "(٢) المصدر السابق ص ١٢٨ ."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0031.png"}, {"n": 32, "paras": ["وقد قرر الإمام الشهيد فصل وكيلي الجماعة السابقين وعشرات غيرهما كان بعضهم أعضاء بمكتب الإرشاد والهيئة التأسيسية ولم يكن قد نسب لأحدهم أنه أتى عملاً أو قال قولاً ارتد به عن الإسلام، ولا زعم أحد أنهم بفصلهم من الجماعة قد أخرجوا من الإسلام(١). منهج الجماعة بعد الإمام الشهيد: سار على ذات السنن القويم الذي اختطه الإمام البنا رحمه الله. قال الإمام الهضيبي: (وبعد الإمام الشهيد صدق مكتب الإرشاد والهيئة التأسيسية على فصل عدد غير قليل من أعضاء كانوا بالجماعة منهم من كان عضواً بمكتب الإرشاد أكثر من مرة، ومنهم من تولى مراكز قيادية في الجماعة وأنظمتها، وكان القول الصريح من قيادة الجماعة في هذه المناسبات مسلمون معصومو الدم والمال ترجو الجماعة لهم أن يخدموا الإسلام بمجهوداتهم الفردية وبأساليبهم الخاصة بعد أن استعصى عليهم توطين أنفسهم على نظام الجماعة والالتزام بمفهوماتها وبرامجها ومناهجها)(٢). مما تقدم يتبين بجلاء لا شبهة فيه أن منهج الإخوان قائم على أنهم جماعة من المسلمين يسعون لتحقيق جماعة المسلمين ويعترفون لغيرها من الجماعات بأنها تسعى لخدمة الإسلام. ومما يتضح في منهج الإخوان كذلك ما يلي:", "١ - أنه لا تقاس عندهم شروط العضوية على شروط الإسلام(٣).", "٢ - أنه لا تقاس عندهم شروط الفصل على شروط الردة(٤). وإلا فلماذا فصل وكيلي الجماعة السابقين وبعض أعضاء مكتب الإرشاد ولم يكن أحدهم قد ارتكب ما يخرجه من الملة؟.", "(١) دعاة لا قضاة ص ١٨٥ .", "(٢) دعاة لا قضاة ص ١٨٥ - ١٨٦ .", "(٣) المصدر السابق ص ١٨٥ - ١٨٦، الرسائل ج ٢ - ٦٢ .", "(٤) المصدر السابق ص ١٨٥ - ١٨٦ ."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0032.png"}, {"n": 33, "paras": ["٣ - يمكن للجماعة أن تلزم أفرادها بأكثر مما يلزمهم الإسلام على وجه التفصيل كالنظم الداخلية واللوائح مثلاً(١).", "٤ - الجماعة ليست مطالبة بالقيام بواجبات الخلافة كلها قبل إيجاد الخليفة، بل الواجب إيجاد الخليفة لتحقيق تلك الأمور(٢).", "٥ - لا تقاس شروط أمير الجماعة وواجباته على شروط أمير المؤمنين(٣). فهذه خلاصة ما حرره فقهاء الجماعة، والتزمته قيادتها في منهاجها العملي، وفي تعاملها مع المخالفين وفق أصول أهل السنة ومنهاج السلف الصالح.", "ما أشار إليه الشيخ سعيد حوى لا يخرج عن هذه المعاني حيث إن جماعة الإخوان جماعة كاملة للمسلمين، إنما عنى من حيث فهمها الشامل وتكامل تصورها في أخذ الإسلام ولم يقصد خروج غيرهم عن جماعات المسلمين.", "(١) شلبي ٢٠٦ - ٣٢٠ الشيخ حسن البنا ومدرسته.", "(٢) الرسائل ج ١ - ٢٥.", "(٣) الشيخ حسن البنا ومدرسته ص ٢٧٠ - ٢٧٢."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0033.png"}, {"n": 34, "paras": ["البيعة في العمل الجماعي", "البيعة لغة واصطلاحاً: كلمة البيعة مشترك لفظي يدور في لغة العرب على معان:", "١ - منها: الصفقة على إيجاب البيع(١). يقال بايع فلاناً مبايعة أي عقد معه البيع والبيعة وأمسك يده لتمام العقد والرضى.", "٢ - ومنها: المبايعة والطاعة(٢).", "٣ - ومنها: المعاهدة والعهد والمعاقدة(٣): يقال: بايعه عليه مبايعة: عاهده. والمبايعة: المعاهدة سميت بذلك تشبيهاً بالمعاوضة المالية كما في قوله تعالى: ﴿إن الله اشترى من المؤمنين أنفسهم وأموالهم بأن لهم الجنة﴾(٤). والعهد: (كل ما عوهد الله عليه، وكل ما بين العباد من المواثيق فهو عهد)(٥). والمبايعة: المعاقدة - ففي الحديث: (ألا تبايعوني على الإسلام): هو عبارة عن المعاقدة - كأن كل واحد منهما باع ما عنده من صاحبه وأعطاه خالصة نفسه وطاعته ودخيلة أمره(٦).", "(١) (٢) (٣) لسان العرب ٢٩٩/١، النهاية ١٧٤/١.", "(٤) سورة التوبة: الآية ١١١.", "(٥) فتح الباري ٦٤/١.", "(٦) لسان العرب ٩١٤/٢."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0034.png"}, {"n": 35, "paras": ["البيعة في الاصطلاح: هي عقد قائم على الرضا، يملك به الأمير حق السمع والطاعة، في العسر واليسر، والمنشط والمكره في المعروف.", "قال العلامة ابن خلدون: (اعلم أن البيعة هي العهد على الطاعة، كأن المبايع لا ينازعه في شيء من ذلك، ويطيعه فيما يكلفه من الأمر على المنشط والمكره. وكانوا إذا بايعوا وعقدوا عهده جعلوا أيديهم في يده، تأكيداً للعهد، فأشبه ذلك فعل البائع والمشتري، فسمي بيعة مصدر باع، وصارت البيعة مصافحة بالأيدي، هذا مدلولها في عرف اللغة ومعهود الشرع، وهو المراد في الحديث في بيعة النبي ﷺ، وحيثما ورد هذا اللفظ، ومنه بيعة الخلفاء، ومنه أيمان البيعة، كأن الخلفاء يستحلفون على العهد، ويستوعبون الأيمان كلها لذلك، فسمى هذا الاستيعاب أيمان البيعة)(١).", "(١) مقدمة ابن خلدون ص ٢٢٩."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0035.png"}, {"n": 36, "paras": ["مشروعية البيعة في العمل الجماعي", "إن البيعة التي وردت بها النصوص هي من مفاهيم عقد الخلافة التي تعطى لأمير المؤمنين أو السلطان المتمكن، وتجعل أمره واجب الاتباع حتى في المباح إذا كان فيه مصلحة. أما بيعة العمل الجماعي فهي عقد وعهد وميثاق مشروط. فهي من جنس البيعات التعاقدية على عمل ما كبيعة بعض المجاهدين يوم اليرموك. وقد تعددت الشواهد على مشروعيتها أسوق منها طرفاً:", "١ - أنها عقد: إمارة صغرى: الإمارة إمارتان: إمارة كبرى وأخرى موقوتة محددة. أما الكبرى فخلافة المسلمين أو الإمامة العامة. وأما الأخرى فكإمرة السفر والحج. وكلا الأمرين ثابت شرعاً. أما دليل الإمارة الكبرى: فقد قال ابن حزم: الإمامة ثابتة بالكتاب والسنة والإجماع. قال تعالى: ﴿أطيعوا الله وأطيعوا الرسول وأولي الأمر منكم﴾(١)، وقال عليه الصلاة والسلام: «من أطاعني فقد أطاع الله، ومن أطاع أميري فقد أطاعني»(٢). وأجمعت الأمة على وجوب الإمامة. ولقد أمر سبحانه بالأمر بالمعروف والنهي عن المنكر ولا يتم ذلك إلا بقوة وإمارة، وما لا يتم الواجب إلا به فهو واجب.", "(١) الملل والتملل: ١٤٩/٤ ط شركة مكتبة عكاظ", "(٢) مسلم بشرح النووي ٢٢٣/٢."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0036.png"}, {"n": 37, "paras": ["أما دليل شرعية الإمارة الأخرى فقد روى أبو داود من حديث أبي سعيد وأبي هريرة مرفوعاً: (إذا خرج ثلاثة في سفر فليؤمروا أحدهم). وصيغة الطلب في الحديث للأمر لأنه فعل مضارع مقترن بلام الأمر فأفاد الوجوب.", "وروى الإمام أحمد في مسنده من حديث عبدالله بن عمرو أن النبي ﷺ قال: «لا يحل لثلاثة يكونون بفلاة من الأرض إلا أمروا عليهم أحدهم» فالحديثان ينصان على وجوب التأمير على جماعة قليلة في سفر عارض.", "يقول شيخ الإسلام ابن تيمية: (يجب أن يعرف أن ولاية أمر الناس من أعظم واجبات الدين، بل لا قيام للدين وللدنيا إلا بها فإن بني آدم لا تتم مصلحتهم إلا بالاجتماع لحاجة بعضهم إلى بعض، ولا بد لهم عند الاجتماع من رأس) . . . ثم قال بعد إيراده للحديثين المتقدمين: (فأوجب ﷺ تأمير الوحد في الاجتماع القليل العارض في السفر تنبيهاً بذلك على سائر أنواع الاجتماع، ولأن الله تعالى أوجب الأمر بالمعروف والنهي عن المنكر ولا يتم ذلك إلا بقوة وإمارة . . . فالواجب اتخاذ الإمارة ديناً وقربة إلى الله، فإن التقرب إليه فيها بطاعته وطاعة رسوله من أفضل القربات)(١).", "أما إمارة الحج فقد قال الماوردي: (ولاية الحجيج على ضربين: أحدهما: أن يكون على تسيير الحجيج. والثاني: إقامة الحج. أما الأول: فهو ولاية سياسة وتدبير وشروط المتولي أن يكون مطاعاً).", "من ذلك الحديث الذي دل على وجوب اتخاذ الإمارة للنفر القليل في السفر العارض، ومن فقه إمارة الحج نرى إمارة الجماعات الإسلامية من هذا الباب بقياس الأولى لشرف الإمارة في العمل الإسلامي، وتجب الطاعة فيها بحكم البيعة التي التزم بها التابع لهم في جماعتهم كأمير السفر.", "وعقد الإمارة الموقوتة خطوات ضرورية ومرحلة لازمة نحو عقد الإمامة", "(١) الفتاوى ٣٩١/٣٨ - ٣٩٣."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0037.png"}, {"n": 38, "paras": ["الكبرى تستمد حرمتها كاملة من كونها شعب تصب في بيعة الخلافة المستقبلية الموعودة بإذن الله تعالى. فهي مرحلة متأكدة لاستئناف الخلافة تسقط بإقامتها.", "والطاعة المعروفة المشروطة للأمراء بدرجاتهم المتفاوتة أمر لازم وهو من طاعة الله والرسول. إذ إن الشارع الحكيم يريد للناس أداءً منضبطاً، وسلوكاً منتظماً. فالعصيان في معروف لا يؤدي إلا إلى التشاكس والفوضى، والإمارة بلا طاعة لا معنى لها، ولا فائدة منها إذ المقصود منها أن تسوس أمور الناس بطريقة منتظمة حتى تجري على نسق وتقوم على ساق ولا يتم ذلك إلا وفق الضوابط الشرعية المعتبرة.", "٢ - عقد على عمل مشروع: لا يخرج عقد البيعة من كونه قائماً على عمل مشروع، لا يتضمن شرطاً فاسداً، أو أمراً محذوراً، وكل عقد خلا من الموانع الشرعية وسلمت فيه المقاصد فإنه يلزم الوفاء به.", "يقول ابن تيمية: (جميع ما يقع بين الناس من الشروط والعقود والمخالفات في الأخوة وغيرها ترد إلى كتاب الله وسنة رسوله، فكل شرط يوافق الكتاب والسنة يوفى به)(١)، ثم قال: (وكذا في شروط البيوع والهبات، والوقوف، والنذور وعقود البيعة للأئمة وعقود المتآخين وعقود أهل الأنساب والقبائل وأمثال ذلك فإنه يجب على كل أحد أن يطيع الله ورسوله في كل شيء، ويجتنب معصية الله ورسوله في كل شيء، ولا طاعة لمخلوق في معصية الخالق)(٢). إذاً فكل عقد قام على موازين الشرع ومحكمات الدين فإنه يلزم نفاذه.", "فإن قيل إن العمل المتعاقد عليه واجب بذاته في ميزان الشرع بدون هذا العقد فما فائدة هذا العقد؟.", "فالجواب كما قال شيخ الإسلام ابن تيمية: (فإذا حلف على ذلك كان ذلك", "(١) و(٢) الخلافة والملك ص ١١٧ - ١١٨."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0038.png"}, {"n": 39, "paras": ["توكيداً وتثبيتاً لما أمر الله به ورسوله(١) فالعقد يزداد تأكداً ولزوماً واستيثاقاً. ثم إن كل عقد بين المؤمنين فهو عقد محترم تجارياً كان أو غيره. لكن حرمة العقود تزداد بحرمة المتعاقد عليه. فإذا كان عقد الإمارة موضوعه أشرف المواضيع فالوفاء به مما يقرب إلى الله تعالى. قال تعالى: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا أَوْفُوا بِالْعُقُودِ﴾(٢)، وقال عز وجل: ﴿فَمَن نَّكَثَ فَإِنَّمَا يَنكُثُ عَلَىٰ نَفْسِهِ﴾(٣)، وقال سبحانه: ﴿وَلَا تَنقُضُوا الْأَيْمَانَ بَعْدَ تَوْكِيدِهَا﴾(٤) ﴿وَالْمُوفُونَ بِعَهْدِهِمْ إِذَا عَاهَدُوا﴾(٥). يقول ابن تيمية: (من كان حالفاً على ما أمر الله به ورسوله من طاعة الأمور ومناصحتهم، أو الصلاة أو الزكاة أو صوم رمضان، أو أداء الأمانة والعدل ونحو ذلك لا يجوز لأحد أن يفتيه بمخالفة ما حلف عليه، والحنث في يمينه، ولا يجوز له أن يستفتي في ذلك، ومن أفتى مثل هؤلاء بمخالفة ما حلفوا عليه، والحنث في أيمانهم، فهو مفتر على الله الكذب، مفت بغير دين الإسلام، بل لو أفتى آحاد العامة بأن يفعل خلاف ما حلف عليه من الوفاء في عقد أو نكاح أو إجارة أو غير ذلك مما يجب عليه الوفاء من العقود التي يجب الوفاء بها وإن لم يحلف عليها، فإذا حلف كان أوكد. فكيف إذا كان ذلك في معاقدة ولاة الأمور التي هي أعظم العقود التي أمر الله بالوفاء بها)(٦).", "٣ - عهد وميثاق: جاء في اللغة ما يلي: (بايعه عليه مبايعة: عاهده، والمبايعة: المعاهدة. والعهد كل ما عوهد الله عليه، وكل ما بين العباد من مواثيق فهو عهد). هذا في مقتضى الدلالة اللغوية.", "كما جاءت بمعنى العهد والميثاق في مواضع متعددة من الوقائع السنية، أبرزها ما تم في بيعة العقبة الثانية حيث كانت عهداً وميثاقاً من أهل النصرة من الأوس والخزرج لرسول الله ﷺ. فعلى الدعاة أن يقيموا مثل هذه العهود.", "(١) المصدر السابق ١٤.", "(٢) سورة المائدة: الآية ١.", "(٣) سورة الفتح: الآية ١٠.", "(٤) سورة النحل: الآية ٩١.", "(٥) سورة البقرة: الآية ١٧٧.", "(٦) الخلافة ص ١٥."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0039.png"}, {"n": 40, "paras": ["فيما بينهم تاصراً على الخير، وتعاوناً على البر، وتكاتفاً على المعروف، وموالاة على الحق لتمكين دين الله وإنفاذ شرعه وتطبيق حكمه. وما أجمل هذا العهد الذي حسن ابن تيمية أن يقوله الأستاذ لتلميذه وكيف أن التزمه كان من المجاهدين في سبيل الله. (عليك عهد الله وميثاقه، أن توالي من والى الله ورسوله وتعادي من عادى الله ورسوله، وتعاون على البر والتقوى، ولا تعاون على الإثم والعدوان، وإذا كان الحق معي نصرت الحق، وإن كنت على الباطل لم تنصر الباطل. فمن التزم هذا كان من المجاهدين في سبيل الله الذين يريدون أن يكون الدين كله لله، وتكون كلمة الله هي العليا)(١).", "وقد حدثت عهود ومواثيق قبل قيام الدولة الأولى وبناء الحكم فيها كبيعة العقبة الثانية مما يفيد أن مثل هذا العهد هو مرحلة لازمة نحو استئناف الخلافة.", "ومن صور العهود ما وقع من تعاهد بعض المجاهدين للزبير بن العوام - ولم يكن أميراً - في واقعة اليرموك على الموت ليقتحم بهم حصناً من الحصون(٢).", "الخلاصة:", "أن البيعات التي تعطى في العمل الجماعي هي مندرجة في عقد الإمارة الصغرى على عمل مشروع تزيد من شأنه توكيداً وتثبيتاً ولزوماً. وهي مرحلة ضرورية نحو ذلك العقد الجامع تستمد حرمتها من كونها شعب تصب في البيعة الخلافية المستقبلية. والوفاء بها لازم شرعاً لكل من تلبث بها. لقوله تعالى: ﴿وأوفوا بالعهد إن العهد كان مسئولا﴾(٣).", "(١) الفتاوى ٢١/٢٨.", "(٢) البخاري: فضائل الصحابة، باب مناقب الزبير بن العوام ٨٠/٧ من فتح الباري.", "(٣) سورة الإسراء: الآية ٣٤."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0040.png"}, {"n": 41, "paras": ["صيغ عقد البيعة", "تعدد صيغ البيعة وألفاظها بتعدد الظروف والأشخاص والأحوال والمهمات، ولم يرد في نصوص السنة ما يفيد حصر البيعة في ألفاظ بعينها، بل ذلك عائد إلى صفة عقد البيعة ومضمونه. وقد تنوعت الألفاظ بحسب مقاماتها المختلفة التي وردت فيها.", "قال ابن القيم: (كان النبي ﷺ يبايع أصحابه في الحرب ألا يفروا، وربما بايعهم على الموت، وبايعهم على الجهاد، كما بايعهم على الإسلام، وبايعهم على الهجرة قبل الفتح، وبايعهم على التوحيد، والتزام طاعة الله ورسوله، وبايع نفراً من أصحابه ألا يسألوا الناس شيئاً)(١)، والمتتبع لعبارات البيعة يجد أنها تختلف تبعاً لمضمون العقد الذي تدور عليه.", "فقد وقعت البيعة العامة على الإسلام كبيعة الناس يوم الفتح على الإسلام والشهادة. ففي رواية البيهقي: (جاءه الناس الكبار والصغار، والرجال والنساء فبايعهم على الإسلام والشهادة)(٢).", "- ومنها البيعة على أعمال الإسلام: كبيعة النساء.", "- ومنها البيعة على الهجرة: كبيعة الناس على الهجرة يوم الخندق.", "- ومنها البيعة على النصرة: كبيعة سبعين رجلاً من الأنصار عند شعب العقبة على النصرة.", "(١) زاد المعاد ٩٥/٣.", "(٢) مجمع الزوائد ٣٧/٦، كنز العمال ٨٢/١."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0041.png"}, {"n": 42, "paras": ["- ومنها البيعة على السمع والطاعة والأثرة وقول الحق لا يخشى في الله لومة لائم وعدم منازعة الأمر أهله: كما في حديث عبادة بن الصامت في بيعة العقبة الثانية.", "- ومنها البيعة على الجهاد: مثل بيعة المهاجرين والأنصار على الجهاد في غزوة الخندق، وبيعة بشير بن الخصاصية (على الإسلام والجهاد).", "- ومنها البيعة على النصيحة: مثل بيعة جرير بن عبدالله (وعلى النصح لكل مسلم).", "- ومنها البيعة على الموت وعدم الفرار من المعركة(١): ففي بيعة الرضوان يوم الحديبية بايع المسلمون رسول الله ﷺ على ألا يفروا وعلى الموت، وكبيعة سلمة بن الأكوع التي كانت على الموت.", "- ومنها بيعة بعض الصحابة على أن ألا يسألوا الناس شيئاً.", "- ومنها بيعات تعاقدية على عمل ما: كبيعة بعض المجاهدين يوم اليرموك(٢). فألفاظ البيعة تختلف بحسب مواضعها ومن هنا فلا مانع من أن يتضمن عقد أي بيعة ألفاظاً لم ترد في صور البيعات السابقة. ولكن تبقى صيغة العقد محكومة بأمرين: الأول: وهو في حق من انعقدت له البيعة: أن يكون مشتملاً على العمل بالكتاب والسنة، والقيام بمضمون العقد والوفاء به وفق موازين الشرع. الثاني: وهو في حق الطرف المبايع: ويتمثل: في السمع والطاعة المبصرة والمشروطة بالمعروف، والنصرة له.", "(١) انظر صور هذه البيعات في حياة الصحابة ٢٣٩/١ - ٢٥٩.", "(٢) بايعوا الزبير على الموت ليقتحم بهم حصناً من الحصون."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0042.png"}, {"n": 43, "paras": ["على الحق، والعون له على البر ما استطاع إلى ذلك سبيلاً بما يضمن الوفاء بميثاق العقد ومتطلباته. وعدم منازعته في المعروف.", "كما نستخلص من تعدد صور البيعة أنه لا مانع من تنوعها بحسب اختلاف الأشخاص ومقاماتهم. فلا مانع من بيعة يبايع فيها الوارد عن قبول الجماعة عضويته كنصير، ثم ثانية قبوله منتظماً، ثم ثالثة عاملاً عندما يستقر ويستأنس بذمته، ويوثق بقوته وعهده.", "ولا مانع من توكيد العقد عند العزمات والأزمات إيقاظاً للهمم، وتذكيراً بالواجب، وشحذاً للعزائم."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0043.png"}, {"n": 44, "paras": ["صفة عقد البيعة", "تتنوع الصور في صفة أخذ العهد، وإجراء البيعة، تارة بالمباشرة أو النيابة بالمشافهة، وأخرى بالكتابة، وثالثة بقرينة الحال مما يدل على عدم حصرها في شكل معين.", "١ - الصيغة القولية: وهي أعلى أنواع الصيغ في باب العقود وهو النطق مشافهة بإعطاء العهد أو البيعة. وقد تتبعها مصافحة باليد علامة على تمام الرضى، كما حدث ذلك في عدد من بيعات الصحابة لرسول الله ﷺ ومنها بيعة العقبة الثانية، وبيعة الرضوان التي نزل فيها قوله تعالى: ﴿إن الذين يبايعونك إنما يبايعون الله، يد الله فوق أيديهم﴾(١). وقد تتخلف عنها المصافحة كما هو الحال في بيعة النساء.", "٢ - الكتابة: وهي من أساليب إجراء عقد البيعة. فقد ثبت أن عبدالله بن عمر رضي الله عنهما أنه كتب إلى عبدالملك بن مروان يبايعه. فكتب: (بسم الله الرحمن الرحيم أما بعد: لعبدالملك بن مروان أمير المؤمنين، سلام عليك، فإني أحمد إليك الله الذي لا إله إلا هو، وأقر لك بالسمع والطاعة على سنة الله وسنة رسوله فيما استطعت)(٢).", "(١) سورة الفتح: الآية ١٠.", "(٢) تنوير الحوالك ٢٥٠/٢ وانظر البيعة في الفكر السياسي الإسلامي ص٨٢ - ٨٣، والبخاري ٣١٨/١٣."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0044.png"}, {"n": 45, "paras": ["٣ - قرينة الحال: وهي جائزة في سائر أنواع العقود إلا في عقد النكاح. فانتظام المسلم برامج الجماعة وأنشطتها ولوائحها، والسمع والطاعة لقيادتها، وسماح الجماعة له بالحضور والمشاركة وممارسة حقوق العضوية تعبير عن تراضي الطرفين. وبذلك ينعقد العهد، بقرينة الحال وإن كانت دون المرتين السابقتين."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0045.png"}, {"n": 46, "paras": ["معالم المنهج في العقيدة سلفية في المنهج، وسنية في الإتباع", "السلف في اللغة جمع سالف، وهم القوم الماضون المتقدمون. وأصبح هذا المصطلح علماً على ما كان عليه الصحابة والتابعون من أهل القرون الفاضلة الثلاثة المشهود لها بالخير والإيمان والفضل والإحسان ومن تبعهم دون من وصف ببدعة أو رمي بتحريف. وهي مرحلة تمثل نقاء النبع، وصفاء المنهج المتلقى من مشكاة النبوة عذباً زلالاً، وسائغاً فراتاً، لم تكدره الشوائب، ولم تشبه المعكرات. اجتمع لهم فيه كمال العلم والعمل والحال فكانوا أبر هذه الأمة قلوباً، وأعمقها إيماناً، وأسلمها نظراً، وأقلها تكلفاً، وأشملها استيعاباً، وأدقها فهماً. وكان أبرز سمات منهجهم، هو شمول الفهم، وسلامة التصور، وصحة الاعتقاد، واعتدال الفكر، وتوازن السلوك، وتكامل البناء، ورعاية الأولويات، ومرحلية البناء، واتباع الدليل، ولزوم الحق، وترك الأهواء، والإعراض عما لا يبنى عليه عمل، ونبذ التكلف، ومواجهة مستجدات العصر، وإدراك مشكلات الواقع، ومجانبة البدع، ورعاية أدب الخلاف، والسعي في مصالح المسلمين، وبذل النصح لهم، والصدع بكلمة الحق، ومقارعة الباطل، والتشمير في الطاعات، يوالون ويعادون ويحبون ويبغضون في الله. فكانوا أهلاً لهذه الخيرية التي نطقت بها النصوص. على هذه المنهجية بنى الإمام البنا دعوته: (إنها دعوة سلفية لأنهم يدعون"], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0046.png"}, {"n": 47, "paras": ["إلى العودة بالإسلام إلى معينه الصافي من كتاب الله وسنة رسوله(١) (وطريقة سنية لأنهم يحملون أنفسهم على العمل بالسنة المطهرة في كل شيء، وبخاصة في العقائد والعبادات ما وجدوا إلى ذلك سبيلاً)(٢). وسأبدأ ببيان منهجه في العقيدة.", "(١) (٢) المؤتمر الخامس ص ١٢٢ من مجموعة الرسائل."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0047.png"}, {"n": 48, "paras": ["معالم المنهج في العقيدة عند الإمام البنا", "الدعوة إلى بناء العقيدة باعتقاد منهج السلف الصالح:", "- أما حثه عليها فقد قال في الأصل السابع عشر: (والعقيدة أساس العمل، وعمل القلب أهم من عمل الجارحة وتحصيل الكمال في كليهما مطلوب شرعاً وإن اختلفت مرتبتا الطلب). قال تعالى: ﴿ولقد أوحي إليك وإلى الذين من قبلك لئن أشركت ليحبطن عملك ولتكونن من الخاسرين، بل الله فاعبد وكن من الشاكرين﴾(١).", "- وأما عمل القلب فقد قال تعالى: ﴿ولكن يؤاخذكم بما كسبت قلوبكم﴾(٢) وإذا حلّت الهداية قلباً نشطت للعبادة الأعضاء.", "- بيان أهمية رباطها: (وأريد بالأخوة أن ترتبط القلوب برباط العقيدة، والعقيدة أوثق الروابط وأقواها)(٣)، (إن أول درجة من درجات القوة قوة العقيدة والإيمان)(٤).", "- بيان أهمية دعوة الناس إليها: (لب دعوتهم فكرة وعقيدة يقذفون بها نفوس الناس، ليتربى عليها الرأي العام وتؤمن بها القلوب وتجتمع من حولها الأرواح)(٥).", "- أصدر رحمه الله - رسالتين - كانت إحداهما: حول (العقيدة في الله).", "(١) سورة الزمر: الآية ٦٥.", "(٢) سورة البقرة: الآية ٢٢٥.", "(٣) مجموعة الرسائل ص ٢٢.", "(٤) المصدر السابق ص ١٣٥.", "(٥) المصدر السابق."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0048.png"}, {"n": 49, "paras": ["والثانية: رسالة العقائد كان من المقرر أن تحتوي على أربعة أقسام رئيسة وهي:", "١ - الإلهيات: وتبحث فيما يتعلق بالإله سبحانه وتعالى من حيث صفاته وأسمائه وأفعاله وما يستلزمه اعتقاد من العبد لمولاه.", "٢ - النبوات: وتبحث في كل ما يتعلق بالأنبياء صلوات الله وسلامه عليهم من حيث صفاتهم وعصمتهم ومهماتهم ورسالاتهم. ويلحق بهذا القسم ما يتعلق بالأولياء والمعجزة والكرامة.", "٣ - الروحانيات: وتبحث فيما يتصل بالعالم غير المادي كالملائكة عليهم السلام والجن والروح.", "٤ - السمعيات: وتبحث فيما يتعلق بالحياة البرزخية كأحوال القبر والدار الآخرة كعلامات الساعة، والبعث والموقف والجزاء. والرسالة المطبوعة باسم (العقائد) اشتملت على القسم الأول فقط وهو قسم (الإلهيات).", "- تركيزه عليها من خلال الأصول العشرين: الناظر المتأمل إلى الأصول العشرين يدرك أن مباحث العقيدة قد نالت اهتماماً بالغاً، وتركيزاً مكثفاً بتوضيح معالمها، وتأسيسها أهميتها.", "- ففي الأصل الأول: موقع العقيدة في إطار المنهج الشامل.", "- وفي الأصل الثاني: بيان الأصلين الذين تستقى منهما العقيدة والأخلاق والعبادة والتشريع.", "- وفي الأصل العاشر: ذكر التوحيد بأنواعه - الربوبية - الألوهية - الأسماء والصفات.", "- وفي الأصل الرابع والحادي عشر والرابع عشر: ذكر ما يخل بتوحيد العبادة."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0049.png"}, {"n": 50, "paras": ["- وفي الأصل الثالث والسابع عشر: ذكر أثر العقيدة في النفوس وبيان لارتباط العقيدة بالعمل.", "- وفي الأصل الثامن عشر والتاسع عشر: ذكر طريقي المعرفة الشرعية، والوضعية.", "- وفي الأصل العشرين: نواقض الإيمان والعقيدة.", "- وفي الأصل الثالث عشر: في الأولياء والصالحين.", "- وفي الأصل التاسع: تقرير منهج السلف في السكوت عما لا ينبني عليه عمل."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0050.png"}, {"n": 51, "paras": ["سمات منهجه في عرض العقيدة", "أولاً: اعتماده منهج القرآن الكريم والسنة المطهرة والسلف الصالح بعيداً عن اصطلاحات الجدليين والكلاميين: وقد تعددت أقواله واستفاضت في تأكيد هذا المنهج: أ - يقول رحمه الله: (لن ألجأ إلى المصطلحات الفنية التي تواضع عليها العلماء المختصون بعلم الكلام، ولن أحاول الخوض في النظريات الفلسفية، أو الأساليب المنطقية التي درج عليها المتكلمون حين يعالجون مثل هذه الموضوعات، ولكني سألجأ إلى القرآن الكريم، وإلى السنة المطهرة، وإلى ما عرفنا من سيرة الصدر الأول من المؤمنين بهذا الدين. وهم لا شك أصفى الناس فطرة وألينهم قلوباً، وأدقهم إدراكاً للمقاصد وأعرفهم بمواقع الألفاظ، والجمل والتراكيب، وأعذبهم تذوقاً لدقائق المعاني والمشاعر)(١). ب - ويقول في موضع آخر: (اعتقد أن واجبنا أن نعود سريعاً إلى ما كان عليه سلفنا الصالح وأن نستقي العقيدة من هذا النبع الصافي الذي لا لبس فيه ولا غموض)(٢). ج - ويقول: (وعمادنا في ذلك كتاب الله الذي لا يأتيه الباطل من بين يديه ولا من خلفه، والسنة الصحيحة الثابتة عن رسول الله ﷺ والسيرة المطهرة لسلف هذه الأمة)(٣).", "(١) الله في العقيدة الإسلامية.", "(٢) الله في العقيدة الإسلامية ص ٩٢٨.", "(٣) مجموعة الرسائل ص ٨٤."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0051.png"}, {"n": 52, "paras": ["د - ويرى: (الاعتماد على طريقة الكريم والرسول ﷺ في توصيل العقائد الدينية إلى النفوس، واستيلائها على المشاعر والقلوب دون تعمق في الألفاظ أو تشعب في البحوث، أو إيراد للآراء والمذاهب أو خوض في مصطلحات الفلاسفة والمناطقة والكلاميين والجدليين، وتلك طريقة السلف الصالح رضوان الله عليهم)(١).", "ثانياً: الاهتمام ببيان أثر العقيدة على النفوس: فقد كان يرى ضرورة: (العناية ببيان آثار هذه العقائد في النفوس ليعلم القارىء أين نفسه من درجة استيلاء العقيدة الإسلامية عليه، فإن كانت متأثرة بها حمد الله على نعمته، وإن كانت هذه الآثار ضعيفة في نفسه عمل على علاجها وتقوية إيمانه. فقد كانت العقائد عند أسلافنا عواطف مستقرة في القلوب، ومشاعر مستولية على النفوس، فلما أن صارت عندنا جدلاً وكلاماً، ضعف إيمان الأمة، وتسرب إلى دينها الخلل والوهن)(٢).", "ثالثاً: رد الشبهات العقائدية الحديثة: وهذا في الحقيقة إعمال لمنهج السلف الذين جابهوا تحديات عصرهم وزمانهم. (وستتبع ذلك عند مناسباته، برد الشبهات الحديثة)(٣).", "رابعاً: اعتماده طريقي المعرفة، النقلية والعقلية: إذ هما مصدرا المعرفة. فالمعرفة النقلية مصدرها الوحي بشقيه الكتاب والسنة. والمعرفة العقلية مصدرها الكون بشقيه الطبيعي والبشري. وذلك وفق قاعدة موافقة صحيح المنقول لصريح المعقول، ودرء تعارض العقل والنقل. يقول في الأصل الثامن عشر: (والإسلام يحرر العقل، ويحث على النظر في الكون، ويرفع قدر العلم والعلماء ويرحب بالصالح النافع من كل شيء). (والحكمة ضالة المؤمن أنى وجدها فهو أحق الناس بها).", "(١) العقائد ص ٤.", "(٢) (٣) العقائد ص ٥٢٤."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0052.png"}, {"n": 53, "paras": ["وفي الأصل التاسع عشر: (وقد يتناول كل من النظر الشرعي والعقلي ما لا يدخل في دائرة الآخر، ولكنهما لن يختلفا في القطعي، فلن تصطدم حقيقة صحيحة بقاعدة شرعية ثابتة، ويؤول الظني منهما ليتفق مع القطعي، فإن كانا ظنيين فالنظر الشرعي أولى بالاتباع حتى يثبت العقلي أو ينهار) وهذا خلاصة ما انتهى إليه أهل التحقيق في هذه المسألة.", "وقد أفاد رحمه الله من الحقائق العلمية المعاصرة في الاستدلال بها على سبيل الاستئناس والاستنباط أخذاً بقوله تعالى: ﴿وفي أنفسكم أفلا تبصرون﴾(١)، وقوله: ﴿سنريهم آياتنا في الآفاق وفي أنفسهم حتى يتبين لهم أنه الحق﴾(٢) والآيات نوعان، تنزيلية في كتاب الله المقروء، وكونية في صفحة الكون المنظور وكلاهما مطلوبان في التسخير إلى عبادة الله تعالى، وإقامة الحجة على الخلق، وتثبيت أهل الإيمان، فإن الإيمان يتضافر بتضافر الأدلة. قال رحمه الله: (ويجب أن تعلم مع ذلك أن كل هذه العقائد يؤيدها العقل، ويثبتها النظر الصحيح، ولهذا شرف الله تعالى العقل بالخطاب، وجعله مناط التكليف، وندبه إلى البحث والنظر والتفكير). قال تعالى: ﴿قل انظروا ما في السموات والأرض وما تغني الآيات والنذر عن قوم لا يؤمنون﴾(٣)(٤).", "خامساً: تقوية الصلة بين الوجدان الإنساني والخالق جلّ وعلا: حتى يصل الإنسان بذلك إلى نوع من المعرفة الروحية القلبية وهي أصدق وأعذب أنواع المعرفة. قال الحسن البصري: (العلم علمان: علم في اللسان فذاك حجة الله على ابن آدم، وعلم القلب، فذاك العلم النافع)(٥). فالعلم بالله والمعرفة بأسمائه وصفاته، هي أجل أنواع العلوم لأنها تثمر الحقائق الإيمانية، والمعارف الوجدانية التي تصل الأرواح بالملأ الأعلى.", "(١) سورة الذاريات: الآية ٢١.", "(٢) سورة فصلت: الآية ٥٣.", "(٣) سورة يونس: الآية ١٠١.", "(٤) مجموعة الرسائل ص ٣٨٠.", "(٥) فضل علم السلف على الخلف ص ٦٨."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0053.png"}, {"n": 54, "paras": ["سادساً: أخذه بمبدأ الشمول: فالعقيدة لا تؤخذ عنده أجزاء تفاريق، ولا تقبل عضين، بل هي منهج عضوي في إطار بناء متكامل. إذ لا تنفصل العقيدة عن الحياة، لتبقى في إطار تجريدي. بل يراد منها أن تكون منهجاً للحياة وأساساً للنظم. ولئن فتن الناس في بعض العهود بشرك الأوثان والأموات، فإن شرك الأحياء والأوضاع والنظم قد عظم خطره، واستطار شرره.", "سابعاً: البعد عن مداحض التكفير ومزلة التضليل: قال في الأصل العشرين: (لا نكفر مسلماً أقر بالشهادتين وعمل بمقتضاها وأدى الفرائض - برأي أو معصية - إلا إن أقر بكلمة الكفر، أو أنكر معلوماً من الدين بالضرورة، أو كذب صريح القرآن، أو فسره على وجه لا تحتمله أساليب اللغة العربية بحال، أو عمل عملاً لا يحتمل تأويلاً غير الكفر). وقال في موضع آخر: (نعتقد إلى جانب هذا أن تأويلات الخلف لا توجب الحكم بكفر ولا تفسيق)(١).", "إن تكفير المسلم إنما يكون بأمر قاطع، لا احتمال فيه ولا اشتباه، إذ مثله يكون من المحكمات الواضحات، والأحكام الجليات، وكل من أتى بالشهادتين فقد عصم دمه إلا بحقها المنصوص عليها. والدلائل في ذلك كثيرة مستفيضة، والحكم بالكفر تترتب عليه آثار جد خطيرة أشار إليها الدكتور القرضاوي منها:", "١ - إنه لا يحل لزوجته البقاء معه ويجب أن يفرّق بينهما.", "٢ - عدم بقاء أبنائه تحت سلطانه خشية أن يؤثر عليهم بكفره.", "٣ - فقدان حق الولاية والنصرة على المجتمع الإسلامي.", "٤ - ينفذ فيه حكم المرتد بعد استتابته وإزالة الشبهات عنه وإقامة الحجة عليه.", "(١) العقائد ص ٧٦."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0054.png"}, {"n": 55, "paras": ["ه - لا تحل ذبيحته.", "٦ - إذا مات لا تجري عليه أحكام المسلمين، فلا يغسل ولا يصلى عليه، ولا يدفن في مقابر المسلمين، ولا يرث ولا يورث.", "٧ - موته على الكفر يستوجب لعنة الله وطرده من رحمته والخلود في النار(١). يقول ابن تيمية: (ليس لأحد أن يكفر أحداً من المسلمين وإن أخطأ وغلط حتى تقام عليه الحجة، وتبين له المحجة ومن ثبت إسلامه بيقين، لم يزل ذلك عنه بالشك بل لا يزول إلا بعد إقامة الحجة وإزالة الشبهة)(٢). فأهل السنة والجماعة عندهم الكفر كفران: كفر يوجب لصاحبه الخلود في النار وهو الكفر الأكبر المخرج عن ملة الإسلام. وكفر لا يستوجب صاحبه الخلود في النار وهو الكفر الأصغر الذي يسمى كفر النعمة أو المعصية، وهذا يستحق صاحبه الوعيد دون الخلود. والوعيد قد يتخلف إما لحسنات ماحية، أو مصائب يبتلى بها، أو شفاعة، وأعظم من ذلك رحمة الله تعالى. كما أنهم يطلقون التفريق بين القول الذي قد يكون كفراً وبين قائله الذي لا يحكمون عليه بالكفر إلا بعد إقامة الحجة عليه وتعليمه وإزالة الشبهة عنه. يقول ابن تيمية: (وأصل ذلك أن المقالة التي هي كفر بالكتاب والسنة والإجماع يقال هي كفر قولاً يطلق، كما دل على ذلك الدلائل الشرعية فإن (الإيمان) من الأحكام المتلقاة عن الله ورسوله، ليس ذلك مما يحكم فيه الناس بظنونهم وأهوائهم. ولا يجب أن يحكم في كل شخص قال ذلك بأنه كافر حتى يثبت في حقه شروط التكفير، وتنتفي موانعه، مثل من قال إن الخمر أو الربا حلال لقرب عهده بالإسلام، أو لنشوئه في بلدة بعيدة، أو سمع كلاماً أنكره ولم يعتقد أنه من القرآن ولا من أحاديث رسول الله ﷺ)(٣).", "(١) ظاهرة الغلو في التفكير ص ٢٣ - ٢٤.", "(٢) الفتاوى ٤٦٦/١٢.", "(٣) التوسل أنواعه وأحكامه ص ٤١."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0055.png"}, {"n": 56, "paras": ["وفي التحذير من تكفير علماء الأمة بسبب اجتهاد يقول رحمه الله: (إن علماء المسلمين المتكلمين في الدنيا باجتهادهم لا يجوز تكفير أحدهم بمجرد خطأ أخطأه في كلامه، فإن تسليط الجهال على تكفير علماء المسلمين من أعظم المنكرات، وإنما أصل هذا من الخوارج والروافض الذين يكفرون أئمة المسلمين وقد اتفق أهل السنة والجماعة على أن علماء المسلمين لا يجوز تكفيرهم بمجرد الخطأ المحض، بل كل أحد يؤخذ من قوله ويترك إلا رسول الله ﷺ، وليس كل من يترك بعض كلامه خطأ أخطأه يكفر ولا يفسق)، (وإني أقرر أن الله قد غفر لهذه الأمة خطأها وذلك يعم الخطأ في المسائل الخبرية القولية، والمسائل العلمية)(١).", "هذه أبرز سمات المنهج الذي سلكه البنا في تأصيل العقيدة موافقاً لما سلكه الأعلام ممن ساروا على منهج السلف الصالح رضوان الله عليهم.", "شبهتان: أثيرت حول منهج الإمام البنا في العقيدة مسألتان: إحداهما: تتصل بمسألة الأسماء والصفات. والثانية: تتعلق بموضوع التوسل. وقد أفاض الشيخ جاسم مهلهل في الرد على هاتين النقطتين في فصل عقده في كتابه: (للدعاة فقط) فجزاه الله خيراً. وأود هنا أن أوجز القول في هاتين المسألتين إكمالاً للبحث، وإتماماً للفائدة:", "١ - موضوع التوسل: وجه الاعتراض فيه كونه ليس من مسائل العقيدة، وأنه موضع خلاف.", "(١) الفتاوى ٢٢٩/٣ - ٢٣١."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0056.png"}, {"n": 57, "paras": ["وقد تبين لي بعد التتبع والاستقراء أن ما أشار إليه البنا قد قاله العلماء من قبل فأي نكير عليه في ذلك. إن التوسل المتفق على جوازه أنواع:", "١ - التوسل بأسماء الله الحسنى وصفاته العليا.", "٢ - التوسل بعمل صالح قام به الداعي.", "٣ - التوسل بدعاء رجل صالح (بأن يدعو ويؤمن على دعائه)(١). وأما ما سوى هذه الأنواع فهو موضع نزاع بين أهل العلم وإليك أقوالهم: يقول ابن تيمية: (وأما قول القائل اللهم إني أتوسل إليك به فللعلماء فيه قولان، كما لهم في الحلف به قولان...). وفي الجملة فقد نقل عن بعض السلف والعلماء السؤال به بخلاف دعاء الموتى والتائبين والاستغاثة بهم(٢). كما نص على ذلك الشيخ محمد بن عبدالوهاب حيث قال في المسألة العاشرة: (قولهم في الاستسقاء لا بأس بالتوسل بالصالحين، وقول أحمد يتوسل بالنبي ﷺ خاصة مع قولهم إنه لا يستغاث بمخلوق فالفرق ظاهر جداً، وليس الكلام مما نحن فيه، فكون بعض يرخص بالتوسل بالصالحين، وبعضهم يخصه بالنبي ﷺ وأكثر العلماء ينهى عن ذلك ويكرهه، فهذه المسألة من مسائل الفقه ولو كان الصواب عندنا قول الجمهور أنه مكروه فلا ننكر على من فعله)(٣). فقد تضمن كلام الشيخ أن التوسل بالصالحين، أو بالنبي ﷺ", "(١) التوسل أنواعه وأحكامه ص ٤١.", "(٢) التوسل والوسيلة ص ٩٥.", "(٣) مجموعة فتاوى الشيخ محمد ب عبدالوهاب ص ٦٨ - ٦٩."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0057.png"}, {"n": 58, "paras": ["هو مع موضع خلاف بين العلماء، وأن هذه المسألة من مسائل الفقه وهذا عين ما قرره البنا.", "وقال الشيخ الألباني بعد ذكره لأنواع التوسل المتفق عليها: (وأما ما عدا هذه الأنواع من التوسلات ففيه خلاف إلى أن قال مع أنه قال ببعضه بعض الأئمة، فأجاز الإمام أحمد التوسل بالرسول ﷺ وحده، وأجاز غيره كالإمام الشوكاني به وبغيره من الصالحين)(١).", "وقال في فقه العقيدة الطحاوية: (فهذه سبع مسائل هامة كلها في العقيدة إلا الأخيرة منها وهي كراهة التوسل بحق الأنبياء وجاههم)(٢). فهذه الأقوال تؤكد ما أشار إليه البنا من وجود الخلاف فيه، ومن كونه من مسائل الفقه لا العقيدة. ولعل منشأ الخلط آت من عدم التفريق بين الاستغاثة والتوسل. فإن الاستغاثة هي التي تندرج في مباحث العقيدة. يقول ابن تيمية: (لم يقل أحد إن التوسل بالنبي ﷺ استغاثة به، بل العامة الذين يتوسلون في أدعيتهم بأمور يعلمون أنهم لا يستغيثون بهذه الأمور، فإن المستغيث بالنبي ﷺ طالب منه، وسائل له، والمتوسل به لا يدعو ولا يطلب منه، ولا يسأل، وإنما يطلب به، وكل أحد يفرق بين المدعو والمدعو به)(٣) ويقول رحمه الله: (والاختلاف فيما يشرع من الدعاء، وما لا يشرع، كاختلافهم هل تشرع الصلاة عليه عند الذبح وليس هو من مسائل السب عن أحد من المسلمين)(٤).", "الشبهة الثانية: وهي مسألة التفويض في الأسماء والصفات وأنها من المتشابه. قال رحمه الله: (ونحن نعتقد أن رأي السلف من السكوت وتفويض علم هذه المعاني إلى الله تبارك وتعالى أسلم وأولى بالاتباع حسماً لمادة التأويل والتعطيل). يقول هؤلاء أن التفويض معناه تفويض معاني صفات الله تعالى مع الاعتقاد.", "(١) التوسل ص ٤١.", "(٢) مقدمة الطحاوية ص ٥٥.", "(٣) باختيار الفتاوى ١٠٣/٣٥.", "(٤) المصدر السابق ١٠٦/٣٥."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0058.png"}, {"n": 59, "paras": ["بأن ظواهرها غير مرادة وليس هذا مذهب السلف لأن الله تعالى لا يخاطبنا بما لا نعقل معناه فهم يفوضون الكيف لا المعنى. والجواب: إن المنهج العلمي يقتضي فهم العبارة ملتئمة مع سائر النصوص والأقوال دون أخذها مجتزأة. فالعبارة جاءت منكرة وليست معرفة فهي لا تعني المذهب المذكور ولكنها استعملت بمعناها اللغوي بمعنى عدم الخوض في كيفية الاستواء أو غيره من الصفات وترك ذلك إلى الله تعالى. فإذا أضيف إلى ذلك أن الرجل أكد ترجيحه لمذهب السلف، وارتضاءه له، واستشهاده بأقوالهم، وأن هذه العبارة وردت في كلام غيره من الأعلام فإنه يتعين فهم مراده على هذا الوجه. وإليك بعضاً من نصوصه في هذه المسألة لنصل إلى فهم النص المذكور.", "١ - قال رحمه الله: (أما السلف فقالوا نؤمن بهذه الآيات والأحاديث كما وردت ونترك بيان المقصود منها لله تبارك وتعالى فهم يثبتون اليد والعين والاستواء والضحك والتعجب . . . إلخ.، ونترك لله تبارك وتعالى الإحاطة بعلمها)(١).", "٢ - (قدمت بلك أن السلف رضوان الله عليهم يؤمنون بآيات الصفات وأحاديثها كما وردت ويتركون بيان المقصود منها لله تبارك وتعالى مع اعتقادهم بتنزيه الله تبارك وتعالى عن المشابهة لخلقه)(٢).", "٣ - (قد علمت أن مذهب السلف في الآيات والأحاديث التي تتعلق بصفات الله تبارك وتعالى أن يمروها على ما جاءت عليه ويسكتوا عن تفسيرها وتأويلها وأن مذهب الخلف أن يؤولوها بما يتفق مع تنزيه الله تبارك وتعالى عن مشابهة خلقه)(٣).", "(١) العقائد ص ٦٦.", "(٣) المصدر السابق ص ٧٦.", "(٢) المصدر السابق ص ٧٠."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0059.png"}, {"n": 60, "paras": ["٤ - عند احتجاجه بأقوال السلف ذكر منهم اللالكائي في (أصول السنة) ونقل عن محمد بن الحسن صاحب أبي حنيفة ونقل عن الخلال في (كتاب السنة) نصوصاً عن أحمد بن حنبل ثم نقل عن مالك بن أنس، وذكر (أبو بكر الأثرم) و(أبو عمرو الطلمنكي) و(أبو عبدالله بن بطة) وغيرهم من الأئمة الأثبات الذين ساروا على نهج السلف الصالح. كما أشار إلى ذلك ابن تيمية(١). قال رحمه الله: (وكلام السلف في هذا الباب موجود في كتب كثيرة مثل كتاب السنة للالكائي والإبانة لابن بطة، والأصول لأبي عمرو الطلمنكي والسنة لأبي بكر بن الأثرم، والسنة للخلال، والسنة لأبي بكر بن أبي عاصم)(٢).", "٥ - نقل عن أبي عبدالله بن أبي سلمة الماجشون كلاماً مختصراً لعقيدة السلف في الأسماء والصفات وقد ذكر هذا النص بتمامه ابن تيمية في الفتاوى(٣).", "٦ - علّق على بعض آيات الأسماء والصفات وذكر معانيها مثل قدم الله تعالى وبقائه، ومثل علمه سبحانه وتعالى وقيام الله تعالى بنفسه.", "٧ - أنه صرّح بمراد الكيفية تصريحاً بيناً في قوله: (وإنما علم الله تبارك وتعالى علم لا يتناهى كماله، ولا يعدّ علم المخلوقين شيئاً إلى جانبه، وكذلك الحياة، وكذلك السمع... فهذه كلها مدلولات الألفاظ فيها تختلف عن مدلولاتها في حق الخلق. من حيث الكمال والكيفية اختلافاً كلياً لأنه تعالى لا يشبه أحداً من خلقه، فتفطن لهذا المعنى فإنه دقيق. ولست مطالباً بمعرفة كنهها(٤) وإنما حسبك أن تعلم آثارها في الكون، ولوازمها في حقك)(٥).", "(١) انظر الفتاوى ٥٢/٦.", "(٢) بتصرف الفتاوى ٢٤/٥.", "(٣) انظر الفتاوى ٤٥/٥.", "(٤) أي كيفيتها.", "(٥) العقائد ص ٤٩."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0060.png"}, {"n": 61, "paras": ["٨ - ارتضاؤه منهج السلف وتعويله عليه: (فإن كنت ممن أسعده الله بطمأنينة الإيمان، وأثلج صدره ببرد اليقين فلا تعدل به بديلاً(١). وجعله أسلم وأولى بالاتباع حسماً لمادة التأويل والتعطيل(٢) فأين هذا من التفويض؟ من مجموع هذه النصوص يتضح أن مراد الإمام البنا هو تفويض الكيفية لا المعنى. على أن العبارة التي اشتد فيها النكير وفسرنا مراده فيها قد جاءت في كلام الأئمة ممن هم على منهج السلف الصالح.", "فقد جاء عن محمد بن الحسن الشيباني: (اتفق الفقهاء كلهم من المشرق إلى المغرب على الإيمان بالقرآن والأحاديث التي جاءت بها الثقات عن رسول الله ﷺ في صفة الرب عز وجل من غير تفسير ولا وصف ولا تشبيه، فمن فسر اليوم شيئاً من ذلك فقد خرج مما كان عليه النبي ﷺ وفارق الجماعة فإنهم لم يصفوا ولم يفسروا، ولكن أفتوا بما في الكتاب والسنة ثم سكتوا)(٣).", "ونقل الخلال عن أحمد بن حنبل: (نؤمن بها ونصدق بها ولا كيف ولا معنى، ولا نرد منها شيئاً، ونعلم أن ما جاء به الرسول ﷺ حق إذا كان بأسانيد صحاح)(٤). وجاء عن ابن رجب الحنبلي في فضل علم السلف على الخلف: والصواب ما عليه السلف الصالح من إمرار آيات الصفات وأحاديثها كما جاءت من غير تفسير لها... ولا يصح منهم خلاف ذلك البتة خصوصاً الإمام أحمد ولا خوض في معانيها، وكذلك ما جاء عن ابن قدامة في لمعة الاعتقاد حين عرض لمسألة الصفات، وتلقيها بالتسليم والقبول أشار إلى ترك التعرض إلى معناها، ورد علمها إلى قائلها(٥).", "فهذه العبارات ونحوها حملت على معنى الكيفية من خلال الجمع بين أقوالهم تحقيقاً للإنصاف، وإحساناً للظن بهم وبالمنهج نفسه نتعامل مع أقوال البنا لما عرف عنه من شدة الحرص على اتباع السنة ولزومها، وسلوك منهج السلف الصالح رضي الله عنهم أجمعين.", "(١) (٢) المصدر السابق ص ٧٦.", "(٤) العقائد ص ٦٧.", "(٥) انظر اللمعة بشرح ابن عثيمين ص ٢٠."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0061.png"}, {"n": 62, "paras": ["أما الأمر الثاني: وهو إطلاق لفظ المتشابه على الصفات فإنه محمول على معنى أن كيفية اتصاف المولى تبارك وتعالى بهذه الصفات مما استأثر سبحانه بعلمه، ولا سبيل للبشر إلى إدراكه والإطلاق بهذا المعنى سائغ ومقبول. يقول الشيخ الشنقيطي في جواز إطلاق لفظ المتشابه على الصفات من هذه الحيثية: (اعلموا أن آيات الصفات كثير من الناس يطلق عليها اسم المتشابه وهذا من جهة غلط، ومن جهة قد يسوغ، كما بينه مالك بن أنس بقوله: (الاستواء غير مجهول، والكيف غير معقول، والسؤال عنه بدعة، والإيمان به واجب) فكون الاستواء غير مجهول يدل على أن معناه غير متشابه بل هو معروف عند العرب، والكيف غير معقول يدل على عجز البشر عن إدراكه وما استأثر الله بعلمه يسمى متشابهاً بناء على الوقف في قوله تعالى: ﴿وما يعلم تأويله إلا الله﴾ فهو بالنسبة إلى الصفة غير متشابه، وبالنسبة إلى كيفية الاتصاف به متشابه على المتشابه ما استأثر الله بعلمه)(١). ثم إن مفهوم المتشابه مما اختلفت فيه أنظار العلماء فيما ذكره السيوطي في (الإتقان) في تفسير المحكم والمتشابه فبعضهم يقول: إن المحكم ما لا يحتمل من التأويل إلا وجهاً واحداً والمتشابه ما احتمل أوجهاً وعزاه السيوطي لابن عباس. وعلى هذا التفسير كتب الإمام أحمد بن حنبل كتابه (الرد على الجهمية والزنادقة فيما شكوا فيه من متشابه القرآن وتأولوه على غير تأويله). ومنهم من يقول المحكم ما عرف المراد منه إما بالظهور وإما بالتأويل. والمتشابه ما استأثر الله بعلمه كقيام الساعة، وخروج الدجال، والحروف المقطعة في أوائل السور. ومنهم من يقول المحكم الذي يؤمن به ويعمل به والمتشابه الذي يؤمن به ولا يعمل به.", "(١) منهج دراسات الأسماء والصفات ص ٣٢."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0062.png"}, {"n": 63, "paras": ["ومنهم من قال المحكم ما كان معقول المعنى، والمتشابه(١) خلافه. وقد جاء في القرآن الكريم: ﴿الله نزل أحسن الحديث كتاباً متشابهاً﴾(٢) أي يشبه بعضه بعضاً وجاء وصفه كله بأنه محكم: ﴿كتاب أحكمت آياته﴾(٣) أي بمعنى الإتقان. وجاء وصف بعضه بالمتشابه: ﴿منه آيات محكمات هن أم الكتاب، وأخر متشابهات﴾(٤). وهذا ما وقع الخلاف في تفسيره على النحو الذي أسلفنا. وخلاصة القول أن منهج البنا جاء مقرراً لعقيدة السلف، داعياً إلى لزومها وتثبيتها فجزاه الله أفضل ما يجزي دعاة الإسلام الصادقين.", "(١) انظر مبحث المحكم والمتشابه في الإتقان وغيره من كتب علوم القرآن.", "(٢) سورة الزمر: الآية ٢٣.", "(٣) سورة هود: الآية ١.", "(٤) سورة آل عمران: الآية ٧."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0063.png"}, {"n": 64, "paras": ["وسطية المنهج الفقهي بين دعاة المذهبية ومخالفيهم", "مسألة التمذهب والتقليد تعاورها طرفان غاليان، وثالث معتدل: الأول: فريق يوجب النظر على كل أحد: قال ابن تيمية: (وكذلك المسائل الفروعية: من غالية المتكلمة والمتفقهة من يوجب النظر والاجتهاد فيها على كل أحد، حتى على العامة، وهذا ضعيف، لأنه لو كان طلب علمها واجباً على الأعيان فإنما يجب مع القدرة، والقدرة على معرفتها من الأدلة المفصلة تتعذر أو تتعسر على أكثر العامة)(١). الثاني: فريق يوجب التقليد على كل أحد: قال ابن تيمية: (وبإزائهم من أتباع المذاهب من يوجب التقليد فيها على جميع من بعد الأئمة علمائهم وعوامهم)(٢). وهذا ما عناه صاحب «الجوهرة» في التوحيد بقوله: وواجب تقليد حبر منهم كما حكى القوم بلفظ يفهم وكلا طرفي الأمر قد حاد عن جادة الصواب. الثالث: معتدل متوسط: وهو الذي عليه جماهير الأمة أن الاجتهاد جائز في الجملة، والتقليد جائز في الجملة، لا يوجبون الاجتهاد على كل أحد ويحرمون التقليد، ولا", "(١) (٢) الفتاوى ٢٠٣/٢٠."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0064.png"}, {"n": 65, "paras": ["يوجبون التقليد على كل أحد ويحرمون الاجتهاد، وأن الاجتهاد جائز للقادر على الاجتهاد، والتقليد جائز للعاجز عن الاجتهاد. فأما القادر على الاجتهاد فهل يجوز له التقليد؟ هذا فيه خلاف، والصحيح أنه يجوز حيث عجز عن الاجتهاد إما لتكافؤ الأدلة، وإما لضيق الوقت على الاجتهاد، وإما لعدم ظهور دليل له. فإنه حيث عجز سقط عنه وجوب ما عجز عنه وانتقل إلى بدله وهو التقليد، كما لو عجز عن الطهارة بالماء. وكذلك العامي إذا أمكنه الاجتهاد في بعض المسائل جاز له الاجتهاد، فإن الاجتهاد منصب يقبل التجزؤ والإنقسام، فالعبرة بالقدرة والعجز، وقد يكون الرجل قادراً في بعض عاجزاً في بعض، لكن القدرة على الاجتهاد ولا تكون إلا بحصول علوم تفيد معرفة المطلوب فأما مسألة واحد من فن فيبعد الاجتهاد فيها(١). بهذا العرض المستوعب يتضح أن القول بإيجاب التقليد أو بتحريمه على وجه الإطلاق قول يجفوه الصواب، وينحسر عنه قناع الحق. بل لا بد من التفصيل في مقامات المكلفين وطبقاتهم. يقول الإمام البنا تأكيداً لما قرره شيخ الإسلام: (لكل مسلم لم يبلغ درجة النظر في أدلة الأحكام الفرعية أن يتبع إماماً من أئمة الدين، ويحسن به مع هذا الاتباع أن يجتهد ما استطاع في تعرف أدلة إمامه، وأن يتقبل كل إرشاد مصحوب بالدليل متى صح عنده صدق من أرشده وكافيته، وأن يستكمل نقصه العلمي إن كان من أهل العلم حتى يبلغ درجة النظر).", "في هذا الأصل جماع لما خلص إليه أهل العلم واعتمدوه في مسألة الاجتهاد والاتباع والتقليد محرراً مما علق به من عصبية للمذهبية أو معاداتها.", "أصناف الناس ومراتبهم: الناس بالنسبة في أمر الاجتهاد والتقليد ثلاث مراتب: الأولى: عالم يفقه الآيات ودلالتها، والأحاديث ومضامينها، راسخ في", "(١) الفتاوى ٢٠٤/٢٠."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0065.png"}, {"n": 66, "paras": ["معرفة قواعد الاستنباط، ومدارك الأدلة، وضوابط الاستدلال، وأصول التوفيق في ما ظاهره الاختلاف، ملمّ بلغة العرب، وتصاريفها، له خبرة بمدلولات الألفاظ، عارف بمواقع الاختلاف والإجماع ومسالك المجتهدين. الثانية: متبع ليست عنده القدرة على الاستقلال في البحث، واستخراج الدلالات من النصوص، واستنباط الأحكام منها لكنه في الوقت نفسه يفهم الحجة ويعرف الدليل. الثالثة: عامي لا يفقه معاني النصوص من القرآن والسنة ولا يستطيع الاستنباط منها، ولا معرفة ما يطلبان منه. يقول الأستاذ سعيد حوى: (الناس في الأحكام العملية التي هي مدار علم الفقه ثلاثة أقسام:", "١ - إنسان وصل إلى رتبة الاجتهاد.", "٢ - وإنسان عالم بمصادر القول وموارده ولم يصل إلى رتبة الاجتهاد.", "٣ - وإنسان عامي عادي. أما الأول فمكلف في السير على ما يوصله إليه اجتهاده وأما الثاني فمكلف أن يسير على رأي من اقتنع أن معه الحق من الأئمة. وأما الثالث فله أن يتابع أي إمام من الأئمة ممن سأله فأفتاه. فله أن يعمل بفتواه إن كان من أهل العلم أو من أهل الفتوى والهدى، ومن ثم قال العلماء: العامي لا مذهب له، وقالوا العامي مذهبه مذهب مفتيه)(١). بهذه الضوابط يفهم التقليد ويمنع من التعصب فيه. أما تحريمه مطلقاً أو إنكاره بدون ضوابط فهذا مما يعد مخالفاً لما اعتمده أهل العلم. قال ابن عبدالبر: (العامة لا بد لها من تقليد علمائها عند النازلة تنزل بها، لأنها لا تتبين موقع الحجة، ولا تصل لعدم الفهم إلى علم ذلك. لأن العلم درجات", "(١) جولات في الفقهين الكبير والأكبر ص ٦١."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0066.png"}, {"n": 67, "paras": ["لا سبيل منها إلى أعلاها إلا بنيل أسفلها، وهذا هو الحائل بين العامة وطلب الحجة. ولم تختلف العلماء أن العامة عليها تقليد علمائها، وأنهم المرادون بقول الله عز وجل: ﴿فاسألوا أهل الذكر إن كنتم لا تعلمون﴾ وأجمعوا على أن الأعمى لا بد له من تقليد غيره ممن يثق بمعرفته بالقبلة إذا أشكلت عليه، فكذلك من لا علم له، ولا بصر بمعنى ما يدين به، لا بد له من تقليد عالمه، وكذلك لم يختلف العلماء أنه لا يجوز للعامة الفتيا، وذلك - والله أعلم - لجهلها بالمعاني التي يجوز التحليل والتحريم والقول في العلم(١).", "الضوابط العامة لمسألة التقليد:", "١ - إذا استبان للمقلد حكم صحيح بخلاف ما انتهى إليه إمام مذهبه وتيقن ذلك بصدق من أرشده وكفايته العلمية، ورسوخه الفقهي لزمه أن يتحرر من قوله إمامه أو مذهبه أو من قلده اتباعاً لما صح به الدليل وقوي به الأثر، ويحرم عليه أن يجعل فتاوى إمامه أو مذهبه بمنزلة نصوص الشارع. بل يعتقد أنه ما من أحد إلا راد ومردود عليه إلا رسول الله ﷺ.", "٢ - إذا تبصر إنسان بمعرفة مسألة ما من وجوهها المختلفة، وصورها المتعددة، وأحاط بأدلتها ونصوصها، فعليه أن يتبع في تلك المسألة ما انتهى إليه اجتهاده وأداه إليه علمه.", "٣ - إن العالم بمصادر الأدلة، وموارد النصوص، وقواعد الفهم إذا عجز عن الاجتهاد في مسألة ما إما لتكافؤ الأدلة أو لضيق وقته، أو لعدم ظهور دليل له جاز له التقليد. فالاجتهاد ليس أمراً واحداً، بل هو قابل للتجزء والانقسام.", "٤ - إن المقلد يجوز له له التنقل من مذهب إلى آخر بناء على قوة الحجة وظهور الدليل وليس من قبيل التتبع للرخص بغير مستند شرعي. فقد نقل الشاطبي عن ابن حزم: (أنه حكى الإجماع على أن تتبع رخص المذاهب", "(١) جامع بيان العلم وفضله باختصار ١٠٩/٢ - ١١٤."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0067.png"}, {"n": 68, "paras": ["بغير مستند شرعي فسق لا يحل)(١). وقال أبو المحاسن الروياني: (يجوز تقليد المذاهب والانتقال إليها بثلاثة شروط: أن لا يجمع بينها على صورة تخالف الإجماع: كمن تزوج بغير صداق ولا ولي ولا شهود، فإن هذه صورة لم يقل بها أحد. وأن يعتقد فيمن يقلده الفضل بوصول أخباره إليه، ولا يقلد أمياً في عماية وألا يتتبع رخص المذاهب)(٢). وقال ابن تيمية: (إن كان انتقاله من مذهب إلى مذهب لأمر ديني مثل أن يتبين رجحان قول على قول فيرجع إلى القول الذي يرى أنه أقرب إلى الله ورسوله فهو مثاب على ذلك بل واجب على كل أحد إذا تبين له حكم الله ورسوله في أمر أن لا يتعداه)(٣).", "ه - عدم التجاسر على الفتوى لمن ليس من أهلها، بل الواجب احترام التخصص، والرجوع في كل فن إلى عارفيه، فليس كل من قرأ الآية والآيتين، والحديث والحديثين نصب نفسه إماماً للفتيا. فدلائل النصوص مشتملة على الخاص والعام، والمطلق والمقيد، والمحكم والمتشابه، والناسخ والمنسوخ. والجلي والخفي، ثم هناك المعرفة اللازم بلغة العرب والخبرة بمدلولات الألفاظ، وتصاريف اللغة، والإدراك لمواضع الإجماع، ومواقع الاختلاف، وأسباب النزول، وتاريخ الحوادث وفتاوى الصحابة، والمعرفة بمسالك الاستدلال، وقواعد الاستنباط، ومدارك الأدلة، وشروط الرواية. إضافة إلى الورع الحاجز عن الهوى والاعتدال المانع من طرفي الغلو والتساهل. فالفتوى بغير علم عظيمة المغبة، وخيمة العاقبة.", "جاء عن ابن مسعود: (إن أحدكم ليفتي الفتوى لو سئل عنها عمر لجمع لها أهل بدر)(٤)، وكان أصحاب النبي ﷺ يتدافعون الفتيا، كل واحد ود لو أن أخاه كفاه، إذ أجرأ الناس على الفتيا أجرؤهم على النار، وإذا كان التوقيع عن الملوك بالمحل الذي لا يخفى فكيف بالتوقيع عن رب العالمين كما يقول ابن القيم(٥).", "(١) انظر الموافقات ١٣٤/٤. (٢) التقرير والتحبير ٣٥٢/٣.", "(٣) الفتاوى ٢٢٣/٢٠.", "(٤) (٥) انظر الجزء الأول من أعلام الموقعين."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0068.png"}, {"n": 69, "paras": ["وقد جعل سبحانه القول عليه بغير علم قريناً للشرك. قال تعالى: ﴿قل إنما حرم ربي الفواحش ما ظهر منها وما بطن والإثم والبغي بغير الحق وأن تشركوا بالله ما لم ينزل به سلطاناً وأن تقولوا على الله ما لا تعلمون﴾(١). وقال عز وجل: ﴿فاسألوا أهل الذكر إن كنتم لا تعلمون﴾(٢). وقال جل وعلا: ﴿ولو ردوه إلى الرسول وإلى أولي الأمر منهم لعلمه الذين يستنبطونه منهم﴾(٣).", "٦ - أن أحد المجتهدين إذا ترك العمل بحديث من الأحاديث لعذر من الأعذار المعتبرة مثل اعتقاده عدم صحة الحديث أو أن ظاهر القرآن يخالفه، أو القياس أو عمل بعض الأمصار ثم تبين لمن يقلده أن ظاهر القرآن لا يخالفه، وأنه صحيح مقدم على الظواهر والقياس والعمل. لم يكن عذر ذلك الإمام المجتهد عذراً في حقه. فإن ظهور المدارك الشرعية وخفاءها أمر لا ينضبط طرفاه(٤) فتعين عليه العمل بما أوجبه الحديث الذي اعتقد صحته ودلالته وإن خالف إمامه.", "بهذه الضوابط تتضح المعالم، وتستبين الرؤى بين التمذهب الصحيح، وبين التعصب المذهبي. وأختم هذه المسألة بكلمة جامعة للإمام ابن القيم: (إن الله تعالى أوجب على العباد أن يتقوه بحسب استطاعتهم. وأصل التقوى معرفة ما يتقى، ثم العمل به. فالواجب على كل عبد أن يبذل جهده في معرفة ما يتقيه مما أمره الله به ونهاه، ثم يلتزم طاعة الله ورسوله، وما خفي عليه، فهو فيه أسوة أمثاله ممن عدا الرسول، فكل أحد سواه قد خفي عليه بعض ما جاء به ولم يخرجه ذلك عن أهل العلم، ولم يكلفه الله ما لا يطيق من معرفة الحق واتباعه)(٥).", "(١) سورة الأعراف: الآية ٣٣.", "(٢) سورة النحل: الآية ٤٣.", "(٣) سورة النساء: الآية ٨٣.", "(٤) الفتاوى ٢١٤/٢٠.", "(٥) إعلام الموقعين ٣٤٧/٢."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0069.png"}, {"n": 70, "paras": ["القواعد الكلية والآداب المرعية عند الاختلاف والتنازع", "١ - (وكل أحد يؤخذ من كلامه ويترك إلا المعصوم ﷺ، وكل ما جاء عن السلف رضوان الله عليهم موافقاً للكتاب والسنة قبلناه، وإلا فكتاب الله وسنة رسوله أولى بالاتباع، ولكنا لا نعرض للأشخاص - فيما اختلف فيه - بطعن أو تجريح ونكلهم إلى نياتهم، وقد أفضوا إلى ما قدموا). الأصل السادس.", "٢ - (والخلاف الفقهي في الفروع لا يكون سبباً للتفرق في الدين، ولا يؤدي إلى خصومة، ولا بغضاء، ولكل مجتهد أجره، ولا مانع من التحقيق العلمي النزيه في مسائل الخلاف في ظل الحب في الله والتعاون على الوصول إلى الحقيقة، من غير أن يجر ذلك إلى المراء المذموم والتعصب). الأصل الثامن.", "الخلاف ضربان: ضرب يقع في قضايا الأصول الكلية، الاعتقادية، ويقع أيضاً في مناهج الفهم عن الله ورسوله تنزيلاً أو تأويلاً كخلاف أهل الأهواء والبدع لأهل السنة والجماعة وهو خلاف مذموم. وهذا الاختلاف يتعذر فيه الوفاق ما لم تتحقق أرضية مشتركة وقاعدة جامعة في مسائل الأصول الاعتقادية.", "والضرب الثاني: يقع فيما دون الأصول كاختلاف العلماء في الفروع العملية، واختلاف الجماعات الإسلامية في تقدير أولويات العمل الإسلامي. والاختلاف في مثل هذه الفروع والجزئيات مع بذل الجهد للوصول إلى الحق"], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0070.png"}, {"n": 71, "paras": ["ضرورة لأنه من طبائع البشر، ولا يمكن أن يتحد الناس في هذه الآراء والمذاهب والمسالك لأسباب عدة أشار إليها الإمام البنا:", "١ - منها اختلاف العقول في قوة الاستنباط أو ضعفه وإدراك الدلائل والجهل بها، والغوص على أعماق المعاني، وارتباط الحقائق بعضها ببعض. والدين آيات وأحاديث يفسرها العقل والرأي في حدود اللغة وقوانينها، والناس في ذلك جد متفاوتين فلا بد من خلاف.", "٢ - ومنها سعة العلم وضيقه، وإن هذا بلغه ما لم يبلغ والآخر شأنه كذلك. وقد قال مالك لأبي جعفر: إن أصحاب رسول الله ﷺ تفرقوا في الأمصار وعند كل قوم علم فإذا حملتهم على رأي واحد تكون فتنة.", "٣ - ومنها اختلاف البيئات حتى إن التطبيق يختلف باختلاف كل بيئة.", "٤ - ومنها اختلاف الاطمئنان القلبي إلى الرواية عند التلقين لها.", "٥ - ومنها اختلاف تقدير الدلالات فهذا يعتبر عمل الناس مقدماً على خبر الآحاد مثلاً وذاك لا يقول معه به وهكذا.", "كل هذه أسباب جعلتنا نعتقد أن الإجماع على أمر واحد في فروع الدين مطلب مستحيل، بل هو يتنافى مع طبيعة هذا الدين(١).", "قواعد كلية عند الاختلاف:", "إن كان الاختلاف ضرورة واقعة فلا بد من رعاية قواعده وآدابه. وقد أوجزتها فيما يلي:", "١ - وجوب رد التنازع إلى الله ورسوله. وقد أجمع أهل العلم على أن الرد إلى الله هو الرد إلى كتابه، وأن الرد إلى الرسول هو إليه في حياته وإلى سنته بعد مماته. كما أجمعوا على أن من استبانت له سنة النبي ﷺ لم يكن له", "(١) رسالة دعوتنا ص ٢٥ - ٢٦ من مجموعة الرسائل."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0071.png"}, {"n": 72, "paras": ["أن يدعها لقول أحد من الناس(١). وقد اشتهر في قواعد الأصول أنه (لا يحل القياس والخبر موجود) (وإذا ورد الأثر بطل النظر) و(لا اجتهاد في مورد النص).", "٢ - لا عصمة لأحد عند أهل الحق إلا للنبي ﷺ وكل أحد يؤخذ من قوله ويترك إلا المعصوم ﷺ.", "وأقوال أهل العلم لا تستقل بنفسها حجة شرعية، ولكن قول النبي ﷺ يستقل بذاته حجة لازمة. ومن هنا قال بعض أهل العلم إن قول العالم يحتج له، وقول النبي ﷺ يحتج به. وعلى هذا:", "أ - فما جاء في الكتاب وصحيح السنّة يجب التقيد بهما مطلقاً حسب دلالات الأحكام.", "ب - وكذلك ما أجمع عليه سلف الأمة وأئمة الاجتهاد.", "ج - ما اختلفت فيه أنظار العلماء، وتجاذبته أقوالهم يتخير أقربها إلى الكتاب والسنّة دون تقديس أو تبخيس.", "٣ - أن يكون القصد هو تحري الحق، وبلوغ الصواب سواء ظهر على لسان القائل أو على لسان خصمه، كما أثر عن الشافعي أنه قال: (ما ناظرت أحداً إلا ورجوت الله أن يظهر الحق على لسانه)، وقال: (قول صواب يحتمل الخطأ، وقول غير خطأ يحتمل الصواب)، وقال: (ما باليت أظهر الحق على لساني أم على لسان خصمي). وذاك أن الحكمة ضالة المؤمن أنى وجدها فهو أحق بها. وقد يخفى الأمر على عالم ويدركه مَنْ هو دونه. وقد صدّق الله تعالى قول ملكة سبأ قبل أن تسلم حين قال: ﴿إِنَّ الْمُلُوكَ إِذَا دَخَلُوا قَرْيَةً أَفْسَدُوهَا وَجَعَلُوا أَعِزَّةَ أَهْلِهَا أَذِلَّةً﴾، فجاء التأكيد لقولها: ﴿وَكَذَلِكَ يَفْعَلُونَ﴾(٢). يقول ابن تيمية: (الحق يقبل من كل من تكلم به). وكان معاذ بن جبل يقول في كلامه المشهور عنه الذي رواه أبو داود في سننه:", "(١) انظر مقدمة أعلام الموقعين. (٢) سورة النمل: الآية ٣٤."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0072.png"}, {"n": 73, "paras": ["(اقبلوا الحق من كل من جاء به وإن كان كافراً، أو قال فاجراً، واحذروا زيغة الحكيم، قالوا كيف نعلم أن الكافر يقول كلمة الحق قال إن على الحق نوراً)(١).", "٤ - وجوب إحسان الظن بعلماء الأمة وتوقيرهم والتماس العذر لهم. يقول ابن تيمية: (يجب على المسلمين بعد موالاة الله ورسوله موالاة المؤمنين كما نطق به القرآن، خصوصاً العلماء الذين هم ورثة الأنبياء، الذين جعلهم الله بمنزلة النجوم يهتدى بهم في ظلمات البر والبحر. وقد أجمع المسلمون على هدايتهم ودرايتهم، إذ كل أمة قبل مبعث محمد ﷺ فعلماؤها شرارها، إلا المسلمين فإن علماءهم خيارهم. فإنهم خلفاء الرسول في أمته، والمحيون لما مات من سنته، بهم قام الكتاب، وبه قاموا، وبهم نطق الكتاب وبه نطقوا. وليعلم أنه ليس أحد من الأئمة المقبولين عند الأمة قبولاً عاماً يتعمد مخالفة رسول الله ﷺ في شيء من سنته، دقيق ولا جليل. فإنهم متفقون اتفاقاً يقينياً على وجوب اتباع الرسول، وعلى أن كل أحد من الناس يؤخذ من قوله ويترك إلا رسول الله ﷺ ولكن إذا وجد لواحد منهم قول قد جاء حديث صحيح بخلافه فلا بد له من عذر في تركه)(٢).", "٥ - ضرورة الجمع بين النصوص والأقوال قبل القطع بالحكم عليها من خلال نص واحد مع مراعاة السياق اللفظي والمعنوي والظرفي. فيحمل المبهم الخفي على الواضح الجلي، والمشكل على المفسر، والمجمل على المفصل والعام على الخاص، والمطلق على المقيد، ويرجح المنطوق على المفهوم، والعبارة على الإشارة، والمتأخر على المتقدم وذلك تحقيقاً للإنصاف.", "٦ - ضرورة حمل الكلام على أحسن المحامل إن اتسع لها التأويل، وساغ لها الفهم. ومسالك الأئمة طافحة في هذا المعنى. فقد تأول ابن تيمية للمتصوفة قولهم: (إن المريد إذا أحبه الله لم يضره ذنب) وحمله على أن من أحبه الله ووقعت منه معصية فإن الله تعالى يوفقه للتوبة والاستغفار ويعينه على", "(١) الفتوى الحموية ص ٦٩.", "(٢) الفتاوى ٢٠/ ٢٣١ - ٢٣٢."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0073.png"}, {"n": 74, "paras": ["الخلاص من ذنبه حتى لا يبقى مصراً عليه. وتأول ابن القيم معنى قول الجنيد: (إذا أراد الله بالمريد خيراً أوقعه على الصوفية، ومنعه صحبة القرّاء) وحمله على معنى أنهم يهذبون أخلاقه ويدلونه على تزكية نفسه، وأما القرّاء - وهم أهل التنسك الذين قصرت همتهم عن ظاهر العبادة(١) - فلا يذيقونه من حلاوة أعمال القلوب وتهذيب النفوس. ثم قال: (والبصير الصادق يضرب في كل غنيمة بسهم، ويعاشر كل طائفة على أحسن ما معها)(٢).", "٧ - لا يحل التشنيع والإرجاف على طائفة ما بسبب مسائل تحتمل وجوهاً في الفهم، ومتسعاً للرأي، ومسرحاً للنظر ولا يحل التضليل والتكفير لخطورتهما. (فمن كان من المؤمنين مجتهداً في طلب الحق وأخطأ فإن الله يغفر له خطأه كائناً ما كان، سواء كان في المسائل النظرية والعملية، أو المسائل الفروعية العملية، هذا الذي عليه أصحاب النبي ﷺ وجماهير أمة الإسلام)(٣).", "وقال الشوكاني: (واعلم أن التكفير لمجتهدي الإسلام بمجرد الخطأ في الاجتهاد في شيء من مسائل العقل كنود لا يصعد إليها إلا من لا يبالي بدينه ولا يحرص عليه لأنه مبني على شفا جرف هار، وعلى ظلمات بعضها فوق بعض)(٤).", "٨ - الاتفاق العام على أصول المنهج، لا يلزم منه الاتفاق على تفاصيله، والمخالفة الفرعية لا تخرج المرء عن أصول المنهج. ومن ذلك اختلاف السلف في بعض فروع العقيدة كمسألة رؤية الرسول ﷺ ربه في المعراج، وتفاضل الصحابة ونحو ذلك.", "فالحكم إنما يكون باعتبار الغلبة والرجحان، فإذا وقع الاتفاق على الأصول والكليات، فلا يضر الخلاف الجزئي المندرج في إطار المنهج الواحد.", "(١) هذا في اصطلاحهم.", "(٢) مدارج السالكين ٢/ ٣٦٩ - ٣٧٠.", "(٣) الفتاوى ٢٣٥ - ٢١٦.", "(٤) إرشاد الفحول ص ٢٦٠."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0074.png"}, {"n": 75, "paras": ["٩ - ضرورة التوسط والاعتدال حتى عند شئنان العداوة واستحكام الخلاف. فلا بد من الإنصاف، والنظر بعين العدل.", "يقول ابن القيم: (وكل أهل نحلة ومقالة يكسون نحلتهم ومقالتهم أحسن ما يقدرون عليه من الألفاظ ومقالة مخالفيهم أقبح ما يقدرون عليه من الألفاظ، ومن رزقه الله بصيرة، فهو يكشف بها حقيقة ما تحت تلك الألفاظ من الحق والباطل من الحق والباطل. ولا تفتر باللفظ كما قيل في هذا المعنى): تقول هذا جني النحل تمدحه وإن تشأ قلت ذا قيء الزنابير مدحاً وذماً وما جاوزت وصفهما والحق قد يعتريه سوء تعبير", "فإذا أردت الاطلاع على كنه المعنى هل هو حق، أو باطل، فجرده من لباس العبارة، وجرّد قلبك عن النفرة والميل ثم أعط النظر حقه ناظراً بعين الإنصاف، ولا تكن ممن ينظر في مقالة أصحابه ومن يحسن ظنه بهم نظراً تاماً بكل قلبه ثم ينظر في مقالة خصومه وممن يسىء ظنه بهم كنظر الشرر والملاحظة فالناظر بعين العداوة يرى المحاسن مساوىء والناظر بعين المحبة عكسه، وما سلم من هذا إلا من أراد الله كرامته، وارتضاه لقبول الحق وقد قيل: وعين الرضا عن كل عيب كليلة ولكن عين السخط تبدي المساويا", "وقال آخر: نظروا بعين عداوة لو أنها عين الرضا لاستحسنوا ما استقبحوا(١)", "١٠ - الأئمة والدعاة المشهود لهم بالإمامة في الدين تنغمر سيئاتهم في خضم حسناتهم وفضائلهم. فلا ينبغي الحرص على تتبع سقطات الأعلام وعثرات الهداة، بل نثبت لأهل الفضل والسابقة فضلهم وسابقتهم.", "(١) مفتاح دار السعادة ص ١٤١."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0075.png"}, {"n": 76, "paras": ["يقول ابن رجب الحنبلي في مقدمة كتابه القواعد في الفقه: (ويأبى الله العصمة لكتاب غير كتابه، والمنصف من اغتفر قليل خطأ المرء في كثير صوابه).", "وحين ترجم الذهبي لابن تيمية في تذكرة الحفاظ قال في آخرها وقد انفرد بفتاوى نيل من عرضه لأجلها وهي مغمورة في بحر علمه فالله تعالى يسامحه ويرضى عنه فما رأيت مثله وكل يؤخذ من قوله ويترك فكان ماذا؟.", "وقال ابن القيم: (من قواعد الشرع والحكمة أن من كثرت حسناته وعظمت، وكان له في الإسلام تأثير ظاهر فإنه يحتمل ما لا يحتمل لغيره، ويعفى له ما لا يعفى عن غيره فإن المعصية خبث، والماء إذا بلغ القلتين لم يحمل الخبث. ومن هذا قول النبي ﷺ لعمر وما يدريك لعل الله اطلع على أهل بدر فقال: اعملوا ما شئتم فقد غفرت لكم، ولما حض النبي ﷺ على الصدقة فأخرج عثمان رضي الله عنه تلك الصدقة العظيمة قال: ما ضر عثمان ما عمل بعدها، وقال لطلحة: لما تطأطأ للنبي ﷺ حتى صعد على ظهره إلى الصخرة أوجب طلحة وهذا موسى كليم الرحمن عز وجل ألقى الألواح التي فيها كلام الله حتى تكسرت، وأخذ بلحية هارون وجره إليه وهو نبي الله ، وكل هذا لم ينقص من قدره شيئاً عند ربه وربه تعالى يكرمه ويحبه. وهذا أمر معلوم عند الناس، مستقر في فطرهم أن من له ألوف الحسنات فإنه يسامح بالسيئة والسيئتين حتى إنه ليختلج داعي عقوبته على إساءته وداعي شكره على إحسانه فيغلب داعي الشكر لداعي العقوبة كما قيل: وإذا الحبيب أتى بذنب واحد جاء محاسنه بكل شفيع", "وقال آخر: فإن يكن الفعل الذي ساء واحداً فأفعاله اللاتي سررن كثير)(١)", "(١) مفتاح دار السعادة باختصار ص ١٧٦ - ١٧٧."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0076.png"}, {"n": 77, "paras": ["١١ - إن لم تتضح الحجة عند الاختلاف، عذر كل أخاه ووكل سريرته إلى الله عز وجل وداوم على أخوته.", "فنعمل في ما اتفقنا عليه من الأصول والكليات والقطعيات والمحكمات. ويعذر بعضنا بعضاً في الفروع مما للاجتهاد فيه نصيب، وللنظر فيه مسرح، وللرأي فيه متسع - أي بضابط إمكان الاجتهاد - في مثل هذا القدر من الخلاف الذي يسمح به المنهاج.", "وأختم هذه القواعد بقول الإمام البنا: (نلتمس كل العذر لمن يخالفوننا في بعض الفرعيات، ونرى أن هذا الخلاف لا يكون أبداً حائلاً دون ارتباط القلوب، وتبادل الحب والتعاون على الخير، وأن يشملنا وإياهم معنى الإسلام السابغ بأفضل حدوده وأوسع مشتملاته.. يعلم الإخوان ذلك، فهم لهذا أوسع الناس صدراً مع مخالفيهم، ويرون أن مع كل قوم علماً، وفي كل دعوة حقاً وباطلاً، فهم يتحرون الحق ويأخذون به ويجادلون في هوادة ورفق لإقناع المخالفين بوجهة نظرهم، فإن اقتنعوا فذاك، وإن لم يقتنعوا فإخوان في الدين نسأل الله لنا ولهم الهداية. ذلك منهاج الإخوان، فهم يجيزون الخلاف ويكرهون التعصب للرأي)(١).. ويقول في موضع آخر: (وأما موقفنا من الهيئات الإسلامية على اختلاف نزعاتها فموقف حب وإخاء، وتعاون وولاء، نحبها ونعاونها، ونحاول جاهدين أن نقرب بين وجهات النظر، ونوفق بين مختلف الفكر توفيقاً ينتصر به الحق في ظل التعاون والحب ولا يباعد بيننا رأي فقهي، أو خلاف مذهبي، فدين الله يسر ولن يشاد الدين أحد إلا غلبه)(٢).", "(١) (٢) دعوتنا باختصار ص ٢٦ - ٢٧ من مجموعة الرسائل."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0077.png"}, {"n": 78, "paras": ["نظرة موضوعية حول مسألة التصوف", "(والعرف الخاطيء لا يغير حقائق الألفاظ الشرعية، بل يجب التأكد من حدود المعاني المقصود بها، والوقوف عندها، كما يجب الاحتراز من الخداع اللفظي في كل نواحي الدنيا والدين، فالعبرة بالمسميات لا الأسماء). الأصل السادس عشر.", "مسألة التصوف قضية زلت فيها أقدام، وضلت فيها أفهام، وافترقت بالسالكين فيها الطرقات، منهم من تشدد فأفرط، ومنهم من تساهل فأفرط، ومنهم من اعتدل فتوسط. وأود في هذه الصفحات أن أشير إلى معالم نخلص من خلالها إلى رؤية منهجية لا تنزع إلى وكس أو شطط.", "وسأبدأ بموقف الإمام البنا إلى التصوف ثم أشير إلى موقف العلماء من هذا المنهج الذي سلكه في تقويم أمر التصوف.", "نظرة الإمام البنا إلى التصوف:", "اعتمد البنا في منهجه بالنسبة للتصوف على قبول ما فيه من حق، ونفي ما علق به من بدع العقائد والعبادة والسلوك. وها هو يشرح موقفه بجلاء ووضوح.", "١ - (حقيقة صوفية) (لأنهم يعلمون أن أساس الخير طهارة النفس، ونقاء القلب، والمواظبة على العمل، والإعراض عن الخلق، والحب في الله، والارتباط على الخير)(١).", "(١) المؤتمر الخامس ص ١٢٢ من مجموعة الرسائل."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0078.png"}, {"n": 79, "paras": ["٢ - رد البدع والالتزام بالمأثور: إلا أننا نرى أن تجاوز السنة في التربية إلى مبالغات لم ترد، وتحليل الأذواق والمواجيد ومزج ذلك بعلوم الفلسفة والمنطق، ليس من الدين في شيء(١).", "٣ - التأكيد على التزام منهج السلف: ومع إيمان الجماعة بجواز حصول الكرامات بشرائطها الشرعية، فإن أعظم كرامة يكرم بها عبد هي التوفيق لنشر دعوة الإسلام، والغيرة على محارم الله والأمر بالمعروف والنهي عن المنكر(٢).", "ويقول في الأصل الثالث: (وللإيمان الصادق، والعبادة الصحيحة والمجاهدة نور وحلاوة يقذفها الله في قلب من يشاء من عباده، ولكن الإلهام والخواطر والكشف ليست من أدلة الأحكام الشرعية، ولا تعتبر إلا بشرط عدم اصطدامها بأحكام الدين ونصوصه)(٣).", "وفي الأصل الثالث عشر: (ومحبة الصالحين، واحترامهم والثناء عليهم بما عرف من طيب أعمالهم قربة إلى الله تبارك وتعالى والأولياء هم المذكورون في قوله تعالى: ﴿الذين آمنوا وكانوا يتقون﴾ والكرامة ثابتة لهم بشرائطها الشرعية مع اعتقاد أنهم رضوان الله عليهم لا يملكون لأنفسهم نفعاً ولا ضراً في حياتهم أو بعد مماتهم فضلاً عن أن يهبوا شيئاً من ذلك لغيرهم)(٤).", "٤ - بيانه لانحراف التصوف وما علق به من بدع الاعتقاد والتعبد والسلوك (ولكن فكرة التصوف لم تقف عند حد علم السلوك والتربية، ولو وقفت عند هذا الحد لكان خيراً لها وللناس ولكنها جاوزت ذلك بعد العصور الأولى إلى تحليل الأذواق والمواجيد، ومزج ذلك بعلوم الفلسفة والمنطق ومواريث الأمم الماضية وأفكارها، فخلطت ذلك بما ليس منه، وفتحت الثغرات الواسعة لكل زنديق وملحد، أو فاسد الرأي والعقيدة ليدخل من", "(١) المذكرات ص ٢٢ بتصرف.", "(٢) انظر المذكرات ص ١٨.", "(٣) (٤) رسالة التعاليم ص ٢٥٦ - ٢٥٨ من مجموعة الرسائل."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0079.png"}, {"n": 80, "paras": ["هذا الباب باسم التصوف والدعوة إلى الزهد والتقشف، والرغبة في الحصول على هذه النتائج الروحية الباهرة، وأصبح كل ما يكتب أو يقال في هذه الناحية يجب أن يكون محل نظر دقيق من الناظرين في دين الله والحريصين على صفائه ونقائه(١).", "٥ - دعوته لمحاربة البدع العقائدية الفاسدة: (والتمائم والرقي والودع والرمل والمعرفة والكهانة، وادعاء معرفة الغيب وكل ما كان من هذا الباب منكر تجب محاربته إلا ما كان آية من قرآن أو رقية مأثورة). الأصل الرابع.", "٦ - دعوته لمحاربة بدع السلوك والتعبد: (وكل بدعة في دين الله لا أصل لها - استحسنها الناس بأهوائهم، سواء بالزيادة فيه أو بالنقص منه - ضلالة تجب محاربتها والقضاء عليها بأفضل الوسائل التي لا تؤدي إلى شر منها). الأصل الحادي عشر.", "٧ - تحذيره مما يخل بتوحيد العبادة الذي وقع فيه من تلبث بانحرافات غلاة المتصوفة: (وزيارة القبور أيا كانت سنة مشروعة بالكيفية المأثورة، ولكن الاستعانة بالمقبورين أياً كانوا ونداءهم لذلك وطلب الحاجات منهم عن قرب أو بعد والنذر لهم وتشييد القبور وسترها وإضاءتها والتمسح بها والحلف بغير الله وما يلحق بذلك من المبتدعات كبائر تجب محاربتها، ولا نتأول لهذه الأعمال سداً للذريعة). الأصل الرابع عشر.", "٨ - إنكاره على متعبدة المتصوفة إهمال كتاب الله والانكفاف على أورادهم: (وأما بقية المتعبدين فلهم فيما وضعوا لأنفسهم ووضعه لهم شيوخهم من أوراد وأحزاب ووظائف وصلوات ما تركوا به كتاب الله وأحلّوه محله حفظاً واهتماماً وتعبداً وتلاوة وترديداً وتكراراً)(٢).", "هذا هو موقف الإمام البنا من التصوف، قبل خيره الموافق لنصوص", "(١) المذكرات ص ٢٢.", "(٢) هل نحن قوم عمليون ص ٨٦ من مجموعة الرسائل."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0080.png"}, {"n": 81, "paras": ["الوحي، وقواعد الشرع، ورد ما سواه من باطل مع كشفه والتحذير عنه وفق رؤية سلفية ومنهجية سنية.", "منهجية متوزانة في معالجة التصوف: إن البنا لم يكن مبتدعاً لهذا الموقف من التصوف بل هو منهج الأئمة الأعلام، والجهابذة الكبار.. وإليك طرفاً منها:", "- الحاكم النيسابوري يقول في مستدركه على الصحيحين (الصوفية طائفة من طوائف المسلمين، فمنهم أخيار ومنهم أشرار)(١).", "- ابن تيمية وهو أكثرهم استيعاباً لمضمون التصوف، والغوص في معانيه، وتمييز حقه من باطله، وغثه من سمينه. يقول رحمه الله: (لأجل ما وقع في كثير منهم من الاجتهاد والتنازع فيه تنازع الناس في طريقهم. فطائفة ذمت (الصوفية والتصوف) وقالوا إنهم مبتدعون، خارجون عن السنة، ونقل عن طائفة من الأئمة في ذلك من الكلام ما هو معروف، وتبعهم على ذلك طوائف من أهل الفقه والكلام. وطائفة غلت فيهم، وادعو أنهم أفضل الخلق، وأكملهم بعد الأنبياء، وكلا طرفي هذه الأمور ذميم. والصواب أنهم مجتهدون في طاعة الله، كما اجتهد غيرهم من أهل طاعة الله، ففيهم السابق المقرب بحسب اجتهاده، وفيهم المقتصد الذي هو من أهل اليمين. وفي كل من الصنفين من قد يجتهد فيخطىء. وفيهم من يذنب فيتوب أو يتوب. ومن المنتسبين إليهم من هو ظالم لنفسه، عاص لربه وقد انتسب إليهم طوائف من أهل البدع والزندقة ولكن عند المحققين من أهل التصوف ليسوا", "(١) المستدرك ١٧/٣."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0081.png"}, {"n": 82, "paras": ["منهم: كالحلاج مثلاً فإن أكثر مشايخ الطريق أنكروه، وأخرجوه عن الطريق مثل الجنيد بن محمد سيد الطائفة وغيره(١).", "- ابن القيم: وهو يسلك المنهج الوسط القويم الذي سلكه شيخه من قبل. وذلك من خلال عرضه لمواقف الناس إزاء شطحات المتصوفة فقرر أن (هذه الشطحات أوجبت فتنة على طائفتين من الناس.", "إحداهما: حجبت بها عن محاسن هذه الطائفة، ولطف نفوسهم، وصدق معاملتهم، فأهدروها لأجل هذه الشطحات، وأنكروها غاية الإنكار، وأساءوا الظن بهم مطلقاً وهذا عدوان وإسراف فلو كان كل من أخطأ أو غلط ترك جملة، وأهدرت محاسنه لفسدت العلوم والصناعات، والحكم وتعطلت معالمها.", "والطائفة الثانية: حجبوا بما رأوه من محاسن القوم وصفاء قلوبهم، وصحة عزائمهم، وحسن معاملاتهم، عن رؤية عيوب شطحاتهم ونقصانها، فسحبوا عليها ذيل المحاسن، وأجروا عليها حكم القبول والانتصار لها واستظهروا بها في سلوكهم.", "وهؤلاء أيضاً معتدون مفرطون.", "والطائفة الثالثة: وهم أهل العدل والإنصاف الذين أعطوا كل ذي حق حقه، وأنزلوا كل ذي منزلة منزلته فلم يحكموا للصحيح بحكم السقيم المعلول، ولا للمعلول السقيم بحكم الصحيح بل قبلوا منها ما يقبل وردوا منها ما يرد. وهذه الشطحات ونحوها هي التي حذر منها سادات القوم، وذموا عاقبتها وتبرؤا منها)(٢). ولما عقب رحمه الله على كلام للإمام الهروي وجّه كلامه، وحمله على أحسن المحامل ثم قال: (هذا ونحوه من الشطحات التي ترجى مغفرتها بكثرة الحسنات، ويستغرقها كمال الصدق، وصحة المعاملة.", "(١) الفتاوى ج ١١/ ١٧ - ١٨.", "(٢) مدارج السالكين ٢/ ٣٩ - ٤٠."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0082.png"}, {"n": 83, "paras": ["وقوة الإخلاص، وتجريد التوحيد، ولم تضمن العصمة لبشر بعد رسول الله ﷺ(١). وقال في موضع آخر: (والبصير الصادق يضرب في كل غنيمة بسهم، ويعاشر كل طائفة على حسن ما معها، ولا يتحيز إلى طائفة، وينأى عن الأخرى بالكلية أن لا يكون معها شيء من الحق. فهذه طريقة الصادقين ودعوى الجاهلية كامنة في النفوس: ولا أعني بذلك أصغريهم ولكني أريد به الدوينا) فهذا هو منهج أهل السنة والجماعة، والعلم والإيمان أنهم يقبلون من كل طائفة ما وافق الكتاب، ويدعون من كل طائفة ما خالف الكتاب والسنة. (وكثير من الناس إذا علم من الرجل ما يحبه، أحب الرجل مطلقاً، وأعرض عن سيئاته وإذا علم منه ما يبغضه، أبغضه مطلقاً، وأعرض عن حسناته وهذا من أقوال أهل البدع والخوارج والمعتزلة والمرجئة. وأهل السنة والجماعة يقولون ما دل عليه الكتاب والسنة والإجماع، وهو أن المؤمن يستحق وعد الله وفضله الثواب على حسناته، ويستحق العقاب على سيئاته، وإن الشخص الواحد يجتمع فيه ما يثاب عليه، وما يعاقب عليه، وما يحمد عليه، وما يذم عليه، وما يحب منه وما يبغضه منه)(٢).", "الخلاصة: أن منشأ التصوف كان بالبصرة التي كان فيها من يسلك طريق الزهد والعبادة ما ليس في سائر الأمصار(٣)، ثم أصبح مصطلحاً لمجاهدة النفس ورياضتها للخروج بها عن الأخلاق الرذيلة والدخول بها في الأخلاق الحميدة والخصالة الحسنة(٤)، وكان في أول عهده منضبطاً بأصول السنة والاعتقاد، وأئمته مشهود لهم بالاستقامة كبشر الحافي، وإبراهيم بن أدهم، وأبي سليمان الداراني، والفضيل بن عياض، والسري السقطي، وسهل بن عبدالله", "(١) المصدر السابق ٣٩/٢.", "(٢) الفتاوى ١٥/١١ - ١٦.", "(٣) (٤) المصدر السابق (١٦/١١)."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0083.png"}, {"n": 84, "paras": ["التستري، وعبدالقادر الجيلاني وأمثالهم ممن وثقهم علماء السنة وشهدوا لهم بصحة المسلك وسلامة المنهج، ونقلوا من أقوالهم ما يدل على ذلك. قال سهل بن عبدالله التستري: (كل وجد لا يشهد له الكتاب والسنة فهو باطل. وقال أبو سليمان الداراني: إنه لتلم بقلبي النكتة من نكت القوم فلا أقبلها إلا بشاهدين عدلين: الكتاب والسنة. وقال أبو سليمان أيضاً: ليس لمن ألهم شيئاً من الخير أن يفعله، حتى يجد فيه أثراً، فإذا وجد فيه أثراً كان نوراً على نور. وقال الجنيد بن محمد: علمنا هذا مقيد بالكتاب والسنة. فمن لم يقرأ القرآن ويكتب الحديث لا يصلح له أن يتكلم في علمنا)(١). ثم منهم من نالته بدعة طفيفة ثم تاب أو أخطأ في التركيز على التخويف دون فتح باب الرجاء كالحارث المحاسبي. ولكن التصوف لم يقف عند هذا الحد، بل خرج عن أصل وضعه حين استقل عن محكمات الاعتقاد، وقواعد الشريعة فدخلت عليه البدع الاعتقادية والعملية حين اختلط بالفلسفات حتى أخرجت بعض منتسبيه(٢) إلى القول بوحدة الوجود والحلول والاتحاد التي حكم العلماء بكفر معتنقيها وظهرت دعاوى الشطحات وإسقاط التكاليف ونحوها من الضلالات. فلا بد لنا من التفريق بين مراحل التصوف، فلا نقبله بجملته، ولا نرده كله بل نقبل حقه ونحرره مما علق به من دخن، ونرد باطله ونكشف زيفه. وهذا هو القسطاس المستقيم والسنن القويم ﴿وأقيموا الوزن بالقسط ولا تخسروا الميزان﴾ وإن من الإنصاف أن يكتال المرء لغيره بالصاع الذي يكتال به لنفسه، فإن في كل شيء وفاءً وتطفيفاً.", "(١) الفتاوى ٥٩٥/١١.", "(٢) وبعضهم ينكر نسبتهم إليهم كما تقدم في كلام شيخ الإسلام ابن تيمية."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0084.png"}, {"n": 85, "paras": ["فقه الأمر بالمعروف وقواعد الإنكار", "الأصل الحادي عشر في محاربة البدع (بأفضل الوسائل التي لا تؤدي إلى ما هو شر منها). محاربة البدع والقضاء عليها محدودة بالأصول العامة والقواعد الشرعية التي تحكم الأمر بالمعروف والنهي عن المنكر. فالأمر بالمعروف والنهي عن المنكر من شعب الدين الجامعة، وبه أرسلت الرسل، وأنزلت الكتب، وشرعت الشرائع، قال تعالى في صفة نبينا ﷺ: ﴿يأمرهم بالمعروف وينهاهم عن المنكر، ويحل لهم الطيبات، ويحرم عليهم الخبائث﴾(١) وهذا بيان لكمال رسالته المتضمنة للأمر بكل معروف، والنهي عن كل منكر، وإحلال كل طيب، وتحريم كل خبيث. وأما من قبله من الرسل فقد كان يحرم عليهم بعض الطيبات كما قال: ﴿فبظلم من الذين هادوا حرمنا عليهم طيبات أحلت لهم﴾(٢) وربما لم يحرم عليهم جميع الخبائث، كما قال تعالى: ﴿كل الطعام كان حلاً لبني إسرائيل إلا ما حرّم إسرائيل على نفسه من قبل أن تنزل التوراة﴾(٣) وتحريم الخبائث يندرج في معنى «النهي عن المنكر» كما أن إحلال الطيبات يندرج في «الأمر بالمعروف»(٤).", "وكذلك وصف تعالى الأمة بما وصف به نبيها حيث قال: ﴿كنتم خير", "(١) سورة الأعراف: الآية ١٥٧.", "(٢) سورة النساء: الآية ١٦٠.", "(٣) سورة آل عمران: الآية ٩٣.", "(٤) الفتاوى ١٢٢/٢٨."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0085.png"}, {"n": 86, "paras": ["أمة أخرجت للناس تأمرون بالمعروف، وتنهون عن المنكر وتؤمنون بالله(١). وقال تعالى: ﴿والمؤمنون والمؤمنات بعضهم أولياء بعض يأمرون بالمعروف، وينهون عن المنكر﴾(٢). قال أبو هريرة: (كنتم خير الناس للناس، تأتون بهم في الأقياد والسلاسل حتى تدخلوهم الجنة)(٣). ولهذا كان إجماع هذه الأمة حجة لأن الله تعالى أخبر أنهم يأمرون بكل معروف، وينهون عن كل منكر. قيل لابن مسعود: (من ميت الأحياء)؟ فقال: (الذي لا يعرف معروفاً ولا ينكر منكراً).", "ولكن يغلط في هذا الواجب التكليفي فريقان من الناس:", "١ - فريق يترك ما يجب من الأمر والنهي تأويلاً لقوله تعالى: ﴿عليكم أنفسكم لا يضركم من ضل إذا اهتديتم﴾(٤). وقد رفع الصديق رضي الله عنه الإلتباس الناشيء في فهم هذه الآية في خطبته التي قال فيها: (إنكم تقرأون هذه الآية وتضعونها في غير موضعها، وإني سمعت النبي ﷺ يقول: «إن الناس إذا رأوا المنكر فلم يغيروه أوشك أن يعمهم الله بعقاب منه»(٥). فالإهتداء في الآية إنما يتم بأداء الواجب، وإنفاذ التكليف. فإذا قام بالأمر بالمعروف والنهي عن المنكر لم يضره ضلال من ضل. يدل عليه قوله تعالى: ﴿واتقوا فتنة لا تصيبن الذين ظلموا منكم خاصة واعلموا أن الله شديد العقاب﴾(٦). قال ابن عباس: (أمر الله المؤمنين أن لا يقروا المنكر بين أظهرهم فيعمهم العذاب).", "٢ - الفريق الثاني: من يريد أن يأمر وينهى دون مراعاة لقواعد الإنكار، وفقه المعروف، وما ينجم عنهما من آثار، ويترتب من مفاسد. ومن هنا جاء التنبيه الذي أشار إليه الإمام البنا حين قال: (بأفضل الوسائل التي لا", "(١) سورة آل عمران: ١١٠.", "(٢) سورة التوبة: الآية ٧١.", "(٣) الفتاوى ١٢٣/٢٨.", "(٤) سورة المائدة: الآية ١٠٥.", "(٥) الفتاوى ١٢٧/٢٨.", "(٦) سورة الأنفال: الآية ٢٥."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0086.png"}, {"n": 87, "paras": ["تؤدي إلى ما هو شر منها). قال شيخ الإسلام ابن تيمية: (حيث ما كانت مفسدة الأمر والنهي أعظم من مصلحته لم تكن مما أمر الله به)، ويقول في موضع آخر: (إن الأمر والنهي وإن تضمناً لتحصيل مصلحة ودفع مفسدة فينظر في المعارض له، فإن كان الذي يفوت من المصالح أو يحصل من المفاسد أكثر لم يكن مأموراً به، بل يكون محرماً إذا كانت مفسدته أكثر من مصلحته، لكن اعتبار مقادير المصالح والمفاسد هو بميزان الشريعة. فمتى قدر الإنسان على اتباع النصوص لم يعدل عنها، وإلا اجتهد رأيه لمعرفة الأشباه والنظائر، وقل أن تعوز النصوص من يكون خبيراً بها وبدلالتها على الأحكام)(٢). كما أن تلميذه الحافظ ابن القيم عقد فصلاً نفيساً في مقدمة الجزء الثالث من كتابه النافع اعلام الموقعين أشار فيه إلى مراتب المنكر ودرجات إنكاره فقال رحمه الله: (هذا فصل عظيم النفع جداً وقع بسبب الجهل به غلط عظيم على الشريعة أوجب من الحرج والمشقة وتكليف ما لا سبيل إليه ما يعلم أن الشريعة الباهرة التي في أعلى رتب المصالح لا تأتي به). وسأشير إلى جملة من القواعد التي تتصل بفقه إنكار المنكر وآدابه تأصيلاً لما أشار إليه الإمام البنا.", "مقامات المنكر وتنوع أهله: للمنكر درجات متشعبة، ومقامات مختلفة لا بد من النظر إليها، والاعتبار لها عند القيام بهذا الواجب الشرعي. وقد أورد الماوردي في أحكامه السلطانية تقسيمات المنكر وأقسام أهله على هذا النحو. أحدها: ما كان من حقوق الله تعالى. الثاني: ما كان من حقوق الآدميين. الثالث: ما كان مشتركاً بين الحقين.", "(١) الفتاوى ١٢٦/٢٨.", "(٢) الفتاوى ١٢٩/٢٨."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0087.png"}, {"n": 88, "paras": ["فأما النهي عنها في حقوق الله تعالى فعلى ثلاثة أقسام: أحدها: ما تعلق بالعبادات. الثاني: ما تعلق بالمحظورات. الثالث: ما تعلق بالمعاملات. فأما المتعلق بالعبادات فكالقاصد مخالفة هيئاتها المشروعة، والمتعمد تغيير أوصافها المسنونة. وأما ما يتعلق بالمحظورات، فكل ما حظره الشرع، كشرب الخمر والزنى وغيره. وأما ما يتعلق بالمعاملات، فكالبيوع الفاسدة، وما منع الشرع منه مع تراضي المتعاقدين به إذا كان متفقاً على حظره. وأما ما ينكر من حقوق الآدميين المحضة فمثل أن يتعدى رجل في حد لجاره أو في حريم لداره ونحو ذلك. وأما ما ينكر من الحقوق المشتركة بين حقوق الله تعالى وحقوق الآدميين فكالمنع من الإشراف على منازل الناس، وملاحظة أهل الذمة بعدم المجاهرة بقولهم في العزير والمسيح، وكذلك القضاة فيما يجب عليهم بين الخصوم(١). تنوع أهل المنكر: قال الماوردي: (لا يخلو حال فاعلي المنكر من أمرين: أحدهما: أن يكونوا آحاداً متفرقين، وأفراداً متبددين، لم يتحزبوا فيه ولم يتضافروا عليه، وهم رعية مقهورون، وأفذاذ مستضعفون، فلا خلاف بين الناس أن أمرهم بالمعروف ونهيهم عن المنكر، مع المكنة وظهور القدرة واجب على من شاهد ذلك من فاعليه، وسمعه من قائليه)(٢).", "(١) انظر مقدمة الجزء الثالث من الأعلام. (٢) المصدر السابق."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0088.png"}, {"n": 89, "paras": ["ثانيها: أن يكون فعل المنكر من جماعة قد تضافرت عليه، وعصبة قد تحزبت ودعت إليه، فقد اختلف الناس في وجوب إنكاره على مذاهب شتى . . . إلى أن قال (وقال جمهور المتكلمين: إنكار ذلك واجب، والدفع عنه لازم على شرطه من وجود أعوان يصلحون له فأما من فقد الأعوان فعلى الإنسان الكف لأن الواحد قد يقتل قبل بلوغ الغرض)(١).", "والخلاصة: إذا ظهر المنكر من فرد أو آحاد فالنهي مع القدرة لازم إذا استوفى شروطه وانعقدت أسبابه.", "وإن صدر من هيئات لها سلطة ومنعة فالإنكار واجب على جماعة مماثلة قادرة لها من الصفات ما تزيل به المنكر وتقيم مقامه معروفاً يحب الله ورسوله وفق قواعد الشرع ومحكمات الدين.", "من يملك إعطاء وصف المنكر:", "وصف المنكر حكم شرعي، لا يملك إعطاءه إلا الشريعة فالحاكم هو الله تعالى: ﴿إن الحكم إلا لله﴾ ومهمة الفقهاء التعرف على حكم الله والكشف عن دلالته وليس إنشاء للحكم الشرعي، فإذا استبان خطؤهم لم يجز متابعتهم عليه إذ الحجة لازمة في اتباع الشرع(٢).", "شروط المنكر:", "يشترط في المنكر أن يكون:", "أ - ظاهراً.", "ب - قائماً في الحال.", "ج - ومتفقاً على حكمه(٣).", "- أما كونه ظاهراً فالمراد انكشافه والعلم به بدون تجسس.", "(١) المصدر السابق.", "(٢) (٣) انظر أصول الدعوة لعبدالكريم زيدان ص ١٨٩ - ١٩٠."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0089.png"}, {"n": 90, "paras": ["ومعنى قيامه في الحال أن يكون موجوداً، فإذا وجدت مقدماته، وظهرت علاماته، ولاحت بوادره، ودلت القرائن المستفيضة على وقوعه وجب التحسب له بما يمنع وقوعه. كما يشترط في المنكر أن يكون مما اتفق الفقهاء على اعتباره منكراً. إذ لا إنكار في المجتهدات. أو ما احتملته دلالات النصوص وتصاريف اللغة.", "والخلاف الذي يمنع الإنكار هو ما كان سائغاً ومقبولاً، وما كان صادراً عن أهل العمل المشهود لهم بالإمامة في الدين، والرسوخ في المعرفة، والاستفراغ في الوسع. أما الخلاف الذي يكون شاذاً أو باطلاً لم يقم عليه دليل مقبول، أو عارض نصاً صريحاً من الكتاب أو السنة، أو الإجماع المتيقن، أو ما علم من الدين بالضرورة أو ناقض محكمات الشرع فلا عبرة به ولا يعتد بمثله.", "وليس كل خلاف جاء معتبراً إلا خلاف له حظ من النظر.", "درجات إنكار المنكر: قال ابن القيم: (إنكار المنكر أربع درجات: الأولى: أن يزول ويخلفه ضده. الثانية: أن يقل وإن لم يزل بجملته. الثالثة: أن يخلفه ما هو مثله. الرابعة: أن يخلفه ما هو شر منه.", "فالدرجتان الأوليان مشروعتا، والثالثة موضع اجتهاد والرابعة محرمة)(١). فالقاعدة الجامعة في مراتب الإنكار أنه: (إذا تعارضت المصالح والمفاسد، والحسنات والسيئات أو تزاحمت. فإنه يجب ترجيح الراجح منها.", "(١) أعلام الموقعين ٣/٣."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0090.png"}, {"n": 91, "paras": ["وعلى هذا إذا كان الشخص أو الطائفة جامعين بين معروف ومنكر بحيث لا يفرقون بينهما، بل إما أن يفعلوهما جميعاً أو يتركوهما جميعاً: لم يجز أن يؤمروا بمعروف، ولا أن ينهوا عن منكر، بل ينظر: فإن كان المعروف أكثر أمر به. وإن استلزم ما هو دونه من المنكر، ولم ينه عن منكر يستلزم تفويت معروف أعظم منه. بل يكون النهي حينئذ من باب الصد عن سبيل الله والسعي في زوال طاعته وطاعة رسوله وزوال فعل الحسنات، وإن كان المنكر أغلب نهي عنه، وإن استلزم فوات ما هو دونه من المعروف. ويكون الأمر بذلك المعروف المستلزم للمنكر الزائد عليه أمراً بمنكر وسعياً في معصية الله ورسوله. وإن تكافأ المعروف والمنكر المتلازمان لم يؤمر بهما ولم ينه عنهما. فتارة يصلح الأمر، وتارة يصلح النهي، وتارة لا يصلح لا أمر ولا نهي حيث كان المعروف والمنكر متلازمين وذلك في الأمور المعينة الواقعة وأما من جهة النوع فيؤمر بالمعروف مطلقاً، وينهى عن المنكر مطلقاً. وفي الفاعل الواحد والطائفة الواحدة يؤمر بمعروفها وينهى عن منكرها، ويحمد محمودها، ويذم مذمومها بحيث لا يتضمن حصول منكر أكبر أو فوات معروف أرجح(١).", "الشواهد الشرعية لهذه القاعدة: قال تعالى: ﴿وما كنت تتلو من قبله من كتاب ولا تخطه بيمينك إذاً لارتاب المبطلون﴾(٢). فالله تعالى لم يعلم نبيه الكتابة مع أنها أمر حسن لمنع تقوّل المبطلين. وقال تعالى: ﴿يا أيها الذين آمنوا لا تقولوا راعنا وقولوا انظرنا واسمعوا﴾(٣).", "نهى الله تعالى المسلمين من استعمال كلمة (راعنا) لأن اليهود كانوا يريدون بها شتم النبي ﷺ ولا يريدون المعنى اللغوي فجاء النهي سداً لذريعة الفساد.", "(١) الفتاوى ٢٩/٢٨ - ١٣٠ مع تصرف يسير.", "(٢) سورة العنكبوت: الآية ٤٨.", "(٣) سورة البقرة: الآية ١٠٤."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0091.png"}, {"n": 92, "paras": ["وقال عز وجل: ﴿ولا تسبوا الذين يدعون من دون الله فيسبوا الله عدواً بغير علم﴾(١). فسب الأصنام جائز ومباح لكنه منع لما صار ذريعة إلى سب الله تعالى.", "وأما في السنة فقد ترك النبي ﷺ ما قد هم به من إعادة بناء الكعبة على قواعد إبراهيم لكون الناس على حداثة عهد بالشرك والجاهلية.", "(ومن هذا الباب إقرار النبي ﷺ لعبدالله بن أبي وأمثاله من أئمة النفاق والفجور لما لهم من أعوان فإزالة منكره بنوع من عقابه مستلزم إزالة معروف أكثر من ذلك بغضب قومه وحميتهم وبنفور الناس إذا سمعوا أن محمداً يقتل أصحابه)(٢).", "ومن ذلك النهي عن قطع الأيدي في الغزو أي إقامة الحد في الحرب. وبهذا أخذ الإمام أحمد(٣) وثبت أن سعد بن أبي وقاص لم يقم حد الخمر على أبي محجن الثقفي في القادسية وقد أبلى بلاء عظيماً.", "ومن السنة كذلك نهي النبي ﷺ الدائن عن قبول الهدايا من مدينه سداً لذريعة الربا(٤).", "وهذه القاعدة دليل شرعي، ومصدر فقهي اعتمده أكثر الفقهاء وقد ذكرها ابن القيم وساق لها أمثلة عديدة تقرب من مائة في كتابه (أعلام الموقعين). ومما ذكره عن شيخه ابن تيمية أنه قال: (مررت أنا وبعض أصحابي في زمن التتار بقوم منهم يشربون الخمر فأنكر عليهم من كان معي، فأنكرت عليه وقلت له إنما حرم الله الخمر لأنها تصد عن ذكر الله وعن الصلاة", "(١) سورة الأنعام: الآية ١٠٨.", "(٢) الفتاوى ١٣/٢٨.", "(٣) انظر أعلام الموقعين ص ٣ فما بعدها.", "(٤) انظر المدخل إلى دراسة الشريعة د. عبدالكريم زيدان ص ٢٠٤."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0092.png"}, {"n": 93, "paras": ["وهؤلاء تصدهم الخمر عن قتل النفوس وسبي الذرية وأخذ الأموال فدعهم(١).", "وعلى هذا فإن النهي عن المنكر لا يتم بصورة واحدة، بل تتعدد درجاته، وتختلف صوره بحسب درجة المنهي عنه، وحالة فاعله، وبحسب الأحوال والمتعلقات، والآثار الناجمة، والمفاسد المترتبة حتى يكون وافياً بالمقصود ومبلغاً لمحاب الله ومراضيه. وكذلك الأمر الناهي ينبغي أن يكون أمره ونهيه بفقه وعلم كما قال عمر بن عبدالعزيز: (من عبدالله بغير علم كان ما يفسد أكثر مما يصلح)(٢). فإن العلم إمام العمل والعمل تابع له. ولا بد من الرفق فإن الله تعالى يعطي على الرفق ما لا يعطي على العنف، وأن يكون حليماً صبوراً على الأذى. قال ابن تيمية: (لا بد من هذه الثلاثة العلم والرفق والصبر. العلم قبل الأمر والنهي، والرفق معه والصبر بعده. وإن كان كل من الثلاثة مستحباً في هذه الأحوال)(٣).", "وقد جاء في الأثر عن بعض السلف: (لا يأمر بالمعروف ولا ينهي عن المنكر إلا من كان عالماً بما يأمر، عالماً بما ينهي، عدلاً فيما يأمر عدلاً فيما ينهي، رفيقاً بما يأمر رفيقاً بما ينهي)(٤).", "وجاء أيضاً: (ليكن أمرك بالمعروف معروفاً، وليكن نهيك عن المنكر ليس فيه منكر)(٥).", "(١) أعلام الموقعين ص ٣.", "(٢) (٣) الفتاوى ٢٨/ ١٣٦ - ١٣٧.", "(٤) (٥) انظر الفتاوى ٢٨/ ١٣٦ - ١٣٧."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0093.png"}, {"n": 94, "paras": ["السياسة الشرعية وضوابط العمل السياسي", "(ورأي الإمام ونائبه فيما لا نص فيه، وفيما يحتمل وجوهاً عدة، وفي المصالح المرسلة معمول به ما لم يصطدم بقاعدة شرعية وقد يتغير بحسب الظروف والعرف والعادة، والأصل في العبادات التعبد دون الالتفات إلى المعاني، وفي العاديات الالتفات إلى الأسرار والحكم والمقاصد). اشتملت هذه القاعدة على جملة أصول:", "الأصل الأول: رأي الأمير أو من ينوب عنه، أو فيمن يوليه، سواء كان في عقد إمارة كبرى كالإمامة العامة (خلافة المسلمين) أو في الإمارة الصغرى، معتبر ومأخوذ به فيما يلي ما لم يصادم قاعدة شرعية: أ - في مسائل الاجتهاد التي لم ترد بها نصوص. ب - وفيما وردت به نصوص، لكنها ظنية في دلالتها، للنظر فيها متسع، وللاجتهاد فيها مهيع تحتمله قواعد الاستدلال وتصاريف اللغة، ومدارك الاستنباط. فإذا مال إلى أحدها. بعد استفراغ الوسع تعين المصير إلى قوله والأخذ به. ج - وفيما كان مندرجاً تحت قاعدة المصالح المرسلة. ولكن المصلحة المرسلة محدودة بقواعد، ومحكومة بأصول يتعين الأخذ بها حتى لا يتجاوز بها نصوص الشرع ومحكمات الدين. وقبل الخوض في ضوابط المصلحة المرسلة"], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0094.png"}, {"n": 95, "paras": ["أشير إلى بعض القواعد التي تتصل بمسألة المصالح كي تتضح معالمها وتتكامل أبنيتها. المسألة الأولى: إن مقصود الشريعة هو رعاية مصالح العباد عاجلاً وآجلاً، ودفع المفاسد عنهم عاجلاً وآجلاً. قال تعالى: ﴿وما أرسلناك إلا رحمة للعالمين﴾(١). والرحمة تتضمن قطعاً رعاية مصالحهم ودرء مفاسدهم. وقد استفاضت أقوال العلماء في الإستدلال لهذا الأصل أجزىء بعضاً منها:", "- قال العز بن عبدالسلام: (إن الشريعة كلها مصالح إما درء مفاسد، أو جلب مصالح)(٢).", "- وقال ابن تيمية: (إن الشريعة جاءت بتحصيل المصالح وتكميلها، وتعطيل المفاسد وتقليلها)(٣).", "- وقال الشاطبي عن الشريعة: (إنها وضعت لمصالح العباد)(٤).", "- وقال ابن القيم: (الشريعة مبناها وأساسها على الحكم ومصالح العباد في المعاش والمعاد، وهي عدل كلها، ورحمة كلها، ومصالح كلها، وحكمة كلها فكل مسألة خرجت من العدل إلى الجور، وعن الرحمة إلى ضدها، وعن المصلحة إلى المفسدة، وعن الحكمة إلى العبث فليست من الشريعة وإن أدخلت فيها بالتأويل)(٥). المسألة الثانية: أن معيار المصلحة وميزانها على الحقيقة هو الشرع. فما شهد له الشرع بالفضل والصلاح فهو صالح، وما شهد له بالفساد فهو فاسد. يقول ابن", "(١) سورة الأنبياء: الآية ١٠٧.", "(٢) قواعد الأحكام ٩/١.", "(٣) منهاج السنة ١٤٧/١، ٢٤٠/٢.", "(٤) الموافقات ٦/٢ - ٣٧.", "(٥) أعلام الموقعين ١/٣."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0095.png"}, {"n": 96, "paras": ["تيمية: (اعتبار مقادير المصالح والمفاسد هو بميزان الشرع)(١) كما إن الإنسان عاجز عن الاستقلال بإدراك المصالح كلها فليس له من سبيل للتلبث بها إلا باتباع الوحي المنزل والاستنارة بنوره والوقوف عند حدوده ومعالمه. المسألة الثالثة:", "مصالح الدنيا معتبرة بمصالح الآخرة. يقول الشاطبي: (المصالح المجتلبة شرعاً، والمفاسد المستدفعة إنما تعتبر من حيث تمام الحياة الدنيا للحياة الأخرى، لا من حيث أهواء النفوس في جلب مصالحها العادية أو درء مفاسدها العادية)(٢) ويقول في موضع آخر: (لا يصح اعتبار مصلحة دنيوية تخل بمصالح الآخرة فما يخل بمصالح الآخرة غير موافق لمقصود الشرع فهو باطل)(٣) فالمطلوب أن تجعل الدنيا مطية للآخرة، ومزرعة لها ووسيلة تفضي إلى عقباها. فقد أراد الله الدنيا خادمة للآخرة لا أن تكون مزاحمة لها.", "أنواع المصالح: أ - مصالح معتبرة: اعتبرها الشارع ورتب أحكاماً لتحقيقها. وهي المصالح والمقاصد التي دل الاستقراء على أن الشريعة جاءت لرعايتها.", "١ - وهي إما ضرورية لازمة في قيام الدين والدنيا، وهي حفظ:", "- الدين: كالإيمان والعبادات.", "- النفس كالقصاص والديات.", "- العقل: كحد شارب الخمر.", "- المال: كالبيع والشراء.", "- النسل: كالزواج.", "(١) الفتاوى ١٢٩/٢٨.", "(٢) الموافقات ٣٨٤/٢.", "(٣) المصدر السابق بتصرف ٣٨٧/٢."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0096.png"}, {"n": 97, "paras": ["وأصول العبادات والعادات والمعاملات جاءت لحفظ هذه الضروريات.", "٢ - الثانية: الحاجية: وهي التي ويفتقر إليها من حيث التوسعة ورفع الحرج، ودفع المشقة. فشرعت لها الرخص عند المشقة، وشرع الطلاق من حياة زوجية لا تطاق ونحو ذلك.", "٣ - الثالثة: التحسينية: وهي التي ترجع إلى مكارم الأخلاق ومحاسن العادات: كالطهارات للبدن والثوب وستر العورة وأخذ الزينة عند كل مسجد، إذ لا يخل فقدانها بأمر ضروري. ولكنها جرت مجرى التحسين والتزيين(١).", "ب - مصالح ملغية: وتشمل سائر المصالح التي دل الشارع على أنها مصلحة ملغية، وصرح بعدم اعتبارها، ونهى عن تحصيلها كمصلحة المرابي التي ألغيت بنصوص تحريم الربا.", "ج - مصالح مرسلة: وهي المصالح التي لم يرد في الشرع على أنها معتبرة ولا على أنها ملغية. بل سكتت عنها النصوص. وقد أخذ بها كثير من العلماء. ومن أمثلتها جمع القرآن في مصحف واحد في عهد أبي بكر، وجمع عثمان القرآن وتحريق المصاحف القديمة وإلزام الناس بقراءة واحدة. وتدوين الدواوين، واتخاذ الصحابة السجون، وقتل الجماعة بالواحد وتضمين الصناع ما يهلك بأيديهم من أموال الناس، وحق ولي الأمر في فرائض الضرائب على الأغنياء عند الضرورة ونحو ذلك.", "وهي مصدر فقهي دل على اعتباره استقراء النصوص، وأحكام الكتاب والسنة وعمل فقهاء الصحابة. فالحوادث متجددة، والنصوص متناهية.", "(١) انظر رسالة البوطي في ضوابط المصلحة."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0097.png"}, {"n": 98, "paras": ["والتجارب في اضطراد وهي بذلك مهيع متسع لما يجد من أقضية، ويطرأ من أحوال.", "ضوابط العمل بها:", "١ - أن لا تعارض نصاً قطعياً من الكتاب أو قطعياً من صحيح السنة أو إجماعاً متيقناً، أو قياساً ظاهراً.", "٢ - أن تكون كلية لا جزئية.", "٣ - أن يغلب على الظن تحققها (حقيقة لا توهماً).", "٤ - أن تكون مندرجة في مقاصد الشرع: (الفورية أو الحاجية أو التحسينية).", "٥ - أن لا تفوت مصلحة أعظم منها، أو تؤدي إلى مفسدة أكبر منها. هذا وجه من وجوه المصالح المرسلة، وهناك وجه آخر من وجوه المصالح يؤخذ بها وإن صادمت نصاً إذ يكون تحصيلها من باب الضرورة. واعتبر الفقهاء هذا النوع من المصالح المرسلة إذا تحققت فيه الشروط التالية:", "١ - الكلية لا الجزئية.", "٢ - غلبة الظن الراجح.", "٣ - نشوء ضرر من تطبيق الحكم الأصلي. أي أن الضرر الناتج من تطبيق الحكم المنصوص عليه أكبر من الضرر الناتج من مخالفته وعدم إنفاذه.", "٤ - أن لا نتجاوز في مخالفة الحكم القدر اللازم لدرء الضرر فمتى زال الضرر يجب التوقف وإنفاذ الحكم الأصلي. لأن الحكم الشرعي أصل، واتباع المصلحة عند الضرورة استثناء ومثال هذا النوع من الاتباع المصلحي هو ما مثله الغزالي وابن تيمية من قتال الكفار المترسين بأسرى المسلمين. يعمدون على الإغارة على بيضة المسلمين فينهبون ويقتلون ثم يتحصنون بحصونهم."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0098.png"}, {"n": 99, "paras": ["ويتذرعون بأطفالهم وشيوخهم. فكان الجواب بجواز قتل المسلمين المتترس بهم مع أن قتلهم حرام، ولكن تركهم يؤدي إلى قتل عدد أكبر من المسلمين بيد الكفار فتعين هذا الطريق للوصول إليهم حماية لأرض الإسلام وتدميراً لحصون الكفر. وبهذه الشروط يكون قد اتضح الظرف الذي تعطى فيه الحركة الإسلامية حق اللجوء إلى اتباع مصلحي يخالف حكماً منصوصاً عليه.", "ثم إن المسائل السياسية التي تتصل بعقد الأحلاف، وإجراء الانتخابات ودخول المجالس النيابية ونحوها مندرجة في قاعدة المصالح المرسلة والسياسة الشرعية التي تنبثق من أصول الشريعة العامة وقواعدها الكلية ومقاصدها التشريعية.", "الأصل الثاني: رعاية الأعراف والعادات: أساس اعتبار الأعراف السليمة والعادات الصحيحة راجع إلى رعاية مصالح الناس ودفع المشقة ورفع الحرج عنهم، سواء كانت تلك الأعراف معدودة في المقاصد بالنسبة لتصرفاتهم أو معدودة في الوسائل والأسباب. فالشريعة أقرت جملة من الأحكام التي قد تعارف عليها العرب في الجاهلية كفرض الدية على العاقلة، وإقرار بعض المعاملات كالمضاربة، واشتراط الكفاءة في الزواج، وكسوة الكعبة ونحو ذلك مما كان محموداً في الجاهلية ومتفقاً مع محاسن العوائد ومكارم الأخلاق. وكذلك ما كان معتبراً في الوسائل كأساليب التعبير والتعامل كتعارف التجار على إثبات الديون في دفاترهم الخاصة من غير إشهاد(١). وكتعارفهم على البيع بالتعاطي دون استعمال الصيغة اللفظية في البيع وغير ذلك مما يصطلح عليه الناس في معاملاتهم وأحوالهم الاجتماعية. وفي مثل هذا قال الفقهاء (المعروف عرفاً كالمشروط شرطاً) فإذا ثبت أن مثل هذه العوائد والأعراف لا تبطل نصاً شرعياً، ولا تهدر مصلحة راجحة للأمة، أو تجر مفسدة فهي جائزة ومعتبرة.", "(١) انظر المدخل إلى الشريعة د. زيدان ص ٢٠٥ - ٢٠٧."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0099.png"}, {"n": 100, "paras": ["الأصل الثالث: تغير الحكم المصلحي بتغير الظروف والأحوال والعوائد والأعراف: الأحكام الشرعية نوعان:", "١ - نوع جاءت الشريعة لتثبيته وتوطيده بالنصوص الصريحة المحكمة وهذا القسم ثابت عبر الأجيال والأزمان ثبوت الجبال الراسيات لا يعتريه تبديل.", "٢ - النوع الثاني: هي الأحكام الاجتهادية التي يكون مصدرها قياس أو عرف أو مصلحة سكتت عنها النصوص أو عادة لم ينشئها حكم شرعي. فهذا النوع تجري عليه قاعدة (لا ينكر تغير الأحكام بتغير الزمان) فيمكن أن يتبدل فيه الحكم نظراً لطروء أحوال تغيرت فيها الأعراف وتبدلت فيها المصالح. يقول الشاطبي: (العوائد المستمرة ضربان: أحدهما: العوائد الشرعية التي أقرها الدليل الشرعي أو نفاها ومعنى ذلك أن يكون الشرع أمر بها إيجاباً أو ندباً أو نهى عنها كراهة أو تحريماً، أو أذن فيها فعلاً وتركاً. والثانية: هي العوائد الجارية بين الخلق بما ليس في نفيه وإثباته دليل شرعي. فأما الأول: فثابت أبداً كسائر الأمور الشرعية، فهي إما حسنة عند الشارع أو قبيحة. فإنها من جملة الأمور الداخلة في أحكام الشرع فلا تبديل لها. فلا يصح أن ينقلب الحسن فيها قبيحاً ولا القبيح حسناً إذ لو صح مثل هذا لكان نسخاً للأحكام المستقرة والنسخ بعد موت النبي ﷺ باطل فرفع العوائد الشرعية باطل)(١).", "(١) الموافقات ٢٨٣/٢ - ٢٨٥."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0100.png"}, {"n": 101, "paras": ["أما الثانية عند الشاطبي فهي العوائد المتبدلة التي لم تنشئها الشريعة أصلاً، ولم تتعرض لها بمدح ولا ذم، فهذه هي التي يؤثر تغيرها في أحكامها الشرعية، وضرب لها أمثلة بالعبارات التي يتعارف الناس في إنشاء العقود أو إنهائها في المعاملات المالية(١). يقول الدكتور الزرقاء: (من المقرر في فقه الشريعة أن لتغير الأوضاع والأحوال الزمنية تأثيراً في كثير من الأحكام الشرعية وعلى هذا الأساس أسست القاعدة الفقهية القائلة: (لا ينكر تغير الأحكام بتغير الزمان) وقد اتفقت كلمة فقهاء المذاهب على أن الأحكام التي تتبدل بتبدل الزمان واختلاف الناس هي الأحكام الاجتهادية من قياسية ومصلحية، وهي المعنية بالقاعدة الآنفة الذكر.", "أما الأحكام الأساسية التي جاء الشريعة لتأسيسها وتوطيدها بنصوصها الأصلية فهذه لا تتبدل بتبدل الزمان بل هي الأصول التي جاءت بها الشريعة لإصلاح الأزمان والأجيال(٢). لهذا نجد بعض الاختلافات بين فقهاء المذهب الواحد مردها إلى تغير الأعراف والعوائد. ويقول الفقهاء عن مثل هذا الاختلاف أنه: (اختلاف عصر وزمان، لا اختلاف حجة وبرهان). يقول القرافي: (الأحكام المترتبة على العادات تدور معها أينما دارت وتبطل معها إذا بطلت.", "وبهذا القانون تعتبر جميع الأحكام الشرعية المترتبة على العوائد، وهو تحقيق مجمع عليه بين العلماء(٣).", "(١) الموافقات ٢٨٣/٢ - ٢٨٥.", "(٢) مجلة المسلمون عدد ٨ ص ٨٩١. (٣) الفروق ١٧٦/١ وما بعدها."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0101.png"}, {"n": 102, "paras": ["فصل في بيان أنَّه لا يصحُّ أن يكونَ في الوجودِ إلَّا واجبٌ واحدٌ بالذاتِ", "اعلم أنَّه قد ثبتَ بالبرهانِ أنَّه لا يصحُّ أن يكونَ في الوجودِ إلَّا واجبٌ واحدٌ بالذاتِ، وهو اللهُ سبحانه وتعالى، وكلُّ ما سواه فهو ممكنٌ بالذاتِ، مفتقرٌ في وجودِهِ إلى غيرِهِ، وهو اللهُ تعالى.", "ويدلُّ على ذلكَ قوله تعالى: {لَوْ كَانَ فِيهِمَا آلِهَةٌ إِلَّا اللَّهُ لَفَسَدَتَا}، وقوله تعالى: {وَمَا كَانَ مَعَهُ مِنْ إِلَهٍ إِذًا لَّذَهَبَ كُلُّ إِلَهٍ بِمَا خَلَقَ وَلَعَلَا بَعْضُهُمْ عَلَى بَعْضٍ}.", "فلو كانَ هناكَ واجبانِ بالذاتِ، لكانَ كلُّ واحدٍ منهما مستقلاً بوجودِهِ، غنياً عن غيرِهِ، ولكانَ لكلٍّ منهما قدرةٌ وإرادةٌ، فلو أرادَ أحدهما شيئاً وأرادَ الآخرُ خلافَهُ، لزمَ إمَّا وقوعُ المرادينِ معاً، وهو محالٌ لتناقضِهما، أو وقوعُ أحدهما دونَ الآخرِ، فيكونُ العاجزُ عن تنفيذِ مرادِهِ ناقصاً، والناقصُ لا يكونُ إلهاً، أو عدمُ وقوعِهما معاً، فيكونانِ عاجزينِ، والعاجزُ لا يكونُ إلهاً.", "فثبتَ بذلكَ أنَّه لا بدَّ أن يكونَ الواجبُ بالذاتِ واحداً لا شريكَ لهُ، وهو اللهُ الواحدُ الأحدُ، الفردُ الصمدُ، الذي لم يلدْ ولم يولدْ، ولم يكنْ لهُ كفواً أحدٌ."], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0102.png"}, {"n": 103, "paras": ["الفهرس", "الموضوع | الصفحة --- | --- مقدمة | ٥ شرعية العمل الجماعي | ٧", "١ - الطلب الدال على وجوب الفعل | ٧", "٢ - الجماعة موضع للرحمة | ٨", "٣ - الاعتصام بها عصمة من الاجتماع على ضلالة | ٨", "٤ - إنها ميراث الرسل والأنبياء ومنهاجهم في البلاغ | ٩", "٥ - الحض على الإتحاد والتعاون على الخير | ١٠", "٦ - استجلاب عون الله ونصره وتأييده | ١٠", "٧ - في الجماعة حسن العاقبة وجميل المال وكريم العقبى | ١٠", "٨ - التحذير من مغبة التفرق وعاقبة التشتت بالتزام الجماعة | ١١", "٩ - مقام الخيرية والشهادة على الناس منوطان بها | ١١", "١٠ - وجوب الولاء لجماعة المؤمنين | ١٢", "١١ - لا قيام ببعض التكاليف إلا بها | ١٢ من شواهد السنة في الحض على لزوم الجماعة | ١٢ آثار السلف | ١٤ ومن أقوال أئمة العلم | ١٥ ومن القواعد الشرعية المرعية | ١٥ منطق الواقع | ١٦ ضرورة التحدي | ١٨ سنة الاجتماع الكونية | ١٨ معنى الجماعة المسلمة على أقوال | ٢٠ الترجيح على قولين | ٢٤ الأول | ٢٤"], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0103.png"}, {"n": 104, "paras": ["الثاني الخلاصة موقف الإخوان من الهيئات الإسلامية الفرق بين الإخوان والجماعات الإسلامية أسلوب معاملة المخالف موقفنا من الدعوات الأخرى تقرير الإمام الهضيبي عن مسلك الإمام البنا العملي منهج الجماعة بعد الإمام الشهيد البيعة في العمل الجماعي البيعة لغة واصطلاحاً البيعة في الإصطلاح مشروعية البيعة في العمل الجماعي", "١ - أنها عقد إمارة صغرى", "٢ - عقد على عمل مشروع", "٣ - عهد وميثاق الخلاصة صيغ عقد البيعة صفة عقد البيعة", "١ - الصيغة القولية", "٢ - الكتابة", "٣ - قرينة الحال معالم المنهج في العقيدة . سلفية في المنهج ، وسنية في الإتباع معالم المنهج في العقيدة عند الإمام البنا سمات منهجه في عرض العقيدة أولاً : اعتماده منهج القرآن الكريم والسنة المطهرة والسلف الصالح ثانياً : الاهتمام ببيان أثر العقيدة على النفوس ثالثاً : رد الشبهات العقائدية الحديثة رابعاً : اعتماده طريقي المعرفة ، النقلية والعقلية خامساً : تقوية الصلة بين الوجدان الإنساني والخالق جل وعلا سادساً : أخذه بمبدأ الشمول سابعاً : البعد عن مداحض التكفير ومزلة التضليل"], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0104.png"}, {"n": 105, "paras": ["٥٦ موضوع التوسل", "٥٨ مسألة التفويض في الأسماء والصفات وإنها من المتشابه", "٦٤ وسطية المنهج الفقهي بين دعاة المذهبية ومخالفيهم", "٦٤ الأول: فريق يوجب النظر على كل أحد", "٦٤ الثاني: فريق يوجب التقليد على كل أحد", "٦٤ الثالث: معتدل متوسط", "٦٥ أصناف الناس ومراتبهم", "٦٧ الضوابط العامة لمسألة التقليد", "٧٠ القواعد الكلية والآداب المرعية عند الإختلاف والتنازع", "٧١ قواعد كلية عند الاختلاف", "٧٨ نظرة موضوعية حول مسألة التصوف", "٧٨ نظرة الإمام البنا إلى التصوف", "٨١ منهجية متوازنة في معالجة التصوف", "٨٣ الخلاصة", "٨٥ فقه الأمر بالمعروف وقواعد الإنكار", "٨٧ مقامات المنكر وتنوع أهله", "٨٨ تنوع أهل المنكر", "٨٩ من يملك إعطاء وصف المنكر", "٨٩ شروط المنكر", "٩٠ درجات إنكار المنكر", "٩١ الشواهد الشرعية لهذه القاعدة", "٩٤ السياسة الشرعية وضوابط العمل السياسي", "٩٤ الأصل الأول", "٩٦ أنواع المصالح", "٩٨ ضوابط العمل بها", "٩٩ الأصل الثاني: رعاية الأعراف والعادات", "١٠٠ الأصل الثالث: تغير الحكم المصلحي بتغير الظروف والأحوال والعوائد والأعراف"], "img": "../../../_ocr-work/libocr/sharh-adwa/pages/0105.png"}]};
